/* ---------------- text utilities ---------------- */

final RegExp _ws = RegExp(r'\s');
final RegExp _nonWs = RegExp(r'\S');
final RegExp _punctQuote = RegExp(r'[，。；：、]');

double cnNum(Object? v) {
  if (v == null) return double.nan;
  final s = v
      .toString()
      .trim()
      .replaceAll(RegExp(r'[〇零]'), '零')
      .replaceAll(RegExp(r'[，,\s]'), '');
  if (RegExp(r'^\d+(?:\.\d+)?$').hasMatch(s)) return double.parse(s);
  const digits = {
    '零': 0,
    '一': 1,
    '二': 2,
    '两': 2,
    '三': 3,
    '四': 4,
    '五': 5,
    '六': 6,
    '七': 7,
    '八': 8,
    '九': 9,
  };
  const units = {'十': 10, '百': 100, '千': 1000, '万': 10000};
  var total = 0;
  var section = 0;
  var number = 0;
  var seen = false;
  for (final ch in s.split('')) {
    if (digits.containsKey(ch)) {
      number = digits[ch]!;
      seen = true;
    } else if (units.containsKey(ch)) {
      seen = true;
      if (ch == '万') {
        section = (section + number) * 10000;
        total += section;
        section = 0;
        number = 0;
      } else {
        section += (number == 0 ? 1 : number) * units[ch]!;
        number = 0;
      }
    } else {
      return double.nan;
    }
  }
  return seen ? (total + section + number).toDouble() : double.nan;
}

String jsNum(num v) {
  if (v is int) return v.toString();
  final d = v.toDouble();
  if (d.isNaN) return 'NaN';
  if (d.isInfinite) return d > 0 ? 'Infinity' : '-Infinity';
  if (d == d.roundToDouble() && d.abs() < 1e21) return d.round().toString();
  return d.toString();
}

String fmtYuan(Object? n) {
  final v = n is num ? n.toDouble() : 0.0;
  if (v.isNaN) return 'NaN';
  var s = jsNum(v);
  final negative = s.startsWith('-');
  if (negative) s = s.substring(1);
  final dot = s.indexOf('.');
  var intPart = dot < 0 ? s : s.substring(0, dot);
  final decPart = dot < 0 ? '' : s.substring(dot);
  final buf = StringBuffer();
  for (var i = 0; i < intPart.length; i++) {
    if (i > 0 && (intPart.length - i) % 3 == 0) buf.write(',');
    buf.write(intPart[i]);
  }
  return '${negative ? '-' : ''}$buf$decPart';
}

String fmtWan(Object? n) {
  final v = n is num ? n.toDouble() : 0.0;
  if (v == 0 || v.isNaN) return '';
  if (v >= 10000 && v % 10000 == 0) return '${jsNum(v / 10000)} 万元';
  return '${fmtYuan(v)} 元';
}

double? parseAmount(String? str) {
  final compact = (str ?? '').replaceAll(RegExp(r'[，,\s]'), '');
  var m = RegExp(r'(?:人民币|RMB|¥|￥)?(\d+(?:\.\d+)?)(万元|万|千元|千|元)')
      .firstMatch(compact);
  if (m != null) {
    var n = double.tryParse(m.group(1)!);
    if (n == null || !n.isFinite) return null;
    final unit = m.group(2)!;
    if (unit.startsWith('万')) {
      n *= 10000;
    } else if (unit.startsWith('千')) {
      n *= 1000;
    }
    return n;
  }
  m = RegExp(r'([一二两三四五六七八九十百千万零〇]+)(万元|万|千元|千|元)').firstMatch(compact);
  if (m != null) {
    var n = cnNum(m.group(1));
    if (!n.isFinite) return null;
    final unit = m.group(2)!;
    if (unit.startsWith('万')) {
      n *= 10000;
    } else if (unit.startsWith('千')) {
      n *= 1000;
    }
    return n;
  }
  return null;
}

double? parsePercent(String? str) {
  final s = str ?? '';
  var m = RegExp(r'(\d+(?:\.\d+)?)\s*[%％]').firstMatch(s);
  if (m != null) return double.parse(m.group(1)!);
  m = RegExp(r'百分之\s*([一二两三四五六七八九十百零〇\d]+)').firstMatch(s);
  if (m != null) {
    final n = cnNum(m.group(1));
    return n.isFinite ? n : null;
  }
  return null;
}

/// 合同签署日期，返回 yyyymmdd；用于判断能否套用 2026-08-01 施行的新规。
int? contractDateKey(String text) {
  final m = RegExp(
    r'(20\d{2})\s*[年\-/.]\s*(\d{1,2})\s*[月\-/.]\s*(\d{1,2})\s*日?',
  ).firstMatch(text);
  if (m == null) return null;
  return int.parse(m.group(1)!) * 10000 +
      int.parse(m.group(2)!) * 100 +
      int.parse(m.group(3)!);
}

bool _isPunct(String ch) => ch.isNotEmpty && _punctQuote.hasMatch(ch);

String clipQuote(String? q, [int? focusStart, int? focusEnd]) {
  final s = (q ?? '').trim();
  const maxLen = 60;
  if (s.length <= maxLen) return s;
  final fs = focusStart != null ? focusStart.clamp(0, s.length) : 0;
  var fe = focusEnd != null
      ? focusEnd.clamp(fs, s.length)
      : (fs + 1).clamp(0, s.length);
  const budget = maxLen - 4;
  var start = 0;
  final maxStart = s.length - budget;
  start = (fe - 46).clamp(0, maxStart);
  if (start > 0) {
    var p = start;
    final cap = [s.length, start + 22, fs].reduce((a, b) => a < b ? a : b);
    while (p < cap && !_isPunct(s[p - 1])) {
      p++;
    }
    if (p <= fs && p > 0 && _isPunct(s[p - 1])) start = p;
  }
  var end = (start + budget) < s.length ? start + budget : s.length;
  if (end < s.length && end > fe) {
    var p = end;
    final floor = fe > start + 16 ? fe : start + 16;
    while (p > floor && !_isPunct(s[p - 1])) {
      p--;
    }
    if (p > fe && p > 0 && _isPunct(s[p - 1])) end = p;
  }
  final lead = start > 0;
  final trail = end < s.length;
  final bodyBudget = maxLen - (lead ? 2 : 0) - (trail ? 2 : 0);
  if (end - start > bodyBudget) end = start + bodyBudget;
  var out = s.substring(start, end);
  if (lead) out = '……$out';
  if (trail) out = '$out……';
  return out;
}

class _Sentence {
  final String quote;
  final int start;
  final int end;
  final int matchStart;
  final int matchEnd;
  _Sentence(this.quote, this.start, this.end, this.matchStart, this.matchEnd);
}

_Sentence? sentenceOf(String text, RegExp re) {
  final m = re.firstMatch(text);
  if (m == null) return null;
  var s = m.start;
  var e = m.end;
  final stop = RegExp(r'[。；！？\n]');
  var guard = 0;
  while (s > 0 && !stop.hasMatch(text[s - 1]) && guard++ < 600) {
    s--;
  }
  guard = 0;
  while (e < text.length && !stop.hasMatch(text[e]) && guard++ < 600) {
    e++;
  }
  if (e < text.length && RegExp(r'[。；！？]').hasMatch(text[e])) e++;
  while (s < e && _ws.hasMatch(text[s])) {
    s++;
  }
  while (e > s && _ws.hasMatch(text[e - 1])) {
    e--;
  }
  final matchStart = (m.start - s).clamp(0, e - s);
  final matchEnd = (m.end - s).clamp(matchStart, e - s);
  return _Sentence(text.substring(s, e), s, e, matchStart, matchEnd);
}

class _Span {
  final String quote;
  final int start;
  final int end;
  _Span(this.quote, this.start, this.end);
}

List<_Span> sentenceList(String? text) {
  final s = text ?? '';
  final list = <_Span>[];
  var start = 0;
  for (var i = 0; i <= s.length; i++) {
    final atEnd = i == s.length;
    final ch = atEnd ? '' : s[i];
    if (atEnd || ch == '。' || ch == '；' || ch == '\n') {
      final raw = s.substring(start, i).trim();
      if (raw.isNotEmpty) {
        final leadM = _nonWs.firstMatch(s.substring(start, i));
        final st = start + (leadM == null ? 0 : leadM.start);
        list.add(_Span(raw, st, st + raw.length));
      }
      start = i + 1;
    }
  }
  return list;
}

List<_Span> commaParts(String? text) {
  final s = text ?? '';
  final out = <_Span>[];
  var start = 0;
  for (var i = 0; i <= s.length; i++) {
    final atEnd = i == s.length;
    final ch = atEnd ? '' : s[i];
    if (atEnd || ch == '，' || ch == ',') {
      final raw = s.substring(start, i).trim();
      if (raw.isNotEmpty) {
        final leadM = _nonWs.firstMatch(s.substring(start, i));
        final st = start + (leadM == null ? 0 : leadM.start);
        out.add(_Span(raw, st, st + raw.length));
      }
      start = i + 1;
    }
  }
  return out;
}

double? parseProbation(String? text) {
  final s = text ?? '';
  var m = RegExp(
    r'试用期(?:限|期限|时间)?\s*(?:为|是|：|:|共)?\s*(\d{1,3}|[一二两三四五六七八九十]{1,4})\s*(?:至|到|—|-|~|～)\s*(\d{1,3}|[一二两三四五六七八九十]{1,4})\s*个?月',
  ).firstMatch(s);
  if (m != null) {
    final a = cnNum(m.group(1));
    final b = cnNum(m.group(2));
    if (a.isFinite && b.isFinite && b > 0) return a > b ? a : b;
  }
  m = RegExp(
    r'试用期(?:限|期限|时间)?\s*(?:为|是|：|:|共)?\s*(\d{1,3}|[一二两三四五六七八九十]{1,4})\s*个?月',
  ).firstMatch(s);
  if (m != null) {
    final n = cnNum(m.group(1));
    if (n.isFinite && n > 0) return n;
  }
  m = RegExp(r'试用期(?:限|期限|时间)?\s*(?:为|是|：|:|共)?\s*半年').firstMatch(s);
  if (m != null) return 6;
  m = RegExp(
    r'试用期[^。；\n]{0,30}?(?:自\s*)?(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日[\s\S]{0,12}?至\s*(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日',
  ).firstMatch(s);
  if (m != null) {
    final d1 = DateTime(
      int.parse(m.group(1)!),
      int.parse(m.group(2)!),
      int.parse(m.group(3)!),
    );
    final d2 = DateTime(
      int.parse(m.group(4)!),
      int.parse(m.group(5)!),
      int.parse(m.group(6)!),
    );
    final months =
        (d2.difference(d1).inMilliseconds / (1000 * 60 * 60 * 24 * 30.4375))
            .round();
    if (months > 0) return months.toDouble();
  }
  return null;
}

class TermMonths {
  final int months;
  final String label;
  TermMonths(this.months, this.label);
}

TermMonths? parseTermMonths(String? text) {
  final s = text ?? '';
  var m = RegExp(
    r'(?:自\s*)?(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日[\s\S]{0,16}?至\s*(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日',
  ).firstMatch(s);
  m ??= RegExp(
    r'(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})[\s\S]{0,12}?(?:至|到|—|-)[\s\S]{0,4}?(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})',
  ).firstMatch(s);
  if (m != null) {
    final d1 = DateTime(
      int.parse(m.group(1)!),
      int.parse(m.group(2)!),
      int.parse(m.group(3)!),
    );
    final d2 = DateTime(
      int.parse(m.group(4)!),
      int.parse(m.group(5)!),
      int.parse(m.group(6)!),
    );
    final months =
        (d2.difference(d1).inMilliseconds / (1000 * 60 * 60 * 24 * 30.4375))
            .round();
    if (months > 0) {
      final label = months >= 11.5
          ? '${jsNum(months / 12 < 0.5 ? 1 : (months / 12).round())} 年'
          : '${months < 1 ? 1 : months} 个月';
      return TermMonths(months, label);
    }
  }
  m = RegExp(
    r'(?:合同期限|合同期|劳动合同期限|期限|有效期)(?:为|是|：|:)?\s*([一二两三四五六七八九十\d]{1,3})\s*年',
  ).firstMatch(s);
  if (m != null) {
    final y = cnNum(m.group(1));
    if (y > 0) return TermMonths((y * 12).round(), '${jsNum(y)} 年');
  }
  m = RegExp(
    r'(?:合同期限|合同期|劳动合同期限|期限|有效期)(?:为|是|：|:)?\s*([一二两三四五六七八九十\d]{1,3})\s*个?月',
  ).firstMatch(s);
  if (m != null) {
    final mo = cnNum(m.group(1));
    if (mo > 0) return TermMonths(mo.round(), '${jsNum(mo)} 个月');
  }
  return null;
}

TermMonths? parseContractTerm(String? text) {
  final t = text ?? '';
  final noFixed = t
      .split(RegExp(r'[。；\n]'))
      .where(
        (s) =>
            RegExp(r'无固定期限').hasMatch(s) &&
            RegExp(r'(本合同|合同期限|期限为|约定为|订立|签订)').hasMatch(s) &&
            !RegExp(r'(可以|可订立|协商|续订|再次|期满后)').hasMatch(s),
      )
      .toList();
  if (noFixed.isNotEmpty) return TermMonths(9999, '无固定期限');
  if (RegExp(r'以完成一定工作任务为期限').hasMatch(t)) return TermMonths(0, '以完成一定工作任务为期限');
  final parts = t
      .split(RegExp(r'[\n。；]'))
      .map((s) => s.trim())
      .where((s) => s.isNotEmpty)
      .toList();
  final nonProbation = parts
      .where((s) => !RegExp(r'(试用期|实习期|培训期)').hasMatch(s))
      .toList();
  final groups = <List<Object>>[
    [RegExp(r'(合同期限|劳动合同期限|合同期|合同有效期|本协议有效期|协议有效期|实习期限|实习期|协议期限)'), parts],
    [RegExp(r'期限'), nonProbation],
    [RegExp(r'自\s*\d{4}\s*年|(\d{4})[-/.]\d{1,2}[-/.]\d{1,2}'), nonProbation],
  ];
  for (final group in groups) {
    final re = group[0] as RegExp;
    final list = group[1] as List<String>;
    for (final s in list) {
      if (!re.hasMatch(s)) continue;
      final term = parseTermMonths(s);
      if (term != null) return term;
    }
  }
  if (RegExp(r'(合同期限|劳动合同期限|合同期|合同有效期)').hasMatch(t)) {
    final term = parseTermMonths(t);
    if (term != null) return term;
  }
  return null;
}

class Clause {
  final String kind;
  final String heading;
  final String body;
  final String text;
  final int start;
  final int end;
  final bool numbered;
  final int index;

  Clause({
    required this.kind,
    required this.heading,
    required this.body,
    required this.text,
    required this.start,
    required this.end,
    required this.numbered,
    required this.index,
  });

  String get full => '${heading.isNotEmpty ? '$heading\n' : ''}$body';
}

class _Heading {
  final int index;
  final int length;
  final String style;
  _Heading(this.index, this.length, this.style);
}

List<_Heading> findClauseHeadings(String text) {
  final out = <_Heading>[];
  final seen = <int>{};
  void add(int index, int length, String style) {
    if (index < 0 || seen.contains(index)) return;
    seen.add(index);
    out.add(_Heading(index, length, style));
  }

  final article = RegExp(r'第[一二三四五六七八九十百零〇\d]+条');
  for (final m in article.allMatches(text)) {
    final i = m.start;
    final before = text.substring(i - 8 < 0 ? 0 : i - 8, i);
    final atStart =
        i == 0 ||
        RegExp(r'(^|\n)[ \t　]*$').hasMatch(before) ||
        RegExp(r'[。；][ \t　]*$').hasMatch(before);
    if (!atStart) continue;
    final afterEnd = i + m.group(0)!.length;
    final after = afterEnd < text.length ? text[afterEnd] : '';
    final afterFew = text.substring(
      afterEnd,
      afterEnd + 8 > text.length ? text.length : afterEnd + 8,
    );
    if (RegExp(r'[款项项目]').hasMatch(after)) continue;
    final afterIsPunct =
        after.isNotEmpty && RegExp(r'[ \t　、：:．.]').hasMatch(after);
    if (!afterIsPunct && RegExp(r'^(规定|约定|的约定|之规定|所称)').hasMatch(afterFew)) {
      continue;
    }
    final lineEnd = text.indexOf('\n', i);
    final lineLen = (lineEnd < 0 ? text.length : lineEnd) - i;
    if (!afterIsPunct && lineLen > 32) continue;
    add(i, m.group(0)!.length, 'article');
  }
  final list = RegExp(r'(^|\n)[ \t　]*([一二三四五六七八九十]+、|\d{1,2}[.、．])');
  for (final m in list.allMatches(text)) {
    final group2 = m.group(2)!;
    final idx = m.start + m.group(0)!.indexOf(group2);
    final probe = idx + group2.length < text.length
        ? text[idx + group2.length]
        : '';
    if (RegExp(r'\d').hasMatch(probe)) continue;
    add(idx, group2.length, 'list');
  }
  out.sort((a, b) => a.index - b.index);
  return out;
}

List<Clause> extractClauses(String text) {
  final raw = text.replaceAll(RegExp(r'\r\n?'), '\n');
  final headings = findClauseHeadings(raw);
  final groups = <Clause>[];
  if (headings.isNotEmpty) {
    final first = headings[0].index;
    final pre = raw.substring(0, first).trim();
    if (pre.isNotEmpty) {
      groups.add(
        Clause(
          kind: 'preamble',
          heading: '',
          body: pre,
          text: pre,
          start: 0,
          end: first,
          numbered: false,
          index: 0,
        ),
      );
    }
    for (var i = 0; i < headings.length; i++) {
      final h = headings[i];
      final start = h.index;
      final end = i + 1 < headings.length ? headings[i + 1].index : raw.length;
      final seg = raw.substring(start, end);
      if (seg.trim().isEmpty) continue;
      final lineEnd = raw.indexOf('\n', start);
      final hasNewline = lineEnd >= 0 && lineEnd < end;
      final firstLineEnd = hasNewline ? lineEnd : end;
      final firstLine = raw.substring(start, firstLineEnd).trim();
      String heading;
      String body;
      if (hasNewline &&
          firstLine.length <= 28 &&
          !RegExp(r'[。；]').hasMatch(firstLine)) {
        heading = firstLine;
        body = raw
            .substring(firstLineEnd, end)
            .replaceFirst(RegExp(r'^\n+'), '')
            .trim();
      } else if (!hasNewline) {
        final restRaw = raw.substring(start + h.length, end);
        final titleM = RegExp(r'^[\s\u3000]*([^。；：:\n]{1,14})[：:]')
            .firstMatch(restRaw);
        heading =
            raw.substring(start, start + h.length).trim() +
            (titleM != null ? ' ${titleM.group(1)!.trim()}' : '');
        body = (titleM != null ? restRaw.substring(titleM.end) : restRaw)
            .replaceFirst(RegExp(r'^[\s\u3000：:、.．]+'), '')
            .trim();
      } else {
        heading = raw.substring(start, start + h.length).trim();
        body = raw
            .substring(start + h.length, end)
            .replaceFirst(RegExp(r'^[\s\u3000]+'), '')
            .trim();
      }
      groups.add(
        Clause(
          kind: 'clause',
          heading: heading,
          body: body,
          text: seg.trim(),
          start: start,
          end: end,
          numbered: true,
          index: groups.length,
        ),
      );
    }
  } else {
    final parts = <_Span>[];
    var start = 0;
    final re = RegExp(r'\n[ \t　]*\n+');
    for (final m in re.allMatches(raw)) {
      final seg = raw.substring(start, m.start);
      if (seg.trim().isNotEmpty) parts.add(_Span(seg.trim(), start, m.start));
      start = m.end;
    }
    final last = raw.substring(start);
    if (last.trim().isNotEmpty) {
      parts.add(_Span(last.trim(), start, raw.length));
    }
    if (parts.length <= 1) {
      final body = raw.trim();
      if (body.isNotEmpty) {
        groups.add(
          Clause(
            kind: 'body',
            heading: '',
            body: body,
            text: body,
            start: 0,
            end: raw.length,
            numbered: false,
            index: 0,
          ),
        );
      }
    } else {
      for (final p in parts) {
        groups.add(
          Clause(
            kind: 'body',
            heading: '',
            body: p.quote,
            text: p.quote,
            start: p.start,
            end: p.end,
            numbered: false,
            index: groups.length,
          ),
        );
      }
    }
  }
  return groups;
}

String clauseLabel(Clause clause, int fallbackIndex) {
  final h = clause.heading.trim();
  if (h.isNotEmpty) return h.length > 28 ? '${h.substring(0, 28)}…' : h;
  return fallbackIndex == 0 ? '文首' : '第 ${fallbackIndex + 1} 段';
}

String detectDocType(String? text) {
  final t = text ?? '';
  final firstLines = t
      .split('\n')
      .map((s) => s.trim())
      .where((s) => s.isNotEmpty)
      .take(5)
      .join('\n');
  final score = {
    'labor': 0,
    'intern': 0,
    'three-party': 0,
    'loan': 0,
    'prepay': 0,
  };
  void add(String key, int n) => score[key] = score[key]! + n;

  if (RegExp(r'(毕业生就业协议|三方协议|三方协议书|就业协议书)').hasMatch(firstLines)) {
    add('three-party', 9);
  } else if (RegExp(r'(三方|就业协议)').hasMatch(firstLines)) {
    add('three-party', 5);
  }
  if (RegExp(r'劳动合同').hasMatch(firstLines)) add('labor', 8);
  if (RegExp(r'(实习协议|实习合同|实习协议书)').hasMatch(firstLines)) {
    add('intern', 8);
  } else if (RegExp(r'实习').hasMatch(firstLines) &&
      RegExp(r'(协议|合同)').hasMatch(firstLines)) {
    add('intern', 4);
  }
  if (RegExp(r'(培训贷|教育分期|分期贷款|助学贷款|培训分期|学费分期)').hasMatch(firstLines)) {
    add('loan', 7);
  } else if (RegExp(r'(培训|教育|课程|学员|学费)').hasMatch(firstLines) &&
      RegExp(r'(分期|贷款|还款|月供|服务费|利息)').hasMatch(firstLines)) {
    add('loan', 3);
  }
  if (RegExp(r'(课程服务协议|课程购买协议|培训服务协议|培训合同|课程合同|预付式|课时服务|课程订单)')
      .hasMatch(firstLines)) {
    add('prepay', 8);
  } else if (RegExp(r'(课程|课时|学员|学费|课程费|培训班)').hasMatch(firstLines) &&
      RegExp(r'(退费|退款|不退|开课|上课|课时|迁址|转班)').hasMatch(firstLines)) {
    add('prepay', 5);
  }

  if (RegExp(r'(三方协议|三方协议书|毕业生就业协议|就业协议书)').hasMatch(t)) add('three-party', 4);
  if (RegExp(r'毕业生').hasMatch(t) && RegExp(r'(学校|用人单位)').hasMatch(t)) {
    add('three-party', 3);
  }
  if (RegExp(r'(实习协议|实习合同|实习单位|实习学生)').hasMatch(t)) add('intern', 4);
  if (RegExp(r'(实习期|实习补贴|实习岗位|实习证明)').hasMatch(t)) add('intern', 2);
  if (RegExp(r'(劳动合同|劳动者|用人单位)').hasMatch(t)) add('labor', 3);
  if (RegExp(r'(试用期|工作岗位|劳动报酬|社会保险|竞业限制|服务期)').hasMatch(t)) add('labor', 2);
  if (RegExp(r'(甲方（用人单位）|乙方（劳动者）|甲方\(用人单位\)|乙方\(劳动者\))').hasMatch(t)) {
    add('labor', 3);
  }
  if (RegExp(r'(分期|贷款|放款|还款|月供|平台服务费)').hasMatch(t)) add('loan', 3);
  if (RegExp(r'(培训费|课程|学员|培训机构|教育科技|学费)').hasMatch(t)) add('loan', 3);
  if (RegExp(r'(贷款|借款|分期)[^。；\n]{0,20}(协议|合同)').hasMatch(t)) add('loan', 2);
  if (RegExp(r'(课程|课时|培训班|学员|学费|课程费)').hasMatch(t) &&
      RegExp(r'(退费|退款|不退|不予退还|开课|上课|课时|转班|迁址)').hasMatch(t)) {
    add('prepay', 4);
  }
  if (RegExp(r'(预付|预收|预交|一次性(?:支付|收取|付款))').hasMatch(t) &&
      RegExp(r'(课程|课时|培训|学费|课程费)').hasMatch(t)) {
    add('prepay', 3);
  }

  if (RegExp(r'(不构成劳动关系|不属于劳动关系|实习关系)').hasMatch(t)) add('labor', -2);
  if (RegExp(r'(劳务(协议|合同)|承揽合同)').hasMatch(firstLines) &&
      !RegExp(r'劳动合同').hasMatch(firstLines)) {
    score['labor'] = 0;
  }
  if (RegExp(r'(房租|租赁|买卖|装修|运输|委托)').hasMatch(firstLines) &&
      !RegExp(r'(劳动|实习|培训|就业)').hasMatch(firstLines)) {
    return 'other';
  }

  final coreFinancing = RegExp(r'(培训贷|分期|贷款|放款|还款|月供|利息|征信)').hasMatch(t);
  if (!coreFinancing) score['loan'] = 0;
  if (score['loan']! > 0 && !RegExp(r'(培训|教育|课程|学员|学费|技能)').hasMatch(t)) {
    score['loan'] = 0;
  }
  // 有分期/贷款/月供时优先按培训贷处理，避免把贷款合同误判成纯预付课程。
  if (coreFinancing) score['prepay'] = score['prepay']! - 4;
  final prepayRefund =
      RegExp(r'(课程|课时|培训班|学员|学费|课程费)').hasMatch(t) &&
      RegExp(r'(退费|退款|不退|不予退还|开课|上课|课时|转班|迁址)').hasMatch(t);
  if (!prepayRefund) {
    score['prepay'] = score['prepay']! < 0 ? score['prepay']! : 0;
  }

  const order = ['labor', 'intern', 'three-party', 'loan', 'prepay'];
  final ranked = order.toList()
    ..sort((a, b) {
      final diff = score[b]! - score[a]!;
      if (diff != 0) return diff;
      return order.indexOf(a) - order.indexOf(b);
    });
  final best = ranked[0];
  if (score[best]! < 3) return 'other';
  return best;
}

bool looksLikeContract(String text) {
  final t = text.trim();
  if (t.length < 12) return false;
  final hasPair = RegExp(r'甲方|乙方').hasMatch(t);
  final hasTerms = RegExp(r'第[一二三四五六七八九十百零〇\d]+条').hasMatch(t);
  final hasAgreement = RegExp(r'协议|合同|条款').hasMatch(t);
  return hasPair || hasTerms || (hasAgreement && t.length > 60);
}

String guessTextKind(String text) {
  if (text.trim().isEmpty) return '空白文本';
  if (RegExp(r'简历|教育经历|项目经历|技能特长|求职意向').hasMatch(text)) return '简历';
  if (RegExp(r'招聘|岗位职责|任职要求|投递简历|面试安排').hasMatch(text)) return '招聘信息';
  if (RegExp(r'通知|会议|放假|安排如下').hasMatch(text)) return '一则通知';
  if (RegExp(r'老师|同学|作业|考试安排').hasMatch(text)) return '聊天或校内消息';
  return '一段普通文本';
}

/* ---------------- analysis engine ---------------- */

class QuoteRef {
  final String quote;
  final String raw;
  final int? start;
  final int? end;
  final bool headingOnly;
  QuoteRef(
    this.quote,
    this.raw, {
    this.start,
    this.end,
    this.headingOnly = false,
  });
}

class Finding {
  final String id;
  final String ruleId;
  final String ruleName;
  final Verdict verdict;
  final String short;
  final int? clauseIndex;
  final String location;
  final String quote;
  final QuoteRef? range;
  final String consequence;
  final LawRef? basis;
  final String ask;
  final String counter;
  final String confidence;
  final double loss;
  final int seq;
  Finding({
    required this.id,
    required this.ruleId,
    required this.ruleName,
    required this.verdict,
    required this.short,
    required this.clauseIndex,
    required this.location,
    required this.quote,
    required this.range,
    required this.consequence,
    required this.basis,
    required this.ask,
    required this.counter,
    required this.confidence,
    required this.loss,
    required this.seq,
  });
}

class Analysis {
  final String docKey;
  final String docType;
  final String detectedDocKey;
  final String detectedDocType;
  final bool forced;
  final List<String> packs;
  final List<String> packLabels;
  final List<String> extraPackLabels;
  final String title;
  final List<Clause> clauses;
  final int numberedCount;
  final int clauseCount;
  final int charCount;
  final List<Finding> items;
  final Map<Verdict, int> counts;
  final List<String> pending;
  final String oneLiner;
  final Verdict topVerdict;
  final bool insufficient;

  Analysis({
    required this.docKey,
    required this.docType,
    required this.detectedDocKey,
    required this.detectedDocType,
    required this.forced,
    required this.packs,
    required this.packLabels,
    required this.extraPackLabels,
    required this.title,
    required this.clauses,
    required this.numberedCount,
    required this.clauseCount,
    required this.charCount,
    required this.items,
    required this.counts,
    required this.pending,
    required this.oneLiner,
    required this.topVerdict,
    required this.insufficient,
  });

  int countOf(Verdict v) => counts[v] ?? 0;
}

class _Ctx {
  final String text;
  final List<Clause> clauses;
  final String docType;
  final String detectedKey;
  final List<String> packs;
  List<Finding> items = [];
  List<String> pending = [];
  final Map<String, int> seq = {};
  int step = 0;
  _Ctx(this.text, this.clauses, this.docType, this.detectedKey, this.packs);
}

QuoteRef? qFor(Clause clause, RegExp re) {
  final body = clause.body;
  final s = sentenceOf(body, re);
  if (s == null || s.quote.isEmpty) return null;
  return QuoteRef(
    clipQuote(s.quote, s.matchStart, s.matchEnd),
    s.quote,
    start: s.start,
    end: s.end,
  );
}

QuoteRef? qAny(Clause clause, RegExp re) {
  final q = qFor(clause, re);
  if (q != null) return q;
  if (clause.heading.isNotEmpty) {
    final s = sentenceOf(clause.heading, re);
    if (s != null && s.quote.isNotEmpty) {
      return QuoteRef(
        clipQuote(s.quote, s.matchStart, s.matchEnd),
        s.quote,
        headingOnly: true,
      );
    }
  }
  return null;
}

QuoteRef? qFilter(Clause clause, RegExp re, [Object? exclude]) {
  final list = sentenceList(clause.body);
  for (final s in list) {
    final bool excluded = exclude is bool Function(String)
        ? exclude(s.quote)
        : (exclude is RegExp ? exclude.hasMatch(s.quote) : false);
    if (excluded) continue;
    final m = re.firstMatch(s.quote);
    if (m != null) {
      return QuoteRef(
        clipQuote(s.quote, m.start, m.end),
        s.quote,
        start: s.start,
        end: s.end,
      );
    }
  }
  if (exclude != null) return null;
  return qFor(clause, re);
}

double? amountNear(String text, RegExp re) {
  final s = text;
  final m = re.firstMatch(s);
  if (m == null) return parseAmount(s);
  final winStart = m.start - 12 < 0 ? 0 : m.start - 12;
  final winEnd = m.start + 64 > s.length ? s.length : m.start + 64;
  final win = s.substring(winStart, winEnd);
  final v = parseAmount(win);
  return (v != null && v != 0) ? v : parseAmount(s);
}

double? maxAmountAfter(String text, RegExp re) {
  final s = text;
  double? max;
  for (final m in RegExp(re.pattern).allMatches(s)) {
    final v = parseAmount(s.substring(m.start));
    if (v != null && (max == null || v > max)) max = v;
  }
  return max;
}

class _ItemData {
  final String ruleId;
  final String? base;
  final Verdict verdict;
  final String ruleName;
  final String short;
  final int? clauseIndex;
  final String location;
  final String quote;
  final QuoteRef? range;
  final String consequence;
  final LawRef? basis;
  final String ask;
  final String counter;
  final String confidence;
  final double loss;
  _ItemData({
    required this.ruleId,
    this.base,
    required this.verdict,
    required this.ruleName,
    required this.short,
    this.clauseIndex,
    this.location = '全文',
    this.quote = '',
    this.range,
    this.consequence = '',
    this.basis,
    this.ask = '',
    this.counter = '',
    this.confidence = '中',
    this.loss = 0,
  });
}

void _addItem(_Ctx ctx, _ItemData d) {
  if (d.clauseIndex != null && d.ruleId.isNotEmpty && d.ruleName.isNotEmpty) {
    final dup = ctx.items.any(
      (it) =>
          it.clauseIndex == d.clauseIndex &&
          it.ruleId == d.ruleId &&
          it.ruleName == d.ruleName,
    );
    if (dup) return;
  }
  if (d.verdict != Verdict.green && d.clauseIndex != null) {
    ctx.items.removeWhere(
      (it) => it.verdict == Verdict.green && it.clauseIndex == d.clauseIndex,
    );
  }
  final base = d.base ?? d.ruleId.split('-').first;
  ctx.seq[base] = (ctx.seq[base] ?? 0) + 1;
  final id = '$base-${ctx.seq[base].toString().padLeft(2, '0')}';
  ctx.items.add(
    Finding(
      id: id,
      ruleId: d.ruleId,
      ruleName: d.ruleName,
      verdict: d.verdict,
      short: d.short,
      clauseIndex: d.clauseIndex,
      location: d.location,
      quote: d.quote,
      range: d.range,
      consequence: d.consequence,
      basis: d.basis,
      ask: d.ask,
      counter: d.counter,
      confidence: d.confidence,
      loss: d.loss,
      seq: ctx.step++,
    ),
  );
}

bool hasNonGreen(_Ctx ctx, int? clauseIndex) => ctx.items.any(
  (it) => it.clauseIndex == clauseIndex && it.verdict != Verdict.green,
);

void addGreen(
  _Ctx ctx,
  Clause? clause,
  String ruleName,
  RegExp re,
  String line,
) {
  if (clause == null) return;
  if (hasNonGreen(ctx, clause.index)) return;
  if (ctx.items.where((it) => it.verdict == Verdict.green).length >= 5) return;
  final q = qAny(clause, re);
  _addItem(
    ctx,
    _ItemData(
      base: 'G',
      ruleId: '常规',
      verdict: Verdict.green,
      ruleName: ruleName,
      short: ruleName,
      clauseIndex: clause.index,
      location: clauseLabel(clause, clause.index),
      quote: q?.quote ?? '',
      range: q,
      consequence: line,
      confidence: '高',
    ),
  );
}

void addPatternItem(
  _Ctx ctx,
  Clause? c,
  _ItemData data,
  RegExp quoteRe, [
  Object? sentenceExclude,
]) {
  final q = c != null
      ? (qFilter(c, quoteRe, sentenceExclude) ?? qAny(c, quoteRe))
      : null;
  _addItem(
    ctx,
    _ItemData(
      ruleId: data.ruleId,
      base: data.base,
      verdict: data.verdict,
      ruleName: data.ruleName,
      short: data.short,
      clauseIndex: c?.index,
      location: c != null ? clauseLabel(c, c.index) : '全文',
      quote: q?.quote ?? '',
      range: q,
      consequence: data.consequence,
      basis: data.basis,
      ask: data.ask,
      counter: data.counter,
      confidence: data.confidence,
      loss: data.loss,
    ),
  );
}

void addPending(_Ctx ctx, List<String> list) {
  for (final p in list) {
    if (p.isNotEmpty && !ctx.pending.contains(p)) ctx.pending.add(p);
  }
}

/* R1 试用期期限 */
void runR1(_Ctx ctx) {
  final extendRe = RegExp(
    r'(?:试用期[^。；\n]{0,16}(?:可以|可|经[^。；\n]{0,8}同意)?(?:延长|顺延|再延)|(?:延长|顺延)[^。；\n]{0,12}试用期|再次约定[^。；\n]{0,10}试用期|二次试用|重复试用|续签[^。；\n]{0,16}约定[^。；\n]{0,6}试用期)',
  );
  final noExtendRe = RegExp(r'(不得|禁止|不能|不再)[^。；\n]{0,8}(?:延长|顺延)');
  Clause? extendC;
  for (final cl in ctx.clauses) {
    final full = cl.full;
    if (extendRe.hasMatch(full) && !noExtendRe.hasMatch(full)) {
      extendC = cl;
      break;
    }
  }
  if (extendC != null) {
    addPatternItem(
      ctx,
      extendC,
      _ItemData(
        base: 'R1',
        ruleId: 'R1',
        verdict: Verdict.red,
        ruleName: '延长或重复约定试用期',
        short: '试用期被延长或重复约定',
        consequence: '同一单位与同一劳动者只能约定一次试用期；延长、二次试用或续签时重新约定，超出法定上限的部分不成立，但公司可能先按延长后的低工资执行。',
        ask: 'HR：这次是第几次约定试用期？延长依据是什么？',
        counter: '删除延长或二次试用；同一段劳动关系只保留一次法定上限内的试用期。',
        basis: law['L19'],
        confidence: '高',
      ),
      extendRe,
    );
  }
  final includeRe = RegExp(
    r'(?:试用期[^。；\n]{0,16}(?:不(?:计入|包括在|包含在)|另行计算|除外)[^。；\n]{0,10}(?:合同期限|劳动合同期限)|(?:合同期限|劳动合同期限)[^。；\n]{0,16}(?:不(?:包括|含|计入))[^。；\n]{0,8}试用期)',
  );
  Clause? includeC;
  for (final cl in ctx.clauses) {
    if (includeRe.hasMatch(cl.full)) {
      includeC = cl;
      break;
    }
  }
  if (includeC != null) {
    addPatternItem(
      ctx,
      includeC,
      _ItemData(
        base: 'R1',
        ruleId: 'R1',
        verdict: Verdict.red,
        ruleName: '试用期不计入合同期限',
        short: '试用期被排除在合同期外',
        consequence: '试用期依法包含在劳动合同期限内。把它排除在外，会连带影响合同期限、社保起算和试用期上限的判断。',
        ask: 'HR：试用期是否包含在劳动合同期限内？',
        counter: '改为“试用期包含在劳动合同期限内”，并写清合同起止日期。',
        basis: law['L19'],
        confidence: '高',
      ),
      includeRe,
    );
  }
  final trialLikeRe = RegExp(r'(试岗期|见习期|适应期|磨合期)');
  Clause? trialLikeC;
  for (final cl in ctx.clauses) {
    final full = cl.full;
    if (!RegExp(r'试用期').hasMatch(full) && trialLikeRe.hasMatch(full)) {
      trialLikeC = cl;
      break;
    }
  }
  if (trialLikeC != null) {
    addPatternItem(
      ctx,
      trialLikeC,
      _ItemData(
        base: 'R1',
        ruleId: 'R1',
        verdict: Verdict.gray,
        ruleName: '非试用期名义的考察期',
        short: '试岗/见习期性质不明',
        consequence: '文本没有写“试用期”，但出现试岗期、见习期或适应期。名称不同不代表不受试用期规则约束；如果实际按低工资、随意辞退管理，仍可能被认定为试用期。',
        ask: 'HR：这段考察期的工资、社保和解除条件是否与正式员工一致？',
        counter: '写清考察期性质与待遇；如按试用期管理，直接使用“试用期”并遵守法定上限。',
        basis: law['L19'],
      ),
      trialLikeRe,
    );
  }
  Clause? c;
  for (final cl in ctx.clauses) {
    final full = cl.full;
    if (RegExp(r'试用期').hasMatch(full) && parseProbation(full) != null) {
      c = cl;
      break;
    }
  }
  if (c == null) return;
  final prob = parseProbation(c.full)!;
  final term = parseContractTerm(ctx.text);
  final q =
      qAny(c, RegExp(r'(试用期[^。；\n]{0,40}?(?:个月|月))')) ??
      qAny(c, RegExp(r'试用期'));
  final loc = clauseLabel(c, c.index);
  if (term == null) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R1',
        ruleId: 'R1',
        verdict: Verdict.gray,
        ruleName: '试用期期限无法核对',
        short: '试用期 ${jsNum(prob)} 个月未对应期限',
        clauseIndex: c.index,
        location: loc,
        quote: q?.quote ?? '',
        range: q,
        consequence:
            '约定试用期 ${jsNum(prob)} 个月，但文本里没有写合同期限；无法核对法定上限，先让 HR 把起止日期写清。',
        ask: 'HR：合同期限是多久？试用期为什么定这个长度？',
        counter: '写明合同起止日期，并按期限对应的上限改短试用期。',
        basis: law['L19'],
      ),
    );
    return;
  }
  final max = term.months < 3
      ? 0
      : term.months < 12
      ? 1
      : term.months < 36
      ? 2
      : 6;
  if (prob > max) {
    final excess = prob - max;
    final cons = max == 0
        ? '合同期限约 ${term.label}，依法不得约定试用期，这里却写了 ${jsNum(prob)} 个月；这段期间应按正常工资标准支付。'
        : '合同期限约 ${term.label}，试用期上限 $max 个月，这里写了 ${jsNum(prob)} 个月；多出的 ${jsNum(excess)} 个月工资差额可主张补足。';
    _addItem(
      ctx,
      _ItemData(
        base: 'R1',
        ruleId: 'R1',
        verdict: Verdict.red,
        ruleName: '试用期超过法定上限',
        short: '试用期超上限 ${jsNum(excess)} 个月',
        clauseIndex: c.index,
        location: loc,
        quote: q?.quote ?? '',
        range: q,
        consequence: cons,
        ask: 'HR：${term.label}合同为什么约定 ${jsNum(prob)} 个月试用期？',
        counter: '按上限改为 $max 个月，并写明合同起止日期。',
        basis: law['L19'],
        confidence: '高',
      ),
    );
  } else {
    addGreen(
      ctx,
      c,
      '试用期期限',
      RegExp(r'试用期'),
      '试用期 ${jsNum(prob)} 个月，未超过约 ${term.label} 合同对应的上限。',
    );
  }
}

/* R2 试用期工资 */
void runR2(_Ctx ctx) {
  final probationClauses = ctx.clauses.where((cl) {
    final t = cl.full;
    return RegExp(r'试用期').hasMatch(t) &&
        (parseProbation(t) != null ||
            RegExp(r'试用期[^。；\n]{0,16}(工资|月薪|薪资|报酬)|试用期[^。；\n]{0,30}(元|%|％|百分之)')
                .hasMatch(t));
  }).toList();
  if (probationClauses.isEmpty) return;
  final salaryClauses = probationClauses
      .where((cl) => RegExp(r'(工资|薪资|月薪|报酬)').hasMatch(cl.full))
      .toList();
  Clause? c;
  for (final cl in salaryClauses) {
    final full = cl.full;
    if (parseAmount(full) != null ||
        parsePercent(full) != null ||
        RegExp(r'(转正后|转正|正式)').hasMatch(full)) {
      c = cl;
      break;
    }
  }
  c ??= salaryClauses.isNotEmpty ? salaryClauses[0] : probationClauses[0];
  final full = c.full;
  final probPayMatch = RegExp(
    r'试用期(?:工资|月薪|薪资|报酬)?\s*(?:为|按|是|不低于|：|:)?\s*(?:每月|月)?\s*(?:人民币)?\s*([\d,]+(?:\.\d+)?|[一二两三四五六七八九十百千万]+)\s*(?:元|千元|万元)',
  ).firstMatch(full);
  final probPay = probPayMatch != null
      ? parseAmount(probPayMatch.group(0))
      : null;
  final probPercentMatch = RegExp(
    r'试用期[^。；\n]{0,30}?(?:转正后|转正|正式|合同约定|约定工资|工资)[^。；\n]{0,16}?(?:的|\s)(\d+(?:\.\d+)?)\s*[%％]',
  ).firstMatch(full);
  final probPercentCN = probPercentMatch != null
      ? null
      : RegExp(r'试用期[^。；\n]{0,30}?百分之\s*([一二两三四五六七八九十百零〇\d]+)')
            .firstMatch(full);
  double? probPercent = probPercentMatch != null
      ? double.parse(probPercentMatch.group(1)!)
      : (probPercentCN != null ? cnNum(probPercentCN.group(1)) : null);
  if (probPercent == null && RegExp(r'(工资|薪|报酬|发放|标准)').hasMatch(full)) {
    final directPct = RegExp(r'试用期[^。；\n]{0,30}?(\d+(?:\.\d+)?)\s*[%％]')
        .firstMatch(full);
    final directCheng = RegExp(r'试用期[^。；\n]{0,30}?([一二两三四五六七八九])成')
        .firstMatch(full);
    if (directPct != null) {
      probPercent = double.parse(directPct.group(1)!);
    } else if (directCheng != null) {
      final n = cnNum(directCheng.group(1));
      if (n.isFinite) probPercent = n * 10;
    }
  }
  final percentText = probPercentMatch != null
      ? probPercentMatch.group(0)!
      : (probPercentCN != null ? probPercentCN.group(0)! : '');
  final percentIsFloor = RegExp(r'(不低于|至少|最低)').hasMatch(percentText);
  final regMatch = RegExp(
    r'(?:转正后|转正|正式|录用后|合同约定)(?:工资|月薪|薪资|报酬)?\s*(?:为|按|是|：|:)?\s*(?:每月|月)?\s*(?:人民币)?\s*([\d,]+(?:\.\d+)?|[一二两三四五六七八九十百千万]+)\s*(?:元|千元|万元)',
  ).firstMatch(full);
  double? reg = regMatch != null ? parseAmount(regMatch.group(0)) : null;
  if (reg == null) {
    final globalReg = RegExp(
      r'(?:转正后|转正|正式|录用后)(?:工资|月薪|薪资|报酬)?\s*(?:为|按|是|：|:)?\s*(?:每月|月)?\s*(?:人民币)?\s*([\d,]+(?:\.\d+)?|[一二两三四五六七八九十百千万]+)\s*(?:元|千元|万元)',
    ).firstMatch(ctx.text);
    if (globalReg != null) reg = parseAmount(globalReg.group(0));
  }
  final q =
      qAny(
        c,
        RegExp(
          r'(试用期[^。；\n]{0,40}(?:元|%|％|百分之[一二两三四五六七八九十百]+|[一二两三四五六七八九十]+成))',
        ),
      ) ??
      qAny(c, RegExp(r'(试用期[^。；\n]{0,40}(?:工资|薪资|月薪|报酬))')) ??
      qAny(c, RegExp(r'试用期'));
  final loc = clauseLabel(c, c.index);
  final months = parseProbation(ctx.text);
  final floor = reg != null ? reg * 0.8 : null;
  final amountTooLow =
      probPay != null && floor != null && probPay < floor - 0.5;
  final percentTooLow = probPercent != null && probPercent < 80;
  final noPayRe = RegExp(
    r'(?:试用期[^。；\n]{0,20}(?:无薪|不发工资|无工资|不支付工资|零工资)|(?:无薪|免费)[^。；\n]{0,8}试用)',
  );
  if (noPayRe.hasMatch(full)) {
    addPatternItem(
      ctx,
      c,
      _ItemData(
        base: 'R2',
        ruleId: 'R2',
        verdict: Verdict.red,
        ruleName: '试用期不支付工资',
        short: '试用期无薪',
        consequence:
            '试用期也是劳动关系，必须支付工资且不得低于当地最低工资标准；“无薪试用”的约定不产生效力，但这段时间你可能先拿不到钱。',
        ask: 'HR：试用期按什么标准发工资？',
        counter: '删除无薪约定，按不低于约定工资 80% 且不低于当地最低工资支付。',
        basis: law['L20'],
        confidence: '高',
      ),
      noPayRe,
    );
    return;
  }
  final scopeRe = RegExp(
    r'(?:试用期[^。；\n]{0,24}(?:只|仅)[^。；\n]{0,10}(?:发放|发|领取|按)[^。；\n]{0,8}(?:基本工资|底薪)|试用期[^。；\n]{0,20}(?:不享受|不参与|不含|不含绩效)[^。；\n]{0,10}(?:绩效|奖金|提成|补贴))',
  );
  if (scopeRe.hasMatch(full) && !amountTooLow && !percentTooLow) {
    addPatternItem(
      ctx,
      c,
      _ItemData(
        base: 'R2',
        ruleId: 'R2',
        verdict: Verdict.gray,
        ruleName: '试用期工资口径不明',
        short: '试用期只发基本工资',
        consequence: '合同把试用期工资限定为基本工资，或不参与绩效、奖金。80% 的比较基数应是约定工资；如果转正工资还包含固定发放的绩效或补贴，实际试用期工资可能低于下限。',
        ask: 'HR：试用期工资是否包含绩效、补贴？转正工资的固定部分是多少？',
        counter: '写明试用期与转正工资的完整构成，按同一口径计算 80% 下限。',
        basis: law['L20'],
      ),
      scopeRe,
    );
    return;
  }

  if (amountTooLow || percentTooLow) {
    final diff = amountTooLow ? floor - probPay : 0.0;
    final cons = amountTooLow
        ? '转正工资 ${fmtYuan(reg)} 元，试用期最低应 ${fmtYuan(floor)} 元；现按 ${fmtYuan(probPay)} 元发，每月少 ${fmtYuan(diff)} 元${months != null ? '，合同写的 ${jsNum(months)} 个月共少 ${fmtYuan(diff * months)} 元' : ''}${percentTooLow ? '。条款还另写了 ${jsNum(probPercent)}% 的比例，低于 80% 下限' : ''}。'
        : '合同把试用期工资写成转正工资的 ${jsNum(probPercent!)}%${reg != null ? '（法定下限 ${fmtYuan(floor)} 元/月）' : ''}，低于法定 80% 下限${probPay != null ? '；虽然另写了 ${fmtYuan(probPay)} 元，但按低比例执行的风险仍在' : ''}。';
    _addItem(
      ctx,
      _ItemData(
        base: 'R2',
        ruleId: 'R2',
        verdict: Verdict.red,
        ruleName: '试用期工资低于约定工资的 80%',
        short: '试用期工资低于 80%',
        clauseIndex: c.index,
        location: loc,
        quote: q?.quote ?? '',
        range: q,
        consequence: cons,
        ask: 'HR：试用期工资为什么低于转正工资的 80%？',
        counter: '改为不低于转正工资的 80%，且不低于当地最低工资标准。',
        basis: law['L20'],
        confidence: '高',
        loss: amountTooLow
            ? diff * (months ?? 1)
            : (reg != null
                  ? (reg * (80 - (probPercent ?? 0)) / 100 > 0
                            ? reg * (80 - (probPercent ?? 0)) / 100
                            : 0) *
                        (months ?? 1)
                  : 0),
      ),
    );
    return;
  }

  if (probPay != null) {
    if (reg == null) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R2',
          ruleId: 'R2',
          verdict: Verdict.gray,
          ruleName: '试用期工资缺比较基准',
          short: '试用期工资无法核对',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '写了试用期工资 ${fmtYuan(probPay)} 元，但没有转正工资，无法核对是否达到约定工资的 80%。',
          ask: 'HR：转正后工资和试用期工资的计算基数是多少？',
          counter: '把转正工资、试用期工资和是否含绩效写进合同。',
          basis: law['L20'],
        ),
      );
      return;
    }
    addGreen(
      ctx,
      c,
      '试用期工资',
      RegExp(r'(试用期[^。；\n]{0,40}元)'),
      '试用期工资 ${fmtYuan(probPay)} 元，不低于转正工资 ${fmtYuan(reg)} 元的 80%（${fmtYuan(floor)} 元）。',
    );
    return;
  }

  if (probPercent != null) {
    if (percentIsFloor) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R2',
          ruleId: 'R2',
          verdict: Verdict.gray,
          ruleName: '试用期工资只写了下限',
          short: '试用期工资未写具体金额',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '只写了“不低于转正工资的 ${jsNum(probPercent)}%”，没有写试用期实际发多少；比例本身达标，但具体金额和当地最低工资仍无法核对。',
          ask: 'HR：试用期每月实际到手多少？是否按转正工资的 80% 以上发？',
          counter: '把试用期工资的具体金额和计算基数写进合同。',
          basis: law['L20'],
        ),
      );
    } else if (reg != null) {
      final computed = reg * probPercent / 100;
      addGreen(
        ctx,
        c,
        '试用期工资',
        RegExp(r'(试用期[^。；\n]{0,40}(?:%|％|百分之[一二两三四五六七八九十百]+|[一二两三四五六七八九十]+成))'),
        '试用期工资按转正工资的 ${jsNum(probPercent)}% 约定（约 ${fmtYuan(computed)} 元/月），不低于法定 80%；仍需核对当地最低工资。',
      );
    } else {
      addGreen(
        ctx,
        c,
        '试用期工资',
        RegExp(r'(试用期[^。；\n]{0,40}(?:%|％|百分之[一二两三四五六七八九十百]+|[一二两三四五六七八九十]+成))'),
        '试用期工资按转正工资的 ${jsNum(probPercent)}% 约定，不低于法定 80%；仍需核对具体金额与当地最低工资。',
      );
    }
    return;
  }

  if (reg != null) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R2',
        ruleId: 'R2',
        verdict: Verdict.gray,
        ruleName: '试用期工资未明确',
        short: '试用期工资未写明',
        clauseIndex: c.index,
        location: loc,
        quote: q?.quote ?? '',
        range: q,
        consequence:
            '合同写了转正工资 ${fmtYuan(reg)} 元，但没有写试用期工资；按 80% 算底线是 ${fmtYuan(reg * 0.8)} 元，实际发多少现在无法核对。',
        ask: 'HR：试用期工资具体多少？是否按转正工资的 80% 以上发？',
        counter: '把试用期工资和转正工资分别写清，并注明是否含绩效。',
        basis: law['L20'],
        confidence: '高',
      ),
    );
  } else {
    _addItem(
      ctx,
      _ItemData(
        base: 'R2',
        ruleId: 'R2',
        verdict: Verdict.gray,
        ruleName: '试用期工资无法核对',
        short: '试用期工资未写明',
        clauseIndex: c.index,
        location: loc,
        quote: q?.quote ?? '',
        range: q,
        consequence: '只写了试用期，没有写试用期工资，也没有可比较的转正工资；80% 下限和当地最低工资都无法核对。',
        ask: 'HR：试用期工资和转正工资分别是多少？',
        counter: '把两项工资、计算基数和发放日写进合同。',
        basis: law['L20'],
      ),
    );
  }
}

/* R3 试用期解除 */
void runR3(_Ctx ctx) {
  final matches = ctx.clauses.where((cl) {
    final t = cl.full;
    return RegExp(r'试用期').hasMatch(t) &&
        RegExp(r'(解除|辞退|终止|不予录用|不予转正|淘汰)').hasMatch(t) &&
        RegExp(
          r'(不合格|不符合(?:录用条件|岗位要求|工作要求)|不胜任|不能胜任|考核(?:不通过|不合格|未通过|不达标)|评分(?:不合格|不达标)|排名末位|末位淘汰|不适合(?:本)?岗位|不符合要求)',
        ).hasMatch(t) &&
        !RegExp(r'(?:^|[^无])(?:应|需|必须|要)[^。；\n]{0,4}说明理由').hasMatch(t);
  }).toList();
  for (final c in matches) {
    final t = c.full;
    final explicit = RegExp(
      r'(无需|无须|不需|不必|不用)[^。；\n]{0,6}(?:说明)?理由|不(?:再|另行|需要)?说明理由|可(?:随时|直接)(?:辞退|解除)',
    ).hasMatch(t);
    final q = qAny(c, RegExp(r'(解除|辞退|终止|不予录用)'));
    _addItem(
      ctx,
      _ItemData(
        base: 'R3',
        ruleId: 'R3',
        verdict: explicit ? Verdict.red : Verdict.yellow,
        ruleName: explicit ? '试用期解除可不说明理由' : '试用期解除理由不清',
        short: explicit ? '可不说明理由辞退' : '试用期解除理由不清',
        clauseIndex: c.index,
        location: clauseLabel(c, c.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: explicit
            ? '公司可以不给理由就辞退你；这与“试用期解除应说明理由”的规定冲突，但真发生时你得先固定考核和沟通记录，再主张程序违法。'
            : '试用期被辞退，公司若只写“不合格”不说明理由，你需要自己固定录用条件、考核和沟通记录；仅凭这条也可能当场让你走。',
        ask: 'HR：录用条件和考核标准写在哪份文件里？',
        counter: '把录用条件、考核方式和解除说明写进附件与流程。',
        basis: law['L21'],
        confidence: explicit ? '高' : '中',
      ),
    );
  }
}

/* R4 违约金（劳动合同） */
void runR4(_Ctx ctx) {
  final penaltyRe = RegExp(
    r'(违约金|违约赔偿|赔偿金|赔偿|罚款|罚金|扣除[^。；\n]{0,10}(?:工资|薪资|报酬)|扣发[^。；\n]{0,10}(?:工资|薪资|报酬))',
  );
  final exitRe = RegExp(
    r'(提前(?:离职|辞职|解除|终止|走人)|未满[^。；\n]{0,12}(?:离职|辞职|解除)|擅自(?:离职|辞职|离岗|走人)|未(?:提前|按)[^。；\n]{0,12}(?:通知|申请)[^。；\n]{0,10}(?:离职|辞职|解除)|未(?:办理|完成)[^。；\n]{0,10}(?:交接|离职手续)|不辞而别|自动离职|(?:辞职|离职|擅离)[^。；\n]{0,26}(?:违约金|赔偿|罚款|扣除|扣发)|(?:违约金|赔偿|罚款|扣除|扣发)[^。；\n]{0,18}(?:辞职|离职)|(?:乙方|劳动者)[^。；\n]{0,10}解除[^。；\n]{0,8}(?:合同|协议|劳动关系))',
  );
  final legalRe = RegExp(r'(服务期|专项培训|竞业限制|竞业|保密协议)');
  final legalPenaltyRe = RegExp(
    r'(?:服务期|专项培训|竞业限制|竞业|保密协议)[^。；\n]{0,36}(?:违约金|赔偿|罚款)|(?:违约金|赔偿|罚款)[^。；\n]{0,36}(?:服务期|专项培训|竞业限制|竞业|保密协议)',
  );
  final hits = <List<Object>>[];
  for (final c in ctx.clauses) {
    final full = c.full;
    if (!penaltyRe.hasMatch(full)) continue;
    if (legalRe.hasMatch(full) && !exitRe.hasMatch(full)) continue;
    _Span? hit;
    for (final sentence in sentenceList(c.body)) {
      final parts = commaParts(sentence.quote);
      for (final p in parts) {
        if (penaltyRe.hasMatch(p.quote) &&
            exitRe.hasMatch(p.quote) &&
            !legalPenaltyRe.hasMatch(p.quote)) {
          hit = _Span(
            p.quote,
            sentence.start + p.start,
            sentence.start + p.end,
          );
          break;
        }
      }
      if (hit != null) break;
      for (var i = 0; i < parts.length - 1; i++) {
        final raw = sentence.quote.substring(parts[i].start, parts[i + 1].end);
        if (penaltyRe.hasMatch(raw) &&
            exitRe.hasMatch(raw) &&
            !legalPenaltyRe.hasMatch(raw)) {
          hit = _Span(
            raw,
            sentence.start + parts[i].start,
            sentence.start + parts[i + 1].end,
          );
          break;
        }
      }
      if (hit != null) break;
    }
    if (hit != null) hits.add([c, hit]);
  }
  for (final entry in hits) {
    final c = entry[0] as Clause;
    final s = entry[1] as _Span;
    final pm = penaltyRe.firstMatch(s.quote);
    final q = pm != null
        ? QuoteRef(
            clipQuote(s.quote, pm.start, pm.end),
            s.quote,
            start: s.start,
            end: s.end,
          )
        : QuoteRef(
            clipQuote(s.quote, 0, 1),
            s.quote,
            start: s.start,
            end: s.end,
          );
    final amt =
        maxAmountAfter(s.quote, RegExp(r'(违约金|赔偿|罚款|扣除)')) ??
        parseAmount(s.quote);
    final deduct = RegExp(r'(扣除|扣减|扣发)[^。；\n]{0,12}(工资|薪资)').hasMatch(s.quote);
    final cons = amt != null
        ? '提前离职要赔 ${fmtYuan(amt)} 元${deduct ? '，还可能被扣当月工资' : ''}；条款是否有效要另争，但钱被扣、流程被拖会先落在你身上。'
        : '提前离职要赔钱${deduct ? '或被扣当月工资' : ''}，但没写金额；先要求写明计算方式，或者直接删除。';
    _addItem(
      ctx,
      _ItemData(
        base: 'R4',
        ruleId: 'R4',
        verdict: Verdict.red,
        ruleName: '离职违约金（法定情形外）',
        short: amt != null ? '${fmtWan(amt)}离职违约金' : '离职违约金',
        clauseIndex: c.index,
        location: clauseLabel(c, c.index),
        quote: q.quote,
        range: q,
        consequence: cons,
        ask: 'HR：普通岗位的离职违约金依据哪条法定情形？',
        counter: '删除离职违约金与扣工资；如确有专项培训，另签服务期协议并列明费用凭证。',
        basis: law['L25'],
        confidence: amt != null ? '高' : '中',
        loss: amt ?? 0,
      ),
    );
  }
}

/* R5 服务期违约金 */
void runR5(_Ctx ctx) {
  _Sentence? feeSent;
  for (final s in sentenceList(ctx.text)) {
    if (RegExp(r'(专项培训费|培训费用|培训费|培训成本|培养费|进修费|学费)').hasMatch(s.quote) &&
        parseAmount(s.quote) != null) {
      feeSent = _Sentence(s.quote, s.start, s.end, 0, 0);
      break;
    }
  }
  final fee = feeSent != null ? parseAmount(feeSent.quote) : null;
  final matches = ctx.clauses.where((cl) {
    final t = cl.full;
    return RegExp(r'(服务期|服务年限|最低服务年限|培训服务期)').hasMatch(t) &&
        RegExp(r'(违约金|赔偿|退还|返还|补缴|承担)').hasMatch(t) &&
        RegExp(r'(提前|离职|解除|未满|违反|不足|不满)').hasMatch(t);
  }).toList();
  final fullRefundRe = RegExp(
    r'(?:未满|违反|提前[^。；\n]{0,10}(?:离职|解除))[^。；\n]{0,30}(?:全额|全部|100\s*%|所有)[^。；\n]{0,12}(?:退还|返还|赔偿|支付)|(?:全额|全部)[^。；\n]{0,10}(?:退还|返还|赔偿)[^。；\n]{0,10}(?:培训费|培训费用|学费)',
  );
  for (final c in matches) {
    final q = qAny(c, RegExp(r'(服务期|违约金|赔偿|退还|返还)'));
    final penSentence = sentenceOf(c.body, RegExp(r'(违约金|赔偿|退还|返还|补缴|承担)'));
    double? penalty;
    if (penSentence != null) {
      final raw = penSentence.quote;
      final searchRe = RegExp(r'(违约金|赔偿|退还|返还|补缴|承担)');
      final idx = raw.indexOf(searchRe);
      final tail = raw.substring(idx < 0 ? 0 : idx);
      final penM = RegExp(
        r'(违约金|赔偿|退还|返还|补缴|承担)[^。；\n]{0,30}?([\d,]+(?:\.\d+)?)\s*(万元|万|千元|千|元)',
      ).firstMatch(tail);
      if (penM != null) {
        penalty = parseAmount('${penM.group(2)}${penM.group(3)}');
      }
    }
    penalty ??= parseAmount(c.body);
    if (penalty == null && penSentence != null && fee != null) {
      final mult = RegExp(r'([一二两三四五六七八九十\d]+)\s*倍')
          .firstMatch(penSentence.quote);
      final n = mult != null ? cnNum(mult.group(1)) : double.nan;
      if (n.isFinite && n > 0) penalty = fee * n;
    }
    final loc = clauseLabel(c, c.index);
    if (fee == null) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R5',
          ruleId: 'R5',
          verdict: Verdict.red,
          ruleName: '服务期缺少专项培训依据',
          short: '服务期缺培训费依据',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '写了服务期违约金${penalty != null ? ' ${fmtYuan(penalty)} 元' : ''}，但文本里没有专项培训费用；公司拿不出培训费凭证时，这笔钱没有依据，但离职时你可能先被索赔。',
          ask: 'HR：专项培训费用是多少？有发票或支付凭证吗？',
          counter: '删除服务期违约金，或按实际培训费用写明并只按未履行部分分摊。',
          basis: law['L22'],
          loss: penalty ?? 0,
        ),
      );
    } else if (fullRefundRe.hasMatch(c.body)) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R5',
          ruleId: 'R5',
          verdict: Verdict.red,
          ruleName: '服务期违约金未按未履行部分分摊',
          short: '服务期要求全额退培训费',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '培训费 ${fmtYuan(fee)} 元，条款要求离职时全额退还或赔偿；法定上限是按服务期未履行部分分摊，已经履行期间对应的培训费不应再赔。',
          ask: 'HR：服务期多长？未履行部分怎么折算？',
          counter: '改为按未履行期限比例分摊，并写明培训费凭证。',
          basis: law['L22'],
          confidence: '高',
          loss: penalty ?? fee,
        ),
      );
    } else if (penalty != null && penalty > fee) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R5',
          ruleId: 'R5',
          verdict: Verdict.red,
          ruleName: '服务期违约金超过培训费',
          short: '服务期违约金超培训费',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '服务期违约金 ${fmtYuan(penalty)} 元，高于 ${fmtYuan(fee)} 元培训费；超过部分以及未履行期限之外的分摊，可以拒绝承担。',
          ask: 'HR：培训费凭证和分摊算法能提供吗？',
          counter: '把违约金上限写成实际培训费用，按未履行期限分摊。',
          basis: law['L22'],
          confidence: '高',
          loss: penalty,
        ),
      );
    } else {
      _addItem(
        ctx,
        _ItemData(
          base: 'R5',
          ruleId: 'R5',
          verdict: Verdict.yellow,
          ruleName: '服务期约束',
          short: '服务期与培训费挂钩',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '服务期与 ${fmtYuan(fee)} 元培训费挂钩；签了就要在服务期内受约束，违约金最多按未履行部分分摊。',
          ask: 'HR：服务期多久？培训费凭证和分摊算法能提供吗？',
          counter: '写明培训费总额与凭证，并约定按未履行期限分摊。',
          basis: law['L22'],
          loss: penalty ?? 0,
        ),
      );
    }
  }
}

/* R6 竞业限制 */
void runR6(_Ctx ctx) {
  final matches = ctx.clauses
      .where(
        (cl) =>
            RegExp(r'(竞业|不竞争)').hasMatch(cl.full) &&
            RegExp(r'(限制|禁止|不得|义务|补偿)').hasMatch(cl.full),
      )
      .toList();
  if (matches.isEmpty) return;
  final permanentRe = RegExp(
    r'(?:竞业|不竞争)[^。；\n]{0,30}(?:永久|无限期|长期)|(?:永久|无限期)[^。；\n]{0,20}(?:竞业|不竞争|不得从事)',
  );
  final durM =
      RegExp(
        r'(?:竞业限制(?:期限|期)?|竞业期限|竞业禁止(?:期限|期)?|限制期限|离职后|离职之日起)[^。；\n]{0,30}?([一二两三四五六七八九十\d]{1,3})\s*(年|个月|月)',
      ).firstMatch(ctx.text) ??
      RegExp(
        r'([一二两三四五六七八九十\d]{1,3})\s*(年|个月|月)[^。；\n]{0,20}(?:内|以内)?[^。；\n]{0,12}(?:不得|不能|禁止|不从事)[^。；\n]{0,12}(?:竞业|同类|竞争)',
      ).firstMatch(ctx.text) ??
      RegExp(r'(?:竞业|不竞争)[^。；\n]{0,40}?([一二两三四五六七八九十\d]{1,3})\s*(年|个月|月)')
          .firstMatch(ctx.text);
  final durNum = durM != null ? cnNum(durM.group(1)) : double.nan;
  final double? durMonths = permanentRe.hasMatch(ctx.text)
      ? 999
      : (durNum.isFinite && durNum != 0
            ? (durM!.group(2) == '年' ? durNum * 12 : durNum)
            : null);
  final negCompGlobal =
      RegExp(r'(无需|不需|不用|不予|不支付|不再支付|没有|无)[^。；\n]{0,16}(经济补偿|补偿)')
          .hasMatch(ctx.text) ||
      RegExp(r'(经济补偿|补偿)[^。；\n]{0,12}(没有|不支付|不予|无需)').hasMatch(ctx.text);
  final compInSalaryRe = RegExp(
    r'(?:经济补偿|竞业补偿|补偿金?)[^。；\n]{0,24}(?:已包含|包含在|计入|随工资|在职期间发放|每月工资中)|(?:工资|薪资|月薪)[^。；\n]{0,20}(?:已包含|包含|含)[^。；\n]{0,12}(?:竞业|经济补偿)',
  );
  final compMention = RegExp(
    r'(竞业|离职后|限制期)[^。；\n]{0,40}(经济补偿|补偿)|(经济补偿|补偿)[^。；\n]{0,40}(竞业|离职后|限制期)',
  ).hasMatch(ctx.text);
  final compAmount = RegExp(
    r'(?:经济补偿|竞业补偿|补偿金?)[^。；\n]{0,24}(?:每月|按月|月工资|年薪|百分之|\d+\s*%|\d+\s*元|不低于)',
  ).hasMatch(ctx.text);
  final scopeWide = RegExp(
    r'(?:竞业|不竞争)[^。；\n]{0,30}(?:全国|全球|全行业|所有行业|任何(?:公司|单位|行业)|同行业所有|不限地域)|(?:全国|全球|全行业)[^。；\n]{0,20}(?:竞业|不竞争)',
  ).hasMatch(ctx.text);
  final hasComp =
      compMention && !negCompGlobal && !compInSalaryRe.hasMatch(ctx.text);
  for (final c in matches) {
    final q = qAny(c, RegExp(r'(竞业限制|竞业|不竞争|经济补偿|补偿|不得从事)'));
    final loc = clauseLabel(c, c.index);
    if (durMonths != null && durMonths > 24) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R6',
          ruleId: 'R6',
          verdict: Verdict.red,
          ruleName: '竞业限制超过两年上限',
          short: permanentRe.hasMatch(ctx.text) ? '竞业限制无期限' : '竞业限制超过 2 年',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '竞业限制约 ${durMonths == 999 ? '无固定期限' : '${jsNum(durMonths)} 个月'}，超过法定 2 年上限；多出的约定不受支持，但可能吓退下家${!hasComp ? '，且没有写补偿' : ''}。',
          ask: 'HR：竞业限制为什么超过 2 年？范围包括哪些公司？',
          counter: '期限改为不超过 2 年，范围列明具体竞品，按月支付补偿。',
          basis: law['L24'],
          confidence: '高',
        ),
      );
    } else if (!hasComp) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R6',
          ruleId: 'R6',
          verdict: Verdict.gray,
          ruleName: compInSalaryRe.hasMatch(ctx.text)
              ? '竞业补偿包含在工资中'
              : '竞业限制未约定补偿',
          short: compInSalaryRe.hasMatch(ctx.text) ? '竞业补偿已在工资里' : '竞业限制没有补偿',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence: compInSalaryRe.hasMatch(ctx.text)
              ? '合同把竞业补偿写成已包含在工资或随工资发放；离职后的竞业限制补偿原则上应在竞业期内按月另行支付，这种写法可能被认定为没有约定补偿。'
              : '离职后${durMonths != null && durMonths != 0 ? ' ${jsNum(durMonths)} 个月内' : '竞业期内'}不能去同类公司，合同没写按月补偿；公司不付补偿时你可主张不受限制，但要先发函或申请仲裁确认。',
          ask: 'HR：竞业补偿按什么标准、离职后怎么发？',
          counter: '离职时另签竞业协议；按月补偿，期限不超过 2 年，范围写明具体竞品。',
          basis: law['L23'],
          confidence: durMonths != null && durMonths != 0 ? '高' : '中',
        ),
      );
    } else if (!compAmount) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R6',
          ruleId: 'R6',
          verdict: Verdict.gray,
          ruleName: '竞业补偿标准不明',
          short: '竞业补偿没写标准',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence: '写了竞业限制和补偿，但没有每月金额、比例或计算方式；离职后实际发多少、能不能覆盖生活成本，现在无法判断。',
          ask: 'HR：竞业补偿每月多少？按离职前工资的什么比例？',
          counter: '写明补偿标准、发放日和支付方式，再签竞业协议。',
          basis: law['L23'],
        ),
      );
    } else if (scopeWide) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R6',
          ruleId: 'R6',
          verdict: Verdict.yellow,
          ruleName: '竞业限制范围过宽',
          short: '竞业范围覆盖全行业',
          clauseIndex: c.index,
          location: loc,
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '竞业范围写成全国、全行业或任何单位；范围过宽会实际限制你换工作，超出合理保护范围的部分可请求调整，但先会被条款吓住。',
          ask: 'HR：竞业范围具体包括哪些产品或公司？',
          counter: '把范围限定到有竞争关系的具体业务、地域和岗位。',
          basis: law['L24'],
        ),
      );
    } else {
      addGreen(
        ctx,
        c,
        '竞业限制',
        RegExp(r'(竞业|补偿)'),
        '竞业限制${durMonths != null && durMonths != 0 ? ' ${jsNum(durMonths)} 个月' : ''}并约定补偿，属常规安排；仍需确认你是否属于应签人员。',
      );
    }
  }
  if (scopeWide) {
    for (final c in matches) {
      final already = ctx.items.any(
        (it) =>
            it.ruleId == 'R6' &&
            it.clauseIndex == c.index &&
            (it.ruleName == '竞业限制范围过宽' || it.verdict == Verdict.green),
      );
      if (already) continue;
      final q = qAny(c, RegExp(r'(竞业|不竞争|范围|全国|全球|全行业)'));
      _addItem(
        ctx,
        _ItemData(
          base: 'R6',
          ruleId: 'R6',
          verdict: Verdict.yellow,
          ruleName: '竞业限制范围过宽',
          short: '竞业范围覆盖全行业',
          clauseIndex: c.index,
          location: clauseLabel(c, c.index),
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '竞业范围写成全国、全行业或任何单位；范围过宽会实际限制你换工作，超出合理保护范围的部分可请求调整，但先会被条款吓住。',
          ask: 'HR：竞业范围具体包括哪些产品或公司？',
          counter: '把范围限定到有竞争关系的具体业务、地域和岗位。',
          basis: law['L24'],
        ),
      );
    }
  }
}

/* R7 无效与单方变更 */
void runR7(_Ctx ctx) {
  final waiverRe = RegExp(
    r'(放弃|不缴|不缴纳|不需缴纳|无需缴纳|不办理)[^。；\n]{0,16}(社保|社会保险|五险)|(社保|社会保险|五险)[^。；\n]{0,16}(自理|自行承担|自行缴纳|放弃|不缴)',
  );
  final personalRe = RegExp(r'个人(?:应缴|应缴纳|缴纳|承担|负担)?(?:的|部分)|个人部分');
  for (final c1 in ctx.clauses.where((cl) => waiverRe.hasMatch(cl.full))) {
    final q = qFilter(c1, RegExp(r'(社保|社会保险|五险|放弃)'), personalRe);
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R7',
        ruleId: 'R7',
        verdict: Verdict.red,
        ruleName: '放弃社保（无效）',
        short: '放弃社保',
        clauseIndex: c1.index,
        location: clauseLabel(c1, c1.index),
        quote: q.quote,
        range: q,
        consequence: '公司不给你缴社保，看病、工伤、养老都少一层保障；“自愿放弃”的约定不产生法律效力，但补缴要先投诉或申请仲裁。',
        ask: 'HR：社保从哪个月开始缴？按什么基数缴？',
