  }
  final changeRe = RegExp(
    r'(甲方|公司|用人单位)[^。；\n]{0,30}(有权|可以|将)[^。；\n]{0,24}(调整|变更|调动)[^。；\n]{0,26}(岗位|工资|薪资|工作地点|职位|部门)|(乙方|劳动者)[^。；\n]{0,14}(服从|接受)[^。；\n]{0,24}(调整|调动|变更)',
  );
  final obeyRe = RegExp(r'(服从|不得异议|不得拒绝|无条件|视为同意)');
  final consentRe = RegExp(r'协商一致|双方书面|书面同意|另行签订');
  for (final c2 in ctx.clauses.where(
    (cl) => changeRe.hasMatch(cl.full) && obeyRe.hasMatch(cl.full),
  )) {
    final q = qFilter(c2, RegExp(r'(调整|变更|调动)'), consentRe);
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R7',
        ruleId: 'R7',
        verdict: Verdict.red,
        ruleName: '单方调岗降薪',
        short: '单方调岗降薪',
        clauseIndex: c2.index,
        location: clauseLabel(c2, c2.index),
        quote: q.quote,
        range: q,
        consequence: '公司可据此单方调岗降薪，你拒绝后可能被针对；变更劳动合同应双方协商一致并书面确认，保留原合同和沟通记录。',
        ask: 'HR：调岗调薪的触发条件和范围是什么？',
        counter: '改为岗位、薪资变更需双方书面协商一致。',
        basis: law['L26'],
      ),
    );
  }
  final injuryRe = RegExp(
    r'(?:工伤|职业病|因工受伤|上下班途中|工作期间|工作场所)[^。；\n]{0,30}(?:受伤|事故|伤害|损害)[^。；\n]{0,24}(?:自负|自理|自行承担|不负责|不承担|概不负责|与甲方无关)|(?:工伤|职业病|因工受伤)[^。；\n]{0,24}(?:自负|自理|自行承担|不负责|不承担|概不负责|与甲方无关)',
  );
  for (final c3 in ctx.clauses.where((cl) => injuryRe.hasMatch(cl.full))) {
    final q =
        qFilter(
          c3,
          RegExp(r'(工伤|职业病|受伤|事故|自负|自理|不承担|与甲方无关)'),
          RegExp(r'甲方[^。；\n]{0,12}(?:负责|承担|支付)'),
        ) ??
        qAny(c3, RegExp(r'(工伤|自负|自理|不承担)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R7',
        ruleId: 'R7',
        verdict: Verdict.red,
        ruleName: '工伤责任自负（无效）',
        short: '工伤责任自负',
        clauseIndex: c3.index,
        location: clauseLabel(c3, c3.index),
        quote: q.quote,
