  final arbitraryFireRe = RegExp(
    r'(?:甲方|公司|用人单位)[^。；\n]{0,18}(?:有权|可以|可)[^。；\n]{0,12}(?:随时|直接|单方)[^。；\n]{0,10}(?:解除|终止|辞退)[^。；\n]{0,16}(?:劳动合同|劳动关系|合同|乙方)',
  );
  final faultFireRe = RegExp(
    r'严重违纪|严重违反|不符合录用条件|不胜任|不能胜任|经济性裁员|协商一致|合同期满|法定情形',
  );
  for (final c6 in ctx.clauses.where(
