  )) {
    var q = qFilter(c6, arbitraryFireRe, faultFireRe);
    if (q == null && !faultFireRe.hasMatch(c6.full)) {
      q = qAny(c6, arbitraryFireRe);
    }
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R7',
        ruleId: 'R7',
        verdict: Verdict.red,
        ruleName: '单位可随时解除（无效）',
        short: '公司可随时辞退',
