  final rulesChangeRe = RegExp(
    r'(?:规章制度|员工手册)[^。；\n]{0,30}(?:随时|单方|无需协商)[^。；\n]{0,10}(?:修改|变更|调整)[^。；\n]{0,20}(?:无需|不需)[^。；\n]{0,10}(?:通知|公示|协商)|(?:规章制度|员工手册)[^。；\n]{0,30}(?:最终解释权|解释权归)[^。；\n]{0,10}(?:甲方|公司)',
  );
  for (final c5 in ctx.clauses.where((cl) => rulesChangeRe.hasMatch(cl.full))) {
