}

/* R8 三方协议违约金 */
void runR8(_Ctx ctx) {
  final penaltyRe = RegExp(r'(违约金|违约责任|违约赔偿|赔偿(?:金|损失)?|诚信金|意向金|押金|保证金|定金)');
  final actionRe = RegExp(
    r'(提前(?:解除|离职|终止)|解约|解除|违约|擅自|未按期|未按|不报到|拒绝|放弃|变更|升学|考公|参军|不去|不履行|违反)',
  );
  bool studentSide(String s) =>
      RegExp(r'(任何一方|双方)[^。；\n]{0,10}(?:违约|解约|解除)').hasMatch(s) ||
      RegExp('(?:乙方|学生|毕业生|本人)[^。；\\n]{0,24}(?:${actionRe.pattern})')
          .hasMatch(s);
  final skipRe = RegExp(r'不得(?:约定|要求)|无权|无效|不承担');
  bool employerSide(String s) =>
      RegExp(
        r'(甲方|用人单位)[^。；\n]{0,14}(?:违约|违反)[^。；\n]{0,24}(?:向|给)?[^。；\n]{0,10}(?:乙方|学生|毕业生)',
      ).hasMatch(s) &&
      !RegExp(r'(乙方|学生|毕业生)[^。；\n]{0,14}(?:违约|解约|违反)').hasMatch(s);
  for (final c in ctx.clauses.where((cl) => penaltyRe.hasMatch(cl.full))) {
    var q = qFilter(
      c,
      penaltyRe,
      (String s) => skipRe.hasMatch(s) || employerSide(s) || !studentSide(s),
    );
    if (q == null &&
        c.heading.isNotEmpty &&
        RegExp(r'(乙方|学生|毕业生|任何一方)').hasMatch(c.heading) &&
        !sentenceList(c.body)
            .any((s) => employerSide(s.quote) || skipRe.hasMatch(s.quote))) {
      q = qAny(c, penaltyRe);
    }
    if (q == null) continue;
    final rawq = q.raw.isNotEmpty ? q.raw : q.quote;
    final amt = maxAmountAfter(rawq, penaltyRe) ?? parseAmount(rawq);
    final isLiquidated = RegExp(r'违约金|违约责任|违约赔偿').hasMatch(rawq);
    _addItem(
      ctx,
      _ItemData(
        base: 'R8',
        ruleId: 'R8',
        verdict: Verdict.yellow,
        ruleName: isLiquidated ? '三方协议解约违约金' : '三方协议违约赔偿',
        short: amt != null && amt != 0
            ? '${fmtWan(amt)}${isLiquidated ? '解约违约金' : '违约赔偿'}'
            : (isLiquidated ? '三方解约违约金' : '三方违约赔偿'),
        clauseIndex: c.index,
        location: clauseLabel(c, c.index),
        quote: q.quote,
        range: q,
        consequence: amt != null && amt != 0
            ? '${isLiquidated ? '解约' : '违约'}时单位可主张 ${fmtYuan(amt)} 元${isLiquidated ? '违约金' : '赔偿'}；三方协议属民事约定，一般有效，若远超单位实际支出可请求调减（司法实践常以实际损失的 30% 作为参考），但你要先应对违约主张。'
            : '写了${isLiquidated ? '违约金' : '违约赔偿'}但没有金额；解约时单位可能按实际损失索赔，金额和计算方式要让它写明。',
        ask: '就业办或单位：这笔违约金或赔偿对应哪些实际损失？',
        counter: '把金额降到有据可查的实际招聘支出，并写明解约流程。',
        basis: law['C585'],
        confidence: '高',
        loss: amt ?? 0,
      ),
    );
  }
  final employerOnlyRe = RegExp(
    r'(?:甲方|用人单位)[^。；\n]{0,24}(?:有权|可以|可)[^。；\n]{0,18}(?:解除|终止)[^。；\n]{0,26}(?:不承担|无需|不予|不支付)[^。；\n]{0,14}(?:违约|赔偿|补偿)',
  );
  for (final c in ctx.clauses.where((cl) => employerOnlyRe.hasMatch(cl.full))) {
    final q =
        qFilter(c, employerOnlyRe) ?? qAny(c, RegExp(r'(解除|终止|不承担|无需赔偿)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R8',
        ruleId: 'R8',
        verdict: Verdict.yellow,
        ruleName: '单位单方解约不担责',
        short: '单位解约不承担违约责任',
        clauseIndex: c.index,
        location: clauseLabel(c, c.index),
        quote: q.quote,
        range: q,
        consequence:
            '协议把单位的解约责任排除掉，只约束学生一方；真到单位反悔时，你很难按同一条款要求赔偿，三方协议的权利义务明显不对等。',
        ask: '就业办或单位：单位解约时学生可以主张哪些损失？',
        counter: '改为双方对等承担违约责任，或明确单位解约的赔偿标准。',
        basis: law['C497'],
      ),
    );
  }
}

/* R9 培训贷与分期 */
class _Rate {
  final double? rate;
  final bool daily;
  final bool monthly;
  _Rate(this.rate, this.daily, this.monthly);
}

_Rate parseRate(String? text) {
  final s = text ?? '';
  final daily = RegExp(r'(?:每?日|每天|按日)').hasMatch(s);
  final monthly = RegExp(r'(?:每月|按月)').hasMatch(s);
  var m = RegExp(r'(\d+(?:\.\d+)?)\s*[%％]').firstMatch(s);
  double? rate = m != null ? double.parse(m.group(1)!) : null;
  if (rate == null) {
    m = RegExp(r'(\d+(?:\.\d+)?)\s*‰').firstMatch(s);
    if (m != null) rate = double.parse(m.group(1)!) / 10;
  }
  if (rate == null) {
    m = RegExp(r'万分之\s*([一二两三四五六七八九十百零〇\d.]+)').firstMatch(s);
    if (m != null) {
      final n = cnNum(m.group(1));
      if (n.isFinite) rate = n / 100;
    }
  }
  if (rate == null) {
    m = RegExp(r'千分之\s*([一二两三四五六七八九十百零〇\d.]+)').firstMatch(s);
    if (m != null) {
      final n = cnNum(m.group(1));
      if (n.isFinite) rate = n / 10;
    }
  }
  return _Rate(rate, daily, monthly);
}

void runR9(_Ctx ctx) {
  _Span? feeSent;
  for (final s in sentenceList(ctx.text)) {
    if (RegExp(r'(培训费|学费|课程费|教育服务费|总费用|贷款本金|借款本金|分期总额)').hasMatch(s.quote) &&
        parseAmount(s.quote) != null) {
      feeSent = s;
      break;
    }
  }
  final principal = feeSent != null ? parseAmount(feeSent.quote) : null;
  var payClauses = ctx.clauses
      .where(
        (cl) => RegExp(
          r'(分\s*[一二两三四五六七八九十\d]{1,3}\s*期|分\s*[一二两三四五六七八九十\d]{1,3}\s*个?月|每期(?:还款|应还|偿还|支付)?|月供|每月(?:还款|应还|支付)|还款计划|先学后付|边学边付|学费分期)',
        ).hasMatch(cl.full),
      )
      .toList();
  if (payClauses.isEmpty) {
    payClauses = ctx.clauses
        .where(
          (cl) =>
              RegExp(r'(分期|贷款|借款|放款|助学贷款|培训贷|分期平台|贷款机构|出借人|资方)')
                  .hasMatch(cl.full),
        )
        .take(1)
        .toList();
  }
  Clause? primaryPay;
  QuoteRef? primaryQ;
  double? primaryOver;
  for (final cPay in payClauses) {
    final t = cPay.full;
    double? periods;
    double? per;
    double? feePer;
    double? perTotal;
    double? total;
    double? over;
    var m = RegExp(r'(?:分|共)\s*([一二两三四五六七八九十\d]{1,3})\s*(?:期|个?月)')
        .firstMatch(t);
    if (m != null) {
      final n = cnNum(m.group(1));
      if (n.isFinite) periods = n;
    }
    m = RegExp(
      r'(?:每期还款|每期应还|每期偿还|每期支付|每月还款|每月应还|月供|每期)[^。；\n]{0,16}?([\d,]+(?:\.\d+)?)\s*(万元|万|千元|千|元)',
    ).firstMatch(t);
    if (m != null) per = parseAmount(m.group(0));
    m =
        RegExp(
          r'(?:平台服务费|技术服务费|咨询服务费|服务费|管理费|手续费|担保费|保险费)[^。；\n]{0,18}?([\d,]+(?:\.\d+)?)\s*(万元|万|千元|千|元)',
        ).firstMatch(t) ??
        RegExp(
          r'([\d,]+(?:\.\d+)?)\s*(万元|万|千元|千|元)[^。；\n]{0,10}(?:平台服务费|技术服务费|咨询服务费|服务费|管理费|手续费|担保费|保险费)',
        ).firstMatch(t);
    if (m != null) feePer = parseAmount(m.group(0));
    m = RegExp(
      r'(?:还款总额|共还|共计还款|总还款|本息合计|合计还款)[^。；\n]{0,16}?([\d,]+(?:\.\d+)?)\s*(万元|万|千元|千|元)',
    ).firstMatch(t);
    if (m != null) total = parseAmount(m.group(0));
    if (per != null) perTotal = per + (feePer ?? 0);
    if (total == null &&
        periods != null &&
        periods != 0 &&
        perTotal != null &&
        perTotal != 0) {
      total = periods * perTotal;
    }
    if (total != null &&
        total != 0 &&
        principal != null &&
        principal != 0 &&
        total > principal) {
      over = total - principal;
    }
    final q =
        qFilter(cPay, RegExp(r'(平台服务费|技术服务费|咨询服务费|服务费|管理费|分期|每期|月供)')) ??
        qAny(cPay, RegExp(r'(分期|每期|月供)'));
    final detailed =
        periods != null && periods != 0 && perTotal != null && perTotal != 0;
    final cons = detailed
        ? '分 ${jsNum(periods)} 期、每期 ${fmtYuan(perTotal)} 元，共还 ${fmtYuan(total)} 元${over != null && over != 0 ? '，比 ${fmtYuan(principal)} 元本金多 ${fmtYuan(over)} 元' : ''}；放款主体和年化成本没写清。'
        : '把培训费拆成分期贷款，但没写清放款主体和年化综合成本；签了之后还款义务先落在你身上。';
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.yellow,
        ruleName: '分期贷款与信息披露',
        short: over != null && over != 0
            ? '${jsNum(periods!)} 期多付 ${fmtYuan(over)} 元'
            : '分期贷款信息不清',
        clauseIndex: cPay.index,
        location: clauseLabel(cPay, cPay.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: cons,
        ask: '机构：放款人是谁？含服务费的年化综合成本是多少？',
        counter: '把放款主体、年化成本、提前结清和退费写进同一份协议。',
        basis: law['LPR25'],
        confidence: periods != null && periods != 0 && per != null && per != 0
            ? '高'
            : '中',
        loss: over ?? 0,
      ),
    );
    if (over != null && over != 0 && primaryPay == null) {
      primaryPay = cPay;
      primaryQ = q;
      primaryOver = over;
    }
  }
  if (primaryPay != null) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.gray,
        ruleName: '利率是否超过司法上限',
        short: '利率可能超 LPR 四倍',
        clauseIndex: primaryPay.index,
        location: clauseLabel(primaryPay, primaryPay.index),
        quote: primaryQ?.quote ?? '',
        range: primaryQ,
        consequence:
            '按合同数字共多付 ${fmtYuan(primaryOver)} 元；是否超过签约时一年期 LPR 四倍，要拿签约当月 LPR 和真实年化核算。',
        ask: '签约当月一年期 LPR 是多少？真实年化多少？',
        counter: '要求按不高于 LPR 四倍重算，并写明年化综合成本。',
        basis: law['LPR25'],
        loss: primaryOver ?? 0,
      ),
    );
  }
  for (final cP in ctx.clauses.where(
    (cl) =>
        RegExp(r'(逾期|罚息|滞纳金)').hasMatch(cl.full) &&
        RegExp(r'(违约金|罚息|滞纳金)').hasMatch(cl.full),
  )) {
    final q = qFilter(cP, RegExp(r'(逾期|罚息|滞纳金|违约金)'));
    final src = q != null ? q.raw : cP.body;
    final rate = parseRate(src);
    if (rate.rate != null) {
      final thirty = double.parse((rate.rate! * 30).toStringAsFixed(2));
      _addItem(
        ctx,
        _ItemData(
          base: 'R9',
          ruleId: 'R9',
          verdict: Verdict.yellow,
          ruleName: '逾期违约金过高',
          short:
              '逾期${rate.daily
                  ? '日息'
                  : rate.monthly
                  ? '月'
                  : ''} ${jsNum(rate.rate!)}%',
          clauseIndex: cP.index,
          location: clauseLabel(cP, cP.index),
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '逾期${rate.daily ? '一天' : ''}加收未还金额的 ${jsNum(rate.rate!)}%${rate.daily ? '，30 天就是 ${jsNum(thirty)}%' : ''}；这笔违约金可请求调减，但催收和征信影响会先发生。',
          ask: '机构：逾期违约金为什么按${rate.daily ? '日 ' : ''}${jsNum(rate.rate!)}% 计？',
          counter: '改为不超过 LPR 四倍折算的逾期利率，删除开口的费用条款。',
          basis: law['C585'],
          confidence: '高',
        ),
      );
    } else {
      _addItem(
        ctx,
        _ItemData(
          base: 'R9',
          ruleId: 'R9',
          verdict: Verdict.gray,
          ruleName: '逾期费用未写上限',
          short: '逾期费用没写清',
          clauseIndex: cP.index,
          location: clauseLabel(cP, cP.index),
          quote: q?.quote ?? '',
          range: q,
          consequence: '写了逾期要收费，但没有写清比例或上限；一旦晚还，费用可能越滚越大，必须在签约前问明。',
          ask: '机构：逾期一天收多少？有没有封顶？',
          counter: '写明逾期利率和上限，且不超过司法保护范围。',
          basis: law['C585'],
        ),
      );
    }
  }
  for (final cR in ctx.clauses.where(
    (cl) =>
        RegExp(r'(不予退还|不退)').hasMatch(cl.full) ||
        RegExp(r'(剩余|未付|未还)[^。；\n]{0,20}一次性结清').hasMatch(cl.full),
  )) {
    final q = qAny(cR, RegExp(r'(不予退还|不退|一次性结清)'));
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.gray,
        ruleName: '退费与解约限制',
        short: '开课后不退费',
        clauseIndex: cR.index,
        location: clauseLabel(cR, cR.index),
        quote: q?.quote ?? '',
        range: q,
        consequence:
            '开课后不退费${RegExp(r'一次性结清').hasMatch(cR.body) ? '，退学还要一次性结清剩余分期' : ''}；这类格式条款是否有效要看培训实际履行情况，退不成时先固定课时与服务证据。',
        ask: '机构：开课前、开课后分别怎么退？剩余分期能否停止？',
        counter: '写明按已上课时比例退费；退学后未发生的贷款停止计息。',
        basis: law['C497'],
      ),
    );
  }
  final refundFeeRe = RegExp(
    r'(?:退费|退款)[^。；\n]{0,24}(?:扣除|扣收|收取)[^。；\n]{0,14}(?:手续费|违约金|服务费|管理费)|(?:扣除|扣收)[^。；\n]{0,14}(?:手续费|违约金)[^。；\n]{0,20}(?:退费|退款|退还)',
  );
  for (final cR in ctx.clauses.where((cl) => refundFeeRe.hasMatch(cl.full))) {
    final q = qFilter(cR, refundFeeRe) ?? qAny(cR, RegExp(r'(退费|退款|手续费|违约金)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.yellow,
        ruleName: '退费扣手续费或违约金',
        short: '退费要扣手续费',
        clauseIndex: cR.index,
        location: clauseLabel(cR, cR.index),
        quote: q.quote,
        range: q,
        consequence: '退费要扣手续费或违约金，但扣多少、对应什么成本没写清；真退学时可能先扣一笔，再让你继续还剩余分期。',
        ask: '机构：退费手续费按什么比例？对应哪些已发生成本？',
        counter: '按已上课时和已发生费用结算，未发生的学费与分期应停止。',
        basis: law['C497'],
      ),
    );
  }
  final upfrontRe = RegExp(
    r'(砍头息|前置利息|预先扣除[^。；\n]{0,10}(?:服务费|利息|手续费)|先扣[^。；\n]{0,10}(?:服务费|利息|手续费))',
  );
  for (final cU in ctx.clauses.where((cl) => upfrontRe.hasMatch(cl.full))) {
    final q = qFilter(cU, upfrontRe) ?? qAny(cU, RegExp(r'(砍头息|前置利息|预先扣除|先扣)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.yellow,
        ruleName: '贷款费用预先扣除',
        short: '预扣服务费或利息',
        clauseIndex: cU.index,
        location: clauseLabel(cU, cU.index),
        quote: q.quote,
        range: q,
        consequence: '放款前先扣服务费、利息或手续费，实际到手会少于合同本金，但还款仍按合同本金计算；真实年化成本会被抬高。',
        ask: '机构：实际放款金额是多少？预扣费用是否计入年化成本？',
        counter: '按实际到手金额计算本金和年化成本，所有费用写入同一份披露表。',
        basis: law['LPR25'],
      ),
    );
  }
  final advanceRe = RegExp(
    r'(提前(?:还款|结清|还清))[^。；\n]{0,24}(?:违约金|手续费|服务费|不予减免|仍需支付全部利息)|(?:违约金|手续费|服务费)[^。；\n]{0,20}(?:提前(?:还款|结清|还清))',
  );
  for (final cA in ctx.clauses.where((cl) => advanceRe.hasMatch(cl.full))) {
    final q = qFilter(cA, advanceRe) ?? qAny(cA, RegExp(r'(提前还款|提前结清|提前还清)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.gray,
        ruleName: '提前结清仍收费用',
        short: '提前还款仍收费',
        clauseIndex: cA.index,
        location: clauseLabel(cA, cA.index),
        quote: q.quote,
        range: q,
        consequence: '提前还款仍要收违约金、手续费或全部利息；想早点止损时，实际结清金额可能高于剩余本金。',
        ask: '机构：提前结清要付多少？剩余利息能否减免？',
        counter: '写明提前结清公式，未发生的利息和管理费不再收取。',
        basis: law['C585'],
      ),
    );
  }
  final agencyRe = RegExp(
    r'(?:贷款|分期)[^。；\n]{0,24}(?:由甲方|由机构|由平台)[^。；\n]{0,10}(?:代办|代签|代为办理|操作)|(?:代(?:为)?(?:办理|申请|签署))[^。；\n]{0,12}(?:贷款|分期)|(?:签署本协议即视为同意)[^。；\n]{0,16}(?:贷款|分期)',
  );
  for (final cG in ctx.clauses.where((cl) => agencyRe.hasMatch(cl.full))) {
    final q = qFilter(cG, agencyRe) ?? qAny(cG, RegExp(r'(贷款|分期|代签|代办|视为同意)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R9',
        ruleId: 'R9',
        verdict: Verdict.yellow,
        ruleName: '贷款由机构代办或默示同意',
        short: '签协议即视为同意贷款',
        clauseIndex: cG.index,
        location: clauseLabel(cG, cG.index),
        quote: q.quote,
        range: q,
        consequence: '签培训协议就被视为同意贷款，或由机构代为操作；你可能没看到借款合同、放款人和真实利率，就已经背上还款义务。',
        ask: '机构：贷款合同和放款人是谁？能否先看完整借款合同再签字？',
        counter: '培训协议与贷款合同分开签署，单独确认放款主体、金额、利率和退费。',
        basis: law['C497'],
      ),
    );
  }
  Clause? cCourse;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(培训项目|培训周期|培训费)').hasMatch(cl.full) &&
        parseAmount(cl.body) != null) {
      cCourse = cl;
      break;
    }
  }
  addGreen(ctx, cCourse, '培训项目与周期', RegExp(r'(培训周期|培训费)'), '培训项目、周期和总费用已写明。');
}

/* R10 实习协议 */
void runR10(_Ctx ctx) {
  final selfInsRe = RegExp(
    r'(乙方|学生|实习生|本人)[^。；\n]{0,18}(自行|自己|本人)[^。；\n]{0,12}(购买|投保|承担)[^。；\n]{0,12}(保险|意外)|(保险|意外)[^。；\n]{0,12}(由乙方|自行|自理)',
  );
  final positiveInsRe = RegExp(
    r'(甲方|实习单位|公司|学校)[^。；\n]{0,26}(购买|投保|缴纳|办理|承担)[^。；\n]{0,16}(意外伤害保险|意外险|实习责任保险)|(购买|投保)[^。；\n]{0,16}(意外伤害保险|意外险|实习责任保险)',
  );
  final selfIns = selfInsRe.hasMatch(ctx.text);
  final hasIns = positiveInsRe.hasMatch(ctx.text) && !selfIns;
  if (!hasIns) {
    Clause? cSelf;
    if (selfIns) {
      for (final cl in ctx.clauses) {
        if (selfInsRe.hasMatch(cl.full)) {
          cSelf = cl;
          break;
        }
      }
    }
    Clause? cSafe = cSelf;
    if (cSafe == null) {
      for (final cl in ctx.clauses) {
        if (RegExp(r'(安全|意外|伤害|不承担责任|保险)').hasMatch(cl.full)) {
          cSafe = cl;
          break;
        }
      }
    }
    QuoteRef? q;
    if (cSafe != null) {
      q =
          qFilter(cSafe, RegExp(r'(不承担责任|保险|意外)')) ??
          qFilter(cSafe, RegExp(r'(安全|意外)')) ??
          qAny(cSafe, RegExp(r'(保险|意外|安全|不承担责任)'));
    }
    final extra = RegExp(r'不承担责任|概不负责').hasMatch(cSafe?.full ?? '');
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习意外伤害保险缺失',
        short: selfIns ? '意外险要你自己买' : '缺少意外伤害保险',
        clauseIndex: cSafe?.index,
        location: cSafe != null ? clauseLabel(cSafe, cSafe.index) : '全文',
        quote: q?.quote ?? '',
        range: q,
        consequence: selfIns
            ? '协议把意外伤害保险推给你自己购买${extra ? '，还写了意外不承担责任' : ''}；实习期间受伤，医疗费和误工可能没有保险兜底。'
            : '全文没有意外伤害保险约定${extra ? '，还写了意外不承担责任' : ''}；实习期间受伤，医疗费和误工可能没有保险兜底。',
        ask: 'HR 或学校：实习责任险或意外险由谁买？保额多少？',
        counter: '写入由甲方投保实习责任保险 / 意外伤害保险，并把保单作为附件。',
        basis: law['R10'],
      ),
    );
  }
  final noPayRe = RegExp(
    r'(?:无薪|无偿|不支付(?:实习)?(?:补贴|报酬|工资)|没有(?:实习)?(?:补贴|报酬|工资))',
  );
  for (final cNoPay in ctx.clauses.where((cl) => noPayRe.hasMatch(cl.full))) {
    final q =
        qFilter(cNoPay, noPayRe) ?? qAny(cNoPay, RegExp(r'(无薪|无偿|不支付|没有)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '无薪或无偿实习',
        short: '无薪实习',
        clauseIndex: cNoPay.index,
        location: clauseLabel(cNoPay, cNoPay.index),
        quote: q.quote,
        range: q,
        consequence: '协议明确不支付补贴或报酬；短期体验尚可，但如果按固定工时承担实际工作，既没有收入，也可能掩盖应得的劳动报酬。',
        ask: 'HR：实习补贴为什么没有？每月出勤和请假怎么算？',
        counter: '写明补贴标准与发放日；实际承担岗位工作的，按约定支付报酬。',
        basis: law['C470'],
      ),
    );
  }
  final hoursRe = RegExp(
    r'每周[^。；\n]{0,12}(?:[6六]\s*天|超过\s*40\s*小时)|(?:单休|做六休一|996|007)|每(?:日|天)[^。；\n]{0,10}(?:工作|实习)?(?:9|10|11|12)\s*小时',
  );
  for (final cH in ctx.clauses.where((cl) => hoursRe.hasMatch(cl.full))) {
    final q = qFilter(cH, hoursRe) ?? qAny(cH, RegExp(r'(每周|每天|单休|996)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习工时偏高',
        short: '实习工时超过 40 小时/周',
        clauseIndex: cH.index,
        location: clauseLabel(cH, cH.index),
        quote: q.quote,
        range: q,
        consequence:
            '每周 6 天、单休或每天 9 小时以上，工时已接近或超过标准工时；实习协议不当然排除劳动保护，长期超时还会挤占课程和休息。',
        ask: 'HR：每周实际实习几天、每天几小时？超时怎么调休或补贴？',
        counter: '写明每周上限、休息日和超时处理，避免把实习生当全职员工使用。',
        basis: law['C470'],
      ),
    );
  }
  final internFeeRe = RegExp(r'(押金|保证金|培训费|服装费|工装费|体检费|管理费|建档费|报名费|设备费)');
  final internFeePayRe = RegExp(r'(交纳|缴纳|收取|支付|从补贴[^。；\n]{0,8}扣)');
  for (final cF in ctx.clauses.where((cl) {
    final t = cl.full;
    return internFeeRe.hasMatch(t) &&
        internFeePayRe.hasMatch(t) &&
        !RegExp(r'(甲方|实习单位|公司)[^。；\n]{0,14}(承担|支付|报销)').hasMatch(t);
  })) {
    final q =
        qFilter(
          cF,
          internFeeRe,
          RegExp(r'(甲方|实习单位|公司)[^。；\n]{0,14}(承担|支付|报销)'),
        ) ??
        qAny(cF, internFeeRe);
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '向实习生收费或收押金',
        short: '实习要交押金或费用',
        clauseIndex: cF.index,
        location: clauseLabel(cF, cF.index),
        quote: q.quote,
        range: q,
        consequence: '实习还要交押金、培训费或服装费；这笔钱可能以“违约”“损坏”“未满期”为由不退，事后追要成本很高。',
        ask: 'HR：这笔费用对应什么成本？有没有收据和退还条件？',
        counter: '删除向学生收费的条款；必要的工装和设备由实习单位提供。',
        basis: law['C470'],
      ),
    );
  }
  final renewRe = RegExp(r'(?:自动续期|自动延长|单方延长|期满后继续有效|未提出异议视为续期)');
  for (final cRn in ctx.clauses.where((cl) => renewRe.hasMatch(cl.full))) {
    final q = qFilter(cRn, renewRe) ?? qAny(cRn, RegExp(r'(续期|延长|继续有效)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习协议自动续期',
        short: '实习协议自动续期',
        clauseIndex: cRn.index,
        location: clauseLabel(cRn, cRn.index),
        quote: q.quote,
        range: q,
        consequence: '协议可自动续期或由单位单方延长；到期后你可能在不知情的情况下继续受约束，影响返校、考试和找工作。',
        ask: 'HR：续期需要谁确认？每次续多久？',
        counter: '改为双方书面确认后续期，到期自动终止。',
        basis: law['C562'],
      ),
    );
  }
  final noLaborRe = RegExp(r'(?:不构成|不属于|并非)[^。；\n]{0,8}劳动关系');
  for (final cN in ctx.clauses.where((cl) => noLaborRe.hasMatch(cl.full))) {
    final q = qFilter(cN, noLaborRe) ?? qAny(cN, RegExp(r'(不构成|不属于|劳动关系)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.gray,
        ruleName: '实习关系被单方定性',
        short: '协议否认劳动关系',
        clauseIndex: cN.index,
        location: clauseLabel(cN, cN.index),
        quote: q.quote,
        range: q,
        consequence:
            '协议声明不构成劳动关系。实习通常确实不按劳动关系处理，但如果实际存在固定岗位、考勤、绩效和持续报酬，仍可能被认定为劳动关系。',
        ask: 'HR 或学校：这份实习是否在学校的实习计划内？日常是否按员工考核？',
        counter: '保留实习计划、考勤、报酬和管理记录，必要时再判断关系性质。',
        basis: law['C470'],
      ),
    );
  }
  final endRe = RegExp(
    r'(甲方|实习单位|公司)[^。；\n]{0,26}(随时|有权|可以)[^。；\n]{0,18}(终止|解除)|(甲方|实习单位|公司)[^。；\n]{0,26}(无需|不需|不必)(?:说明)?理由',
  );
  for (final cEnd in ctx.clauses.where((cl) => endRe.hasMatch(cl.full))) {
    final q =
        qFilter(cEnd, RegExp(r'(随时(?:终止|解除)|无需(?:说明)?理由)')) ??
        qFilter(cEnd, RegExp(r'(终止|解除)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习解除条件不对等',
        short: '公司可随时终止实习',
        clauseIndex: cEnd.index,
        location: clauseLabel(cEnd, cEnd.index),
        quote: q.quote,
        range: q,
        consequence: '公司可以随时终止实习且不用说明理由；你为实习租的房、推掉的课可能落空，实习证明也未必拿得到。',
        ask: 'HR：终止实习要提前几天通知？能写明理由吗？',
        counter: '改为双方提前 7 日书面通知；单方终止需说明理由并结清补贴。',
        basis: law['C562'],
        confidence: '高',
      ),
    );
  }
  final payWord = RegExp(r'(补贴|报酬|工资|实习补助)');
  Clause? payClause;
  for (final cl in ctx.clauses) {
    if (payWord.hasMatch(cl.full) && parseAmount(cl.body) != null) {
      payClause = cl;
      break;
    }
  }
  if (!payWord.hasMatch(ctx.text)) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习报酬未约定',
        short: '实习报酬未约定',
        consequence: '没写补贴标准和发放时间；干了几个月也可能拿不到钱，事后追要时说不清标准。',
        ask: 'HR：实习补贴多少、每月几号发？',
        counter: '写明金额、发放日和不足整月的折算方式。',
        basis: law['C470'],
        confidence: '高',
      ),
    );
  } else if (payClause == null) {
    Clause? cP;
    for (final cl in ctx.clauses) {
      if (payWord.hasMatch(cl.full)) {
        cP = cl;
        break;
      }
    }
    final q = cP != null ? qAny(cP, payWord) : null;
    _addItem(
      ctx,
      _ItemData(
        base: 'R10',
        ruleId: 'R10',
        verdict: Verdict.yellow,
        ruleName: '实习报酬标准未写明',
        short: '实习报酬没写金额',
        clauseIndex: cP?.index,
        location: cP != null ? clauseLabel(cP, cP.index) : '全文',
        quote: q?.quote ?? '',
        range: q,
        consequence: '提到了补贴或报酬，但没写具体金额和发放时间；干了几个月也可能说不清该拿多少。',
        ask: 'HR：实习补贴多少、每月几号发？',
        counter: '写明金额、发放日和不足整月的折算方式。',
        basis: law['C470'],
      ),
    );
  }
  Clause? cTerm;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(实习期|实习期限)').hasMatch(cl.full) &&
        RegExp(r'\d{4}\s*年').hasMatch(cl.full)) {
      cTerm = cl;
      break;
    }
  }
  addGreen(ctx, cTerm, '实习期限', RegExp(r'(实习期|实习期限)'), '实习起止日期完整。');
  addGreen(ctx, payClause, '实习报酬', RegExp(r'(补贴|报酬)'), '报酬标准、发放时间与折算方式已写明。');
  Clause? cHours;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(每日|每天|每周)[^。；\n]{0,14}(小时|天)').hasMatch(cl.full)) {
      cHours = cl;
      break;
    }
  }
  addGreen(ctx, cHours, '实习工时', RegExp(r'(每日|每天|每周)'), '每周天数与每日时段已写明。');
  if (hasIns) {
    Clause? cIns;
    for (final cl in ctx.clauses) {
      if (positiveInsRe.hasMatch(cl.full)) {
        cIns = cl;
        break;
      }
    }
    addGreen(ctx, cIns, '意外伤害保险', RegExp(r'(保险|意外)'), '意外伤害保险由单位投保，属常规安排。');
  }
}

/* R11 押金与扣证 */
void runR11(_Ctx ctx) {
  final feeRe = RegExp(
    r'(押金|保证金|抵押金|担保金|风险金|风险抵押金|履约保证金|保密保证金|培训押金|服装费|工装费|工服费|工牌费|体检费|培训费|入职费|管理费|建档费|报名费|设备费|工具费|资料费|电脑押金|住宿押金|水电押金|背景调查费|招聘费|集资款|入股款)',
  );
  final payRe = RegExp(r'(交纳|缴纳|收取|交付|支付|预交|预缴|代收|扣留|扣除|从工资[^。；\n]{0,8}扣)');
  final employerPayRe = RegExp(r'(甲方|公司|用人单位)[^。；\n]{0,14}(承担|支付|提供|报销|退还)');
  for (final cDep in ctx.clauses) {
    _Span? sentence;
    for (final s in sentenceList(cDep.full)) {
      if (feeRe.hasMatch(s.quote) &&
          payRe.hasMatch(s.quote) &&
          !employerPayRe.hasMatch(s.quote)) {
        sentence = s;
        break;
      }
    }
    if (sentence == null) continue;
    final kindM = feeRe.firstMatch(sentence.quote);
    final kind = kindM != null ? kindM.group(1)! : '费用';
    final deposit = RegExp(r'押金|保证金|抵押金|担保金|风险金|集资款|入股款').hasMatch(kind);
    final amt = amountNear(sentence.quote, feeRe);
    final fm = feeRe.firstMatch(sentence.quote);
    final q = fm != null
        ? QuoteRef(
            clipQuote(sentence.quote, fm.start, fm.end),
            sentence.quote,
            start: sentence.start,
            end: sentence.end,
          )
        : null;
    _addItem(
      ctx,
      _ItemData(
        base: 'R11',
        ruleId: 'R11',
        verdict: Verdict.red,
        ruleName: deposit ? '向劳动者收取押金或保证金' : '以其他名义向劳动者收费',
        short: amt != null && amt != 0 ? '${fmtWan(amt)}$kind' : '收取$kind',
        clauseIndex: cDep.index,
        location: clauseLabel(cDep, cDep.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: deposit
            ? '入职先交 ${amt != null && amt != 0 ? '${fmtYuan(amt)} 元' : ''}$kind；离职时可能以各种理由不退，向劳动者收这笔钱本身不合法，追回要凭收据并投诉。'
            : '入职先交 ${amt != null && amt != 0 ? '${fmtYuan(amt)} 元' : ''}$kind；以其他名义向劳动者收费同样被禁止，这笔钱可能退不回来。',
        ask: 'HR：这笔$kind依据什么规定收取？',
        counter: '删除收取$kind的条款；已交的出具收据并无条件退还。',
        basis: law['L09'],
        confidence: '高',
        loss: amt ?? 0,
      ),
    );
  }
  final guaranteeRe = RegExp(
    r'(?:要求|需|须|应)[^。；\n]{0,12}(?:乙方|劳动者|员工)[^。；\n]{0,10}(?:提供|找|出具)[^。；\n]{0,10}(?:担保|保证人)|(?:担保人|保证人)[^。；\n]{0,14}(?:签字|提供|承担连带)',
  );
  for (final cG in ctx.clauses.where((cl) => guaranteeRe.hasMatch(cl.full))) {
    final q = qFilter(cG, guaranteeRe) ?? qAny(cG, RegExp(r'(担保|保证人|连带)'));
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R11',
        ruleId: 'R11',
        verdict: Verdict.red,
        ruleName: '要求劳动者提供担保',
        short: '要求提供担保人',
        clauseIndex: cG.index,
        location: clauseLabel(cG, cG.index),
        quote: q.quote,
        range: q,
        consequence: '入职还要求担保人或连带责任保证；用人单位招用劳动者不得要求提供担保，这类条款会把你和家人的财产一起卷进来。',
        ask: 'HR：为什么要求提供担保？依据是什么？',
        counter: '删除担保条款；如涉及财物保管，用岗位制度和交接清单解决。',
        basis: law['L09'],
        confidence: '高',
      ),
    );
  }
  final idRe = RegExp(r'(扣押|扣留|收走|收缴|保管)');
  final certRe = RegExp(r'(身份证|毕业证|学位证|学历证|资格证|证件|证书|户口本|护照)');
  final keepCopyRe = RegExp(
    r'(乙方|本人)[^。；\n]{0,8}(自行|自己)[^。；\n]{0,4}保管|复印件|扫描件|影印件',
  );
  for (final cId in ctx.clauses.where(
    (cl) => idRe.hasMatch(cl.full) && certRe.hasMatch(cl.full),
  )) {
    final q = qFilter(cId, RegExp(r'(扣押|扣留|收走|收缴|保管|原件)'), keepCopyRe);
    if (q == null) continue;
    _addItem(
      ctx,
      _ItemData(
        base: 'R11',
        ruleId: 'R11',
        verdict: Verdict.red,
        ruleName: '扣押证件',
        short: '扣留证件',
        clauseIndex: cId.index,
        location: clauseLabel(cId, cId.index),
        quote: q.quote,
        range: q,
        consequence: '公司扣下你的证件，出行、入职、办卡都会被卡住；扣押证件本身被法律禁止，先要回证件再谈其他。',
        ask: 'HR：为什么要收走证件？什么时候归还？',
        counter: '删除扣押条款；入职核验后当场归还。',
        basis: law['L09'],
        confidence: '高',
      ),
    );
  }
}

/* R12 解除与通知期 */
class _Notice {
  final double days;
  final QuoteRef ref;
  _Notice(this.days, this.ref);
}

void runR12(_Ctx ctx) {
  final noticeRe = RegExp(r'(离职|辞职|解除|终止)');
  final employeeRe = RegExp(r'(乙方|劳动者|员工|本人)');
  final employerRe = RegExp(r'(甲方|公司|用人单位|雇主)');
  final employeeLeaningRe = RegExp(r'(辞职|离职|劳动者)');
  String subjectOf(String sentence, String heading, int matchIndex) {
    final before = sentence.substring(0, matchIndex);
    final employeeAt = [
      before.lastIndexOf('乙方'),
      before.lastIndexOf('劳动者'),
      before.lastIndexOf('员工'),
      before.lastIndexOf('本人'),
    ].reduce((a, b) => a > b ? a : b);
    final employerAt = [
      before.lastIndexOf('甲方'),
      before.lastIndexOf('公司'),
      before.lastIndexOf('用人单位'),
      before.lastIndexOf('雇主'),
    ].reduce((a, b) => a > b ? a : b);
    if (employeeAt > employerAt) return 'employee';
    if (employerAt > employeeAt) return 'employer';
    if (employeeRe.hasMatch(heading)) return 'employee';
    if (employerRe.hasMatch(heading)) return 'employer';
    return 'unknown';
  }

  for (final c in ctx.clauses.where(
    (cl) =>
        RegExp(r'提前[^。；\n]{0,12}(日|天|个?工作日|个?自然日|个?日历日|个月|月|周|星期)')
            .hasMatch(cl.full) &&
        noticeRe.hasMatch(cl.full),
  )) {
    final isTrial = RegExp(r'试用期').hasMatch(c.full);
    _Notice? found;
    _Notice? trialFound;
    final noticeSentences = sentenceList(c.body);
    final hasTrialSentence = noticeSentences.any(
      (s) => RegExp(r'试用期').hasMatch(s.quote),
    );
    for (final s in noticeSentences) {
      final re = RegExp(
        r'提前\s*([一二两三四五六七八九十百零〇\d]{1,4})\s*(个?工作日|个?自然日|个?日历日|日|天|个月|月|周|星期)',
      );
      for (final m in re.allMatches(s.quote)) {
        final n = cnNum(m.group(1));
        if (!n.isFinite) continue;
        var days = n;
        final unit = m.group(2)!;
        if (unit == '个月' || unit == '月') {
          days = n * 30;
        } else if (unit == '周' || unit == '星期') {
          days = n * 7;
        } else if (RegExp(r'工作日').hasMatch(unit)) {
          days = (n * 7 / 5).roundToDouble();
        }
        final subject = subjectOf(s.quote, c.heading, m.start);
        if (subject == 'employer') continue;
        if (subject == 'unknown' && !employeeLeaningRe.hasMatch(s.quote)) {
          continue;
        }
        final candidate = _Notice(
          days,
          QuoteRef(
            clipQuote(s.quote, m.start, m.end),
            s.quote,
            start: s.start,
            end: s.end,
          ),
        );
        final trialAt = s.quote.indexOf('试用期');
        final matchTrial = trialAt >= 0
            ? m.start >= trialAt
            : (isTrial && !hasTrialSentence);
        if (matchTrial &&
            days > 3 &&
            days <= 30 &&
            (trialFound == null || days > trialFound.days)) {
          trialFound = candidate;
        }
        if (!matchTrial && days > 30 && (found == null || days > found.days)) {
          found = candidate;
        }
      }
    }
    if (found != null) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R12',
          ruleId: 'R12',
          verdict: Verdict.gray,
          ruleName: '离职通知期高于法定 30 天',
          short: '${jsNum(found.days)} 天离职通知期',
          clauseIndex: c.index,
          location: clauseLabel(c, c.index),
          quote: found.ref.quote,
          range: found.ref,
          consequence:
              '合同要求你提前 ${jsNum(found.days)} 天通知离职，高于法定的 30 天；多出的时间可能拖住下家和入职，超出部分是否有效要个案判断。',
          ask: 'HR：这条通知期能否按法定 30 天执行？',
          counter: '改为提前 30 日书面通知，试用期内提前 3 日。',
          basis: law['L37'],
        ),
      );
    } else if (trialFound != null) {
      _addItem(
        ctx,
        _ItemData(
          base: 'R12',
          ruleId: 'R12',
          verdict: Verdict.gray,
          ruleName: '试用期通知期高于法定 3 天',
          short: '试用期 ${jsNum(trialFound.days)} 天通知期',
          clauseIndex: c.index,
          location: clauseLabel(c, c.index),
          quote: trialFound.ref.quote,
          range: trialFound.ref,
          consequence:
              '合同要求试用期离职提前 ${jsNum(trialFound.days)} 天通知，高于法定的 3 天；多出的通知时间可能被公司拿来做交接或拖延。',
          ask: 'HR：试用期离职能否按法定 3 天执行？',
          counter: '改为试用期内提前 3 日通知，转正后提前 30 日书面通知。',
          basis: law['L37'],
        ),
      );
    }
  }
}

/* R13 工时与加班费 */
void runR13(_Ctx ctx) {
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final waiverRe = RegExp(
    r'(?:加班费|加班工资|加班报酬)[^。；\n]{0,32}(?:不再|不另|无需|无须|不予|不支付|不计算|不计发|包含(?:在|于)[^。；\n]{0,10}(?:工资|薪资|月薪)|已包含|已含)|(?:放弃|不要求|自愿放弃)[^。；\n]{0,14}(?:加班费|加班工资|加班报酬)',
  );
  final waiverC = find(waiverRe);
  if (waiverC != null) {
    addPatternItem(
      ctx,
      waiverC,
      _ItemData(
        base: 'R13',
        ruleId: 'R13',
        verdict: Verdict.red,
        ruleName: '加班费被排除或已包含',
        short: '不另付加班费',
        consequence:
            '合同把加班费排除掉，或写成工资已经包含加班费；只要实际存在单位安排的加班，仍应按法定标准补足，但你要先证明加班事实。',
        ask: 'HR：加班费按什么基数、什么比例计算？',
        counter: '删除“不再支付/已包含”的写法，按 150%/200%/300% 法定标准另行列明。',
        basis: law['L44'],
        confidence: '高',
      ),
      waiverRe,
    );
  }
  final holidayRe = RegExp(
    r'(?:法定节假日|法定假日)[^。；\n]{0,32}(?:安排调休|调休|补休)[^。；\n]{0,22}(?:不(?:再)?支付|无需支付|不另支付)|(?:法定节假日|法定假日)[^。；\n]{0,24}(?:按|只按|仅按)(?:正常工资|基本工资|1(?:\.0)?倍|一(?:倍|倍工资)|100\s*%)(?:支付|计算|计发)?',
  );
  final holidayC = find(holidayRe);
  if (holidayC != null) {
    addPatternItem(
      ctx,
      holidayC,
      _ItemData(
        base: 'R13',
        ruleId: 'R13',
        verdict: Verdict.red,
        ruleName: '法定节假日加班只调休或按一倍算',
        short: '法定节假日加班费不足',
        consequence: '法定节假日加班不能只用调休替代，也不应按正常工资计算；依法应支付不低于 300% 的工资报酬。',
        ask: 'HR：法定节假日加班的 300% 工资怎么发？',
        counter: '按法定节假日 300% 标准支付，不能以调休或正常工资替代。',
        basis: law['L44'],
        confidence: '高',
      ),
      holidayRe,
    );
  }
  final lowBaseRe = RegExp(
    r'(?:加班|加班费|加班工资)[^。；\n]{0,26}(?:按|按照|以)[^。；\n]{0,18}(?:基本工资|底薪|最低工资|当地最低工资|1(?:\.0)?倍|一(?:倍|倍工资)|100\s*%|百分之百)[^。；\n]{0,14}(?:计算|支付|计发|为基数)?',
  );
  final lowBaseC = find(lowBaseRe);
  if (lowBaseC != null) {
    addPatternItem(
      ctx,
      lowBaseC,
      _ItemData(
        base: 'R13',
        ruleId: 'R13',
        verdict: Verdict.yellow,
        ruleName: '加班费计算基数偏低',
        short: '加班费按基本工资或最低工资算',
        consequence:
            '把加班费基数压到基本工资、底薪或最低工资，会让实际加班费低于按正常工资计算的法定标准；差额可以主张，但需要工资条和考勤。',
        ask: 'HR：加班费基数是否包含绩效、补贴等正常工资？',
        counter: '按正常工作时间工资作为加班费基数，并在合同中写清构成。',
        basis: law['L44'],
      ),
      lowBaseRe,
    );
  }
  final scheduleRe = RegExp(
    r'(996|007|朝九晚九|早9晚9|早九晚九|大小周|单休|做六休一|月休[二两三四2-4]天|每月(?:休息|休)[二两三四2-4]天|每周(?:工作)?[6六]天|六天工作制)',
  );
  final scheduleC = find(scheduleRe);
  if (scheduleC != null) {
    final term = scheduleRe.firstMatch(scheduleC.full)?.group(0) ?? '';
    addPatternItem(
      ctx,
      scheduleC,
      _ItemData(
        base: 'R13',
        ruleId: 'R13',
        verdict: Verdict.yellow,
        ruleName: '工时安排超过标准工时风险',
        short: '工时安排：${term.isNotEmpty ? term : '单休/超时'}',
        consequence:
            '合同出现“${term.isNotEmpty ? term : '单休'}”等安排，可能超过每日 8 小时、每周 40 小时的标准工时；如果公司没有经过审批实行综合工时或不定时工时，超时部分应支付加班费。',
        ask: 'HR：公司实行哪种工时制度？综合工时或不定时工时有没有审批？',
        counter: '写明标准工时与休息日；确需轮班的，先确认工时制度审批和加班费。',
        basis: law['L31'],
      ),
      scheduleRe,
    );
  }
  final approvalRe = RegExp(
    r'(?:加班|延时工作)[^。；\n]{0,18}(?:须|需|必须|应)[^。；\n]{0,12}(?:审批|申请|批准|同意)|未经[^。；\n]{0,14}(?:审批|批准)[^。；\n]{0,14}(?:不(?:视为|算作|属于)加班|无加班费|不支付加班费)',
  );
  final approvalC = find(approvalRe);
  if (approvalC != null) {
    addPatternItem(
      ctx,
      approvalC,
      _ItemData(
        base: 'R13',
        ruleId: 'R13',
        verdict: Verdict.gray,
        ruleName: '加班认定受审批限制',
        short: '加班需审批才算',
        consequence:
            '公司规定加班必须事先审批，未审批不算加班；实际被安排加班但没走流程时，你需要用排班、聊天记录、打卡和工作成果证明。',
        ask: 'HR：主管口头安排的加班算不算？审批流程怎么留痕？',
        counter: '保留加班安排和考勤记录；确需审批的，写明补批机制。',
        basis: law['L31'],
      ),
      approvalRe,
    );
  }
  if (!ctx.items.any((it) => it.ruleId == 'R13')) {
    final cGreen = find(
      RegExp(
        r'(?:依法|按法定标准|按照法定标准)[^。；\n]{0,24}(?:支付|计发)?[^。；\n]{0,8}加班费|加班费[^。；\n]{0,20}(?:150%|200%|300%|百分之一百五十|百分之二百|百分之三百)',
      ),
    );
    if (cGreen != null) {
      addGreen(ctx, cGreen, '加班费', RegExp(r'(加班费|加班工资)'), '加班费按法定标准支付，属常规安排。');
    }
  }
}

/* R14 工资支付与扣款 */
void runR14(_Ctx ctx) {
  final r4Clauses = ctx.items
      .where((it) => it.ruleId == 'R4')
      .map((it) => it.clauseIndex)
      .toSet();
  final r13Clauses = ctx.items
      .where((it) => it.ruleId == 'R13')
      .map((it) => it.clauseIndex)
      .toSet();
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (!r4Clauses.contains(cl.index) &&
          !r13Clauses.contains(cl.index) &&
          re.hasMatch(cl.full)) {
        return cl;
      }
    }
    return null;
  }

  final withholdRe = RegExp(
    r'(?:压|押)(?:一个月|1个月|半个月|十五天|15天|两个月|2个月|三十天|30天)?[^。；\n]{0,10}(?:工资|薪资)|(?:工资|薪资)[^。；\n]{0,16}(?:年底|年后|次次月|第三个月|下下月|统一)[^。；\n]{0,10}(?:发放|结算|支付)|(?:离职|辞职)[^。；\n]{0,22}(?:工资|薪资)[^。；\n]{0,14}(?:不(?:予|再)?(?:发放|结算|支付)|暂缓|延后|扣发|扣除|年底|年后|次次月|第三个月|下下月|统一发放)|(?:离职|辞职)[^。；\n]{0,16}(?:不予结算|不结算|不发放工资|视为放弃)',
  );
  final handoverRe = RegExp(
    r'(?:未|不|拒绝)[^。；\n]{0,12}(?:办理|完成|配合|按)[^。；\n]{0,6}(?:交接|离职手续)|(?:交接|离职手续)[^。；\n]{0,16}(?:未|不)[^。；\n]{0,8}(?:办理|完成|配合)',
  );
  var withholdC = find(withholdRe);
  if (withholdC != null && handoverRe.hasMatch(withholdC.full)) {
    withholdC = null;
    for (final cl in ctx.clauses) {
      if (!r4Clauses.contains(cl.index) &&
          !r13Clauses.contains(cl.index) &&
          !handoverRe.hasMatch(cl.full) &&
          withholdRe.hasMatch(cl.full)) {
        withholdC = cl;
        break;
      }
    }
  }
  if (withholdC != null) {
    addPatternItem(
      ctx,
