  if (ctx.items.any((it) => it.ruleId == 'R14')) {
    addPending(ctx, ['工资构成（基本工资/绩效/补贴）、发薪日与扣款制度的具体依据']);
  }
}

/* R15 社保与公积金 */
void runR15(_Ctx ctx) {
  final r7Clauses = ctx.items
      .where((it) => it.ruleId == 'R7')
      .map((it) => it.clauseIndex)
      .toSet();
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (!r7Clauses.contains(cl.index) && re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final delayRe = RegExp(
    r'(?:试用期(?:间|内)?|转正前|转正后|试用期满后|入职满(?:一年|1年)(?:后)?|工作满(?:一年|1年)(?:后)?)[^。；\n]{0,30}(?:不缴|不缴纳|不办理|不参保|无需缴纳|才(?:为|给)?[^。；\n]{0,8}(?:缴纳|办理|参保)|(?:后|再|开始)[^。；\n]{0,10}(?:为|给)?[^。；\n]{0,8}(?:缴纳|办理|参保))',
  );
  final delayC = find(delayRe);
  if (delayC != null) {
    addPatternItem(
      ctx,
      delayC,
      _ItemData(
        base: 'R15',
        ruleId: 'R15',
        verdict: Verdict.red,
        ruleName: '社保未从用工之日起缴纳',
        short: '试用期或满一年后才缴社保',
        consequence:
            '社保应从用工之日起 30 日内办理；试用期不缴、转正后才缴或满一年才缴，都会造成医保、工伤和养老断档，补缴还要另走投诉。',
        ask: 'HR：社保从哪个月开始缴？按什么基数？',
        counter: '删除延迟参保条款，入职当月依法办理社保登记。',
        basis: law['L58'],
        confidence: '高',
      ),
      delayRe,
    );
  }
  final subsidyRe = RegExp(
    r'(?:社保|社会保险|五险)[^。；\n]{0,26}(?:补贴|补助|折现|现金|以工资|随工资|自行缴纳|自己缴纳)|(?:不缴|不办理|不缴纳)[^。；\n]{0,18}(?:社保|社会保险)[^。；\n]{0,22}(?:补贴|补助|折现|补偿)',
  );
  final subsidyC = find(subsidyRe);
  if (subsidyC != null) {
    final selfPayOnly = !RegExp(r'(?:补贴|补助|折现|现金|以工资|随工资)')
        .hasMatch(subsidyC.full);
    addPatternItem(
      ctx,
      subsidyC,
      _ItemData(
        base: 'R15',
        ruleId: 'R15',
        verdict: Verdict.red,
        ruleName: selfPayOnly ? '社保由员工自行承担' : '以补贴代替社保',
        short: selfPayOnly ? '社保全部自己交' : '社保折现或发补贴',
        consequence: selfPayOnly
            ? '合同把社保写成由你个人缴纳或自行承担；单位参保义务不因这种约定转移，但你会先失去医保、工伤和养老记录，补缴还要另走投诉。'
            : '把社保折成现金补贴，表面多拿一点，实际没有医保、工伤和养老记录；这种约定不能免除单位参保义务，但补缴时你也要配合。',
        ask: 'HR：社保是否实际参保？补贴之外还会不会缴？',
        counter: '删除折现或自缴条款，依法参保并按实际工资申报基数。',
        basis: law['L60'],
        confidence: '高',
      ),
      subsidyRe,
    );
  }
  final baseRe = RegExp(
    r'(?:按|以)[^。；\n]{0,18}(?:最低缴费基数|最低基数|最低标准|当地最低工资)[^。；\n]{0,18}(?:缴纳|申报|作为基数|为基数)|(?:未按|不按)[^。；\n]{0,18}(?:实际工资|工资总额|应发工资)[^。；\n]{0,18}(?:缴纳|申报)',
  );
  final baseC = find(baseRe);
  if (baseC != null) {
    addPatternItem(
      ctx,
      baseC,
      _ItemData(
        base: 'R15',
        ruleId: 'R15',
        verdict: Verdict.red,
        ruleName: '社保按最低基数缴纳',
        short: '社保基数被压低',
        consequence: '社保不按实际工资申报，而统一按最低基数缴；每月看似少扣一点，医保个人账户、工伤待遇和养老金都会缩水。',
        ask: 'HR：社保缴费基数按多少申报？是否包含绩效和补贴？',
        counter: '按实际工资总额申报社保基数，并在工资条中列明。',
        basis: law['L60'],
        confidence: '高',
      ),
      baseRe,
    );
  }
  final employeeAllRe = RegExp(
    r'(?:社保|社会保险|五险)[^。；\n]{0,26}(?:全部|全额)[^。；\n]{0,12}(?:由乙方|由员工|由个人)[^。；\n]{0,10}(?:承担|缴纳)|(?:乙方|员工|个人)[^。；\n]{0,18}(?:自行|全额|全部)[^。；\n]{0,10}(?:承担|缴纳)[^。；\n]{0,14}(?:社保|社会保险|五险)',
  );
  final employeeAllC = find(employeeAllRe);
  if (employeeAllC != null) {
    addPatternItem(
      ctx,
      employeeAllC,
      _ItemData(
        base: 'R15',
        ruleId: 'R15',
        verdict: Verdict.red,
        ruleName: '社保费用全部由员工承担',
        short: '社保全部自己交',
        consequence: '单位应承担的部分也让你全额承担，实际工资会被多扣；这不因“双方同意”而合法，但每月扣款会先发生。',
        ask: 'HR：单位应缴部分为什么从我的工资里扣？',
        counter: '单位承担法定部分，个人部分依法代扣代缴。',
        basis: law['L60'],
        confidence: '高',
      ),
      employeeAllRe,
    );
  }
  final housingRe = RegExp(
    r'(?:公积金|住房公积金)[^。；\n]{0,26}(?:不缴|不办理|不缴纳|个人(?:自行)?承担|由乙方承担|以补贴代替|包含在工资)',
  );
  final housingC = find(housingRe);
  if (housingC != null) {
    addPatternItem(
      ctx,
      housingC,
      _ItemData(
        base: 'R15',
        ruleId: 'R15',
        verdict: Verdict.yellow,
        ruleName: '公积金未缴或由个人承担',
        short: '公积金不缴或自己承担',
        consequence:
            '公积金不缴、让个人全额承担或用补贴代替，会影响你后续租房、购房贷款额度；公积金属于另一套投诉渠道，处理周期可能较长。',
        ask: 'HR：公积金从什么时候开始缴？缴存比例是多少？',
        counter: '按工资基数和当地比例缴存，个人部分依法代扣。',
        basis: law['HF20'],
      ),
      housingRe,
    );
  }
  if (ctx.items.any((it) => it.ruleId == 'R15')) {
    addPending(ctx, ['社保参保地、缴费基数和公积金缴存比例（工资条与参保记录要能对上）']);
  }
}

/* R16 休假与特殊保护 */
void runR16(_Ctx ctx) {
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final annualRe = RegExp(
    r'(?:年休假|年假)[^。；\n]{0,32}(?:不享受|不再享受|自动放弃|放弃|不休|作废|清零|包含在(?:春节|法定节假日)|统一安排[^。；\n]{0,20}(?:不(?:再)?支付|无补偿|不补休))',
  );
  final annualC = find(annualRe);
  if (annualC != null) {
    addPatternItem(
      ctx,
      annualC,
      _ItemData(
        base: 'R16',
        ruleId: 'R16',
        verdict: Verdict.red,
        ruleName: '年休假被作废或排除',
        short: '年假被作废',
        consequence:
            '年休假是法定权利，不能简单写成自动放弃、年底清零或包含在春节假期里；未休年假应依法安排补休或支付 300% 工资报酬。',
        ask: 'HR：年假几天？没休完怎么处理？',
        counter: '按累计工作年限写明年假天数；未休部分安排补休或依法支付。',
        basis: law['ANNUAL5'],
        confidence: '高',
      ),
      annualRe,
    );
  }
  final sickRe = RegExp(
    r'病假[^。；\n]{0,26}(?:无工资|不支付|扣发(?:全部)?工资|按事假|不计薪|最低工资以下)',
  );
  final sickC = find(sickRe);
  if (sickC != null) {
    addPatternItem(
      ctx,
      sickC,
      _ItemData(
        base: 'R16',
        ruleId: 'R16',
        verdict: Verdict.yellow,
        ruleName: '病假工资被取消',
        short: '病假不发工资',
        consequence:
            '病假期间完全不发工资或按最低工资以下处理，可能低于当地病假工资标准；具体比例看地方规定，但“病假无薪”通常站不住。',
        ask: 'HR：病假工资按什么标准发？需要哪些证明？',
        counter: '按当地病假工资规定执行，写明计算方式和所需材料。',
        basis: law['L26'],
      ),
      sickRe,
    );
  }
  final maternityRe = RegExp(
    r'(?:不得|禁止|不允许|不能|承诺|保证)[^。；\n]{0,10}(?:怀孕|生育|结婚)|(?:怀孕|生育|结婚)[^。；\n]{0,26}(?:即|就|视为|按)[^。；\n]{0,12}(?:自动离职|辞退|解除|不续签)|(?:怀孕|生育|结婚)[^。；\n]{0,26}(?:降薪|调岗|辞退|解除|不续签)',
  );
  final protectiveRe = RegExp(
    r'(?:不得|禁止)[^。；\n]{0,8}(?:因|因为)[^。；\n]{0,6}(?:怀孕|生育|结婚)|(?:不得|禁止)[^。；\n]{0,14}(?:降低|辞退|解除|降薪|调岗|不续签)',
  );
  Clause? maternityC;
  QuoteRef? maternityQ;
  for (final cl in ctx.clauses) {
    if (!maternityRe.hasMatch(cl.full)) continue;
    final q = qFilter(cl, maternityRe, protectiveRe);
    if (q != null) {
      maternityC = cl;
      maternityQ = q;
      break;
    }
  }
  if (maternityC != null && maternityQ != null) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R16',
        ruleId: 'R16',
        verdict: Verdict.red,
        ruleName: '限制婚育（无效）',
        short: '限制怀孕/生育/结婚',
        clauseIndex: maternityC.index,
        location: clauseLabel(maternityC, maternityC.index),
        quote: maternityQ.quote,
        range: maternityQ,
        consequence: '合同要求你在一定期限内不得怀孕、生育或结婚，或把怀孕视为离职、降薪、辞退的理由；这类条款违反女职工特殊保护规定，通常无效，但现实中会影响你的工作安排。',
