  }
}

/* R17 保密与成果归属 */
void runR17(_Ctx ctx) {
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final allWorksRe = RegExp(
    r'(?:所有|一切|全部|无论何时|任何)[^。；\n]{0,20}(?:成果|作品|发明|创作|知识产权)[^。；\n]{0,24}(?:归|属于|归属)[^。；\n]{0,10}(?:甲方|公司)',
  );
  final personalWorkRe = RegExp(
    r'(?:非工作时间|业余时间|个人时间|工作之外|与工作无关)[^。；\n]{0,30}(?:成果|作品|发明|创作|代码|设计)[^。；\n]{0,26}(?:归|属于)[^。；\n]{0,10}(?:甲方|公司)',
  );
  final worksC = find(allWorksRe) ?? find(personalWorkRe);
  if (worksC != null) {
    final q =
        qFilter(worksC, RegExp(r'(所有|一切|全部|成果|作品|发明|创作|知识产权|甲方|公司)')) ??
        qAny(worksC, RegExp(r'(成果|作品|知识产权)'));
    _addItem(
      ctx,
      _ItemData(
        base: 'R17',
        ruleId: 'R17',
        verdict: Verdict.gray,
        ruleName: '成果归属范围过宽',
        short: '个人成果也可能归公司',
        clauseIndex: worksC.index,
        location: clauseLabel(worksC, worksC.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: '合同把“所有成果”或业余时间创作也归公司；职务成果归单位通常合理，但你的课程作业、开源项目、个人作品如果没有排除，离职时可能被主张归属。',
        ask: 'HR：职务成果和个人作品的边界怎么划？',
        counter: '明确仅限本职工作、使用公司资源完成的成果归公司，列出个人作品和开源项目例外。',
        basis: law['L23'],
      ),
    );
  }
  final confidentialityRe = RegExp(
    r'(?:保密期限|保密义务)[^。；\n]{0,24}(?:永久|无限期|长期|离职后[^。；\n]{0,10}(?:仍然|继续))',
  );
  final confidentialityC = find(confidentialityRe);
  if (confidentialityC != null) {
    addPatternItem(
      ctx,
      confidentialityC,
      _ItemData(
        base: 'R17',
        ruleId: 'R17',
        verdict: Verdict.yellow,
        ruleName: '保密期限过长',
        short: '保密义务永久或无限期',
        consequence: '保密义务写成永久、无限期或离职后继续；商业秘密在仍属秘密时可以持续保护，但范围过宽会限制你以后使用通用技能。',
        ask: 'HR：哪些信息属于商业秘密？保密期限具体多久？',
        counter: '列明保密信息范围；对已公开信息、通用技能和个人经验作例外。',
        basis: law['L23'],
      ),
      confidentialityRe,
    );
  }
  final penaltyRe = RegExp(
    r'(?:违反[^。；\n]{0,12}保密|泄露[^。；\n]{0,12}秘密|泄密)[^。；\n]{0,28}(?:赔偿|违约金|罚款)[^。；\n]{0,18}(?:全部|一切|无限|不低于|双倍|三倍)?',
  );
  final penaltyC = find(penaltyRe);
  if (penaltyC != null) {
    addPatternItem(
      ctx,
      penaltyC,
      _ItemData(
        base: 'R17',
        ruleId: 'R17',
        verdict: Verdict.yellow,
        ruleName: '保密违约赔偿无上限',
        short: '泄密赔偿无上限',
        consequence: '保密违约写成赔偿全部损失、无上限或高倍罚款；真发生争议时，公司需要证明实际损失，但条款会先给你很大压力。',
        ask: 'HR：保密违约的赔偿上限和计算方式是什么？',
        counter: '把赔偿限定为可证明的实际损失，删除无上限和高倍惩罚。',
        basis: law['C497'],
      ),
      penaltyRe,
    );
  }
  final moonlightRe = RegExp(
    r'(?:不得|禁止|未经[^。；\n]{0,8}(?:同意|批准))[^。；\n]{0,14}(?:兼职|副业|对外投资|在其他单位任职|提供(?:服务|咨询))|(?:兼职|副业)[^。；\n]{0,18}(?:一经发现|视为严重违纪|解除|辞退)',
  );
  final moonlightC = find(moonlightRe);
  if (moonlightC != null) {
    addPatternItem(
      ctx,
      moonlightC,
      _ItemData(
        base: 'R17',
        ruleId: 'R17',
        verdict: Verdict.yellow,
        ruleName: '兼职或副业限制过宽',
        short: '禁止一切兼职副业',
        consequence:
            '合同禁止一切兼职、副业或对外服务；如果范围过宽，可能影响你正常的课程项目、开源贡献和过渡收入，严重违纪还可能被解除。',
        ask: 'HR：兼职限制是否限于与公司有竞争关系的业务？',
        counter: '把限制限定为竞争性兼职和利益冲突，不影响个人学习和开源项目。',
        basis: law['L26'],
      ),
      moonlightRe,
    );
  }
  if (ctx.items.any((it) => it.ruleId == 'R17')) {
    addPending(ctx, ['保密信息范围、成果归属边界、个人作品/开源项目是否被排除']);
  }
}

/* R18 离职手续与结算 */
void runR18(_Ctx ctx) {
  final r4Clauses = ctx.items
      .where((it) => it.ruleId == 'R4')
      .map((it) => it.clauseIndex)
      .toSet();
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final approvalRe = RegExp(
    r'(?:辞职|离职|解除(?:劳动)?合同|解除劳动关系)[^。；\n]{0,20}(?:须|需|必须|应|应当)[^。；\n]{0,14}(?:经|由)[^。；\n]{0,14}(?:甲方|公司|领导|主管|人事)[^。；\n]{0,12}(?:批准|同意|审批)|(?:未经|未获)[^。；\n]{0,14}(?:批准|同意)[^。；\n]{0,14}(?:不得|不能|不予)[^。；\n]{0,10}(?:离职|辞职|解除)',
  );
  final approvalC = find(approvalRe);
  if (approvalC != null) {
    addPatternItem(
      ctx,
      approvalC,
      _ItemData(
        base: 'R18',
        ruleId: 'R18',
        verdict: Verdict.red,
        ruleName: '离职需要公司批准',
        short: '辞职要公司批准',
        consequence:
            '劳动者提前 30 日书面通知即可解除，不需要公司批准；把批准作为离职前提，会把你困在“公司不同意就走不了”的状态。',
        ask: 'HR：我提交书面通知后，公司不批准怎么办？',
        counter: '删除审批前置；写明收到书面通知后按期办理交接和结算。',
        basis: law['L37'],
        confidence: '高',
      ),
      approvalRe,
    );
  }
  final withholdRe = RegExp(
    r'(?:未(?:提前|办理|完成|按规定)[^。；\n]{0,22}(?:通知|交接|手续|离职)[^。；\n]{0,22}(?:工资|薪资|报酬)[^。；\n]{0,14}(?:不(?:予|再)?(?:发|结算|支付)|暂缓|延后|扣发|扣除)|(?:离职|辞职)[^。；\n]{0,18}(?:未[^。；\n]{0,12}(?:交接|手续))[^。；\n]{0,18}(?:不(?:予)?(?:发|结算|支付)|扣(?:发|除))|未(?:办理|完成|按规定)[^。；\n]{0,12}(?:交接|手续)[^。；\n]{0,26}(?:不(?:予|再)?(?:发|结算|支付)|扣(?:发|除))[^。；\n]{0,8}(?:工资|薪资|报酬))',
  );
  Clause? withholdC;
  for (final cl in ctx.clauses) {
    if (!r4Clauses.contains(cl.index) && withholdRe.hasMatch(cl.full)) {
      withholdC = cl;
      break;
    }
  }
  if (withholdC != null) {
    addPatternItem(
      ctx,
      withholdC,
      _ItemData(
        base: 'R18',
        ruleId: 'R18',
        verdict: Verdict.red,
        ruleName: '未交接或未通知就扣工资',
        short: '不交接就扣工资',
        consequence:
            '公司以未提前通知、未办交接为由扣工资或拒绝结算；工资和交接是两件事，交接争议可以另算，不能直接扣住已经产生的劳动报酬。',
        ask: 'HR：交接清单是什么？工资结算和交接能不能分开处理？',
        counter: '离职时先结算工资；交接按清单办理，损失赔偿另行举证。',
        basis: law['L50'],
        confidence: '高',
      ),
      withholdRe,
    );
  }
  final certificateRe = RegExp(
    r'(?:离职证明|解除(?:劳动)?合同证明|终止(?:劳动)?合同证明|离职手续)[^。；\n]{0,26}(?:不(?:予|再)?(?:出具|办理|提供)|拒绝|扣押|与[^。；\n]{0,12}(?:工资|补偿|赔偿|交接)[^。；\n]{0,10}挂钩)|(?:档案|社会保险关系|社保关系)[^。；\n]{0,20}(?:扣押|不(?:予)?转出|不办理|拖延)',
  );
  final certificateC = find(certificateRe);
  if (certificateC != null) {
    addPatternItem(
      ctx,
      certificateC,
      _ItemData(
        base: 'R18',
        ruleId: 'R18',
        verdict: Verdict.red,
        ruleName: '离职证明或档案被扣押',
        short: '离职证明/档案被卡',
        consequence:
            '公司拒开离职证明、扣押档案或社保关系，会影响下家入职、社保接续和考公政审；这些义务不能拿来和工资、赔偿或交接绑定。',
        ask: 'HR：离职证明什么时候开？档案和社保什么时候转？',
        counter: '解除时出具证明，15 日内办理档案和社保转移；交接争议另行处理。',
        basis: law['L50'],
        confidence: '高',
      ),
      certificateRe,
    );
  }
  final autoExitRe = RegExp(
    r'(?:旷工|连续[^。；\n]{0,10}(?:日|天)|未(?:按时)?(?:到岗|上班))[^。；\n]{0,24}(?:视为|按|作)[^。；\n]{0,12}(?:自动离职|自动解除|放弃[^。；\n]{0,8}(?:工资|权利)|严重违纪)',
  );
  final autoExitC = find(autoExitRe);
  if (autoExitC != null) {
    addPatternItem(
      ctx,
      autoExitC,
      _ItemData(
        base: 'R18',
        ruleId: 'R18',
        verdict: Verdict.yellow,
        ruleName: '缺勤直接视为自动离职',
        short: '旷工视为自动离职',
        consequence:
            '把缺勤直接写成“自动离职”，公司可能据此不办手续、不结算工资；是否构成严重违纪要看制度是否合法公示、缺勤原因和程序。',
        ask: 'HR：旷工多久算严重违纪？制度有没有公示？',
        counter: '改为按规章制度处理并书面通知；离职手续和工资照常结算。',
        basis: law['L37'],
      ),
      autoExitRe,
    );
  }
  if (ctx.items.any((it) => it.ruleId == 'R18')) {
    addPending(ctx, ['离职证明出具时间、工资结算日、档案和社保转移流程']);
  }
}

