        ruleName: '劳动关系被合同否认',
        short: '合同声明不构成劳动关系',
        consequence: '合同声明不构成劳动关系，但关系性质按实际用工判断；固定岗位、考勤、绩效和持续工资都可能支持劳动关系认定。',
        ask: 'HR：日常是否按员工考勤、考核和发工资？',
        counter: '保留招聘、考勤、工资和管理记录，再判断是否需要主张劳动关系。',
        basis: law['L10'],
      ),
      noLaborRe,
    );
  }
  Clause? cCopy;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(一式两份|一式二份|各执一份|双方各执)').hasMatch(cl.full)) {
      cCopy = cl;
      break;
    }
  }
  addGreen(
    ctx,
    cCopy,
    '合同文本',
    RegExp(r'(一式两份|一式二份|各执一份|双方各执)'),
    '合同一式两份、双方各执一份，属常规安排。',
  );
  if (ctx.items.any((it) => it.ruleId == 'R19')) {
    addPending(ctx, ['是否已拿到盖章的书面合同原件，空白处是否全部填写或划掉']);
  }
}

/* R20 就业承诺与培训服务 */
void runR20(_Ctx ctx) {
  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  final guaranteeRe = RegExp(
    r'(?:(?:保证|承诺|包|确保)[^。；\n]{0,18}(?:就业|入职|录用|转正|薪资|月薪|底薪|高薪))|(?:(?:推荐|安排|提供)[^。；\n]{0,12}就业[^。；\n]{0,32}(?:不保证|不承诺|不负责|不担保))',
  );
  final guaranteeC = find(guaranteeRe);
  if (guaranteeC != null) {
    addPatternItem(
      ctx,
      guaranteeC,
      _ItemData(
        base: 'R20',
        ruleId: 'R20',
        verdict: Verdict.yellow,
        ruleName: '就业或薪资承诺',
        short: '包就业/保底薪资承诺',
        consequence:
            '“包就业”“保底薪资”如果只停留在口头或模糊宣传，很难变成可执行的合同义务；合同同时又写“不保证录用”，承诺基本落空。',
        ask: '机构：推荐就业的次数、岗位范围和保底薪资条件写在哪一条？',
        counter: '把就业服务标准、推荐次数和未达成时的退费写进合同。',
        basis: law['AD24'],
      ),
      guaranteeRe,
    );
  }
  final noJobStillPayRe = RegExp(
    r'(?:无论|不管)[^。；\n]{0,14}(?:是否|有无)[^。；\n]{0,12}(?:就业|录用|入职)[^。；\n]{0,24}(?:均|仍|都)[^。；\n]{0,12}(?:还款|偿还|支付|履行)',
  );
  final noJobStillPayC = find(noJobStillPayRe);
  if (noJobStillPayC != null) {
    addPatternItem(
      ctx,
      noJobStillPayC,
      _ItemData(
        base: 'R20',
        ruleId: 'R20',
        verdict: Verdict.yellow,
        ruleName: '未就业仍需还款',
        short: '没就业也要还贷款',
        consequence: '培训结束没找到工作，分期仍要照还；就业风险完全落在你身上，机构只要完成“推荐”就可能不再负责。',
        ask: '机构：没就业时能否暂停还款、延长分期或退费？',
        counter: '把未就业、未推荐面试等情形下的停还款或退费安排写进合同。',
        basis: law['C497'],
        confidence: '高',
      ),
      noJobStillPayRe,
    );
  }
  final refundPromiseRe = RegExp(
    r'(?:保过|包过|不过(?:全额)?退费|未就业(?:全额)?退费|就业不成功[^。；\n]{0,12}(?:退|返还))',
  );
  final refundPromiseC = find(refundPromiseRe);
  if (refundPromiseC != null) {
    addPatternItem(
      ctx,
      refundPromiseC,
      _ItemData(
        base: 'R20',
        ruleId: 'R20',
        verdict: Verdict.gray,
        ruleName: '保过或退费承诺',
        short: '保过/未就业退费',
        consequence:
            '“保过”“不过退费”“未就业退费”听起来像保障，实际常附带出勤、考试、面试次数等条件；触发条件不写清，退费会很难。',
        ask: '机构：退费触发条件、办理时限和扣除费用是什么？',
        counter: '把退费条件、比例、时限和流程写成可核对的条款。',
        basis: law['C20'],
      ),
      refundPromiseRe,
    );
  }
  if (ctx.items.any((it) => it.ruleId == 'R20')) {
    addPending(ctx, ['就业服务的岗位范围、推荐次数、未就业时的退费或停还款安排']);
  }
}

/* R21 必备条款缺失 */
bool hasRuleItem(_Ctx ctx, int? clauseIndex, String ruleId) =>
    clauseIndex != null &&
    ctx.items.any((it) => it.clauseIndex == clauseIndex && it.ruleId == ruleId);

void runR21(_Ctx ctx) {
  final checks = <Map<String, Object>>[
    {
      'label': '用人单位名称、住所和法定代表人',
      're': RegExp(
        r'(甲方[（(]用人单位[）)]|用人单位[^。；\n]{0,10}(名称|住所|法定代表人)|甲方[^。；\n]{0,10}(名称|住所|法定代表人))',
      ),
    },
    {
      'label': '劳动者姓名、住址和身份证件号码',
      're': RegExp(
        r'(乙方[（(]劳动者[）)]|劳动者[^。；\n]{0,10}(姓名|身份证)|乙方[^。；\n]{0,10}(姓名|身份证))',
      ),
    },
    {'label': '合同期限', 're': RegExp(r'(合同期限|劳动合同期限|期限自)')},
    {'label': '工作内容与工作地点', 're': RegExp(r'(工作内容|工作岗位|工作地点|岗位为)')},
    {'label': '工作时间与休息休假', 're': RegExp(r'(工作时间|休息休假|工时制度|每周工作)')},
    {'label': '劳动报酬', 're': RegExp(r'(劳动报酬|工资|薪资|月薪)')},
    {'label': '社会保险', 're': RegExp(r'(社会保险|社保|五险)')},
    {'label': '劳动保护、劳动条件和职业危害防护', 're': RegExp(r'(劳动保护|劳动条件|职业危害|安全生产)')},
  ];
  final missing = checks
      .where((x) => !(x['re'] as RegExp).hasMatch(ctx.text))
      .map((x) => x['label'] as String)
      .toList();
  if (missing.isEmpty) {
    _addItem(
      ctx,
      _ItemData(
        base: 'R21',
        ruleId: 'R21',
        verdict: Verdict.green,
        ruleName: '必备条款齐全',
        short: '必备条款齐全',
        consequence: '八项法定必备条款均有明确表述。',
        basis: law['L17'],
        confidence: '高',
      ),
    );
    return;
  }
  const core = ['合同期限', '工作内容与工作地点', '劳动报酬', '社会保险'];
  final missingCore = missing.where(core.contains).toList();
  final verdict = missingCore.length >= 3 ? Verdict.red : Verdict.gray;
  Clause? c;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(其他按公司规定|按公司制度|另行约定|具体以公司)').hasMatch(cl.full)) {
      c = cl;
      break;
    }
  }
  final q = c != null ? qAny(c, RegExp(r'(其他按公司规定|按公司制度|另行约定|具体以公司)')) : null;
  _addItem(
    ctx,
    _ItemData(
      base: 'R21',
      ruleId: 'R21',
      verdict: verdict,
      ruleName: verdict == Verdict.red ? '核心必备条款缺失' : '部分必备条款缺失',
      short: missingCore.isNotEmpty
          ? '缺 ${missingCore.length} 项核心条款'
          : '缺 ${missing.length} 项条款',
      clauseIndex: c?.index,
      location: c != null ? clauseLabel(c, c.index) : '全文',
      quote: q?.quote ?? '',
      range: q,
      consequence:
          '合同缺少以下必备条款：${missing.join('、')}。其中核心条款缺失会让劳动关系基本要素无法确定，发生争议时举证和计算都会更困难。',
      basis: law['L17'],
      ask: 'HR：这些缺失条款能否补齐后再签？如果写在附件或员工手册里，能否一并交付？',
      counter: '按《劳动合同法》第十七条补齐八项必备条款；附件须双方签字并交付。',
      confidence: verdict == Verdict.red ? '高' : '中',
    ),
  );
}

/* R22 经济补偿与违法解除 */
void runR22(_Ctx ctx) {
  final noCompRe = RegExp(
    r'(解除|终止|辞退|裁员)[^。；\n]{0,24}(无需|无须|不支付|不予|不承担|不补偿)[^。；\n]{0,12}(经济补偿|补偿)',
  );
  final waiverRe = RegExp(r'(放弃|不主张|不要求)[^。；\n]{0,12}(经济补偿|补偿金)');
  final lowBaseRe = RegExp(
    r'(经济补偿|补偿金)[^。；\n]{0,24}(按|以)[^。；\n]{0,12}(最低工资|基本工资|当地最低工资)',
  );
  final illegalLowRe = RegExp(
    r'(违法解除|违法辞退)[^。；\n]{0,20}(只|仅|按)[^。；\n]{0,10}(一个月|1个月|N|N\+1)[^。；\n]{0,10}(工资|补偿|赔偿)',
  );
  final greenRe = RegExp(
    r'(经济补偿)[^。；\n]{0,40}(每满一年|工作年限|十二个月平均工资)|(违法解除)[^。；\n]{0,20}(二倍|2N)',
  );
  Clause? c;
  for (final cl in ctx.clauses) {
    final t = cl.full;
    if ((noCompRe.hasMatch(t) || waiverRe.hasMatch(t)) &&
        !hasRuleItem(ctx, cl.index, 'R7') &&
        !RegExp(r'(依法|应当|需要)[^。；\n]{0,12}(支付|补偿)').hasMatch(t)) {
      c = cl;
      break;
    }
  }
  if (c != null) {
    addPatternItem(
      ctx,
      c,
      _ItemData(
        base: 'R22',
        ruleId: 'R22',
        verdict: Verdict.red,
        ruleName: '解除不支付经济补偿',
        short: '辞退不给补偿',
        consequence: '合同提前排除了解除或终止时的经济补偿；符合法定补偿情形时，这类约定不能免除支付义务，违法解除还应按二倍标准赔偿。',
        ask: 'HR：解除时经济补偿按什么标准算？违法解除是否按2N赔偿？',
        counter: '删除“无需补偿/放弃补偿”；按工作年限和法定标准写明经济补偿，违法解除按二倍赔偿。',
        basis: law['L47'],
        confidence: '高',
      ),
      noCompRe.hasMatch(c.body) ? noCompRe : waiverRe,
    );
    return;
  }
  Clause? low;
  for (final cl in ctx.clauses) {
    if (illegalLowRe.hasMatch(cl.full)) {
      low = cl;
      break;
    }
  }
  if (low != null) {
    addPatternItem(
      ctx,
      low,
      _ItemData(
        base: 'R22',
        ruleId: 'R22',
        verdict: Verdict.red,
        ruleName: '违法解除赔偿不足',
        short: '违法解除只给一个月',
        consequence: '违法解除或辞退应按经济补偿标准的二倍支付赔偿金；只给一个月工资或只按N支付，低于法定标准。',
        ask: 'HR：这次解除是合法解除还是违法解除？赔偿按N还是2N？',
        counter: '违法解除按2N支付；合法解除按工作年限支付经济补偿。',
        basis: law['L87'],
        confidence: '高',
      ),
      illegalLowRe,
    );
    return;
  }
  Clause? lowBase;
  for (final cl in ctx.clauses) {
    if (lowBaseRe.hasMatch(cl.full)) {
      lowBase = cl;
      break;
    }
  }
  if (lowBase != null) {
    addPatternItem(
      ctx,
      lowBase,
      _ItemData(
        base: 'R22',
        ruleId: 'R22',
        verdict: Verdict.yellow,
        ruleName: '经济补偿标准偏低',
        short: '补偿基数被压低',
        consequence: '把经济补偿基数写成最低工资或基本工资，会压低离职补偿；法定基数应是解除或终止前十二个月的平均工资。',
        ask: 'HR：经济补偿的月工资基数按什么算？是否包含绩效和补贴？',
        counter: '按解除前十二个月平均工资计算，不按最低工资或基本工资单方压低。',
        basis: law['L47'],
        confidence: '中',
      ),
      lowBaseRe,
    );
    return;
  }
  Clause? green;
  for (final cl in ctx.clauses) {
    if (greenRe.hasMatch(cl.full)) {
      green = cl;
      break;
    }
  }
  if (green != null) addGreen(ctx, green, '经济补偿', greenRe, '经济补偿按工作年限和法定标准约定。');
}

/* R23 无固定期限与连续签约 */
void runR23(_Ctx ctx) {
  final tenRe = RegExp(r'(连续工作满十年|连续工作10年|工作满十年)');
  final twiceRe = RegExp(r'(连续订立二次|连续订立两次|第三次签订|第三次续订)');
  final fixRe = RegExp(r'(?:^|[^无])(固定期限|一年期|一年一签|不续签)');
  final noWrittenRe = RegExp(
    r'(满一年|超过一年)[^。；\n]{0,12}(未|不)[^。；\n]{0,10}(签订|订立)[^。；\n]{0,8}书面',
  );
  final yearlyRe = RegExp(r'(一年一签|每年签订一次|一年一续)');
  final greenRe = RegExp(
    r'(无固定期限)[^。；\n]{0,20}(应当|依法|订立)|(连续工作满十年)[^。；\n]{0,20}(无固定期限)',
  );
  final legalRecital = RegExp(
    r'(依法|应当|应)[^。；\n]{0,10}(订立|签订)[^。；\n]{0,10}无固定期限',
  );
  Clause? red;
  for (final cl in ctx.clauses) {
    final t = cl.full;
    if (((tenRe.hasMatch(t) || twiceRe.hasMatch(t)) && fixRe.hasMatch(t) ||
            noWrittenRe.hasMatch(t)) &&
        !legalRecital.hasMatch(t)) {
      red = cl;
      break;
    }
  }
  if (red != null) {
    addPatternItem(
      ctx,
      red,
      _ItemData(
        base: 'R23',
        ruleId: 'R23',
        verdict: Verdict.red,
        ruleName: '应订无固定期限仍签固定期限',
        short: '规避无固定期限',
        consequence: '已符合连续工作满十年或连续订立二次固定期限合同的情形，仍约定固定期限或不续签，可能违反第十四条；满一年未签书面合同还会被视为无固定期限。',
        ask: 'HR：这次是第几次签订固定期限合同？我是否符合订立无固定期限合同的条件？',
        counter: '符合条件时改为无固定期限合同；不续签请书面说明法定终止依据。',
        basis: law['L14'],
        confidence: '中',
      ),
      tenRe.hasMatch(red.body)
          ? tenRe
          : (twiceRe.hasMatch(red.body) ? twiceRe : noWrittenRe),
    );
    return;
  }
  Clause? yearly;
  for (final cl in ctx.clauses) {
    if (yearlyRe.hasMatch(cl.full)) {
      yearly = cl;
      break;
    }
  }
  if (yearly != null) {
    addPatternItem(
      ctx,
      yearly,
      _ItemData(
        base: 'R23',
        ruleId: 'R23',
        verdict: Verdict.yellow,
        ruleName: '反复签订短期合同',
        short: '一年一签',
        consequence: '长期一年一签可能规避无固定期限合同；连续订立二次后，劳动者提出或同意续订的，单位应订立无固定期限合同。',
        ask: 'HR：公司为什么一直一年一签？第三次续签是否按无固定期限处理？',
        counter: '写明续订规则；符合第十四条情形时订立无固定期限合同。',
        basis: law['L14'],
        confidence: '中',
      ),
      yearlyRe,
    );
    return;
  }
  Clause? green;
  for (final cl in ctx.clauses) {
    if (greenRe.hasMatch(cl.full)) {
      green = cl;
      break;
    }
  }
  if (green != null) {
    addGreen(ctx, green, '无固定期限', greenRe, '符合条件时订立无固定期限合同，属常规安排。');
  }
}

/* R24 特殊工时审批 */
void runR24(_Ctx ctx) {
  final specialRe = RegExp(r'(综合计算工时|综合工时|不定时工作制|不定时工时|轮班制|倒班制)');
  final approvalRe = RegExp(
    r'(经|已获)[^。；\n]{0,12}(劳动行政部门|人社局|人力资源和社会保障局|审批)[^。；\n]{0,10}(批准|审批)',
  );
  final noPayRe = RegExp(r'(加班费|加班工资)[^。；\n]{0,20}(不支付|不再|不予|按季度|包干|包含)');
  final greenRe = RegExp(r'(150%|200%|300%|百分之一百五十|百分之二百|百分之三百)');
  Clause? c;
  for (final cl in ctx.clauses) {
    if (specialRe.hasMatch(cl.full)) {
      c = cl;
      break;
    }
  }
  if (c == null) return;
  final t = c.full;
  if (!approvalRe.hasMatch(t)) {
    final noPay = noPayRe.hasMatch(t);
    addPatternItem(
      ctx,
      c,
      _ItemData(
        base: 'R24',
        ruleId: 'R24',
        verdict: noPay ? Verdict.red : Verdict.yellow,
        ruleName: noPay ? '特殊工时未审批且不付加班费' : '特殊工时缺少审批信息',
        short: noPay ? '综合工时没有加班费' : '特殊工时未写审批',
        consequence: noPay
            ? '合同实行综合工时或不定时工时，却没有劳动行政部门审批，还约定超时不付加班费；未经审批应按标准工时支付加班费。'
            : '合同提到综合工时、不定时工时或轮班制，但没有审批文号、计算周期和超时加班费规则，实际执行时容易少算加班费。',
        ask: 'HR：公司实行哪种工时制度？有没有劳动行政部门的审批文号？超时部分怎么算加班费？',
        counter: '写明审批文号与计算周期；未审批的按标准工时支付150%/200%/300%加班费。',
        basis: law['L39'],
        confidence: noPay ? '高' : '中',
      ),
      specialRe,
    );
    return;
  }
  if (greenRe.hasMatch(t)) {
    addGreen(ctx, c, '特殊工时', specialRe, '特殊工时已写审批与加班费标准，属常规安排。');
  } else {
    addPatternItem(
      ctx,
      c,
      _ItemData(
        base: 'R24',
        ruleId: 'R24',
        verdict: Verdict.yellow,
        ruleName: '特殊工时加班费规则不明',
        short: '特殊工时加班费未写明',
        consequence: '写了特殊工时审批，但没有写清超出标准工时的加班费计算方式；实际结算时仍可能按低标准执行。',
        ask: 'HR：综合计算周期内超过法定标准工时的部分按什么比例支付？',
        counter: '补写150%/200%/300%的支付规则和计算周期。',
        basis: law['L39'],
        confidence: '中',
      ),
      specialRe,
    );
  }
}

/* R25 女职工三期保护 */
void runR25(_Ctx ctx) {
  final redRe = RegExp(
    r'(怀孕|孕期|生育|产期|哺乳|哺乳期)[^。；\n]{0,30}(降薪|调岗|辞退|解除|不续签|扣工资|限制)',
  );
