}

/* R30 争议管辖与送达 */
void runR30(_Ctx ctx) {
  final redRe = RegExp(
    r'(争议|纠纷)[^。；\n]{0,20}(只能|仅能|应当)[^。；\n]{0,12}(甲方所在地|公司所在地|用人单位所在地|外地)[^。；\n]{0,10}(仲裁|法院|管辖)|(放弃|不提起)[^。；\n]{0,12}(仲裁|诉讼)',
  );
  final courtRe = RegExp(r'(争议|纠纷)[^。；\n]{0,20}(法院|诉讼)[^。；\n]{0,10}(管辖|解决)');
  final deliveryRe = RegExp(r'(短信|微信|电子)[^。；\n]{0,10}送达');
  final greenRe = RegExp(r'(劳动合同履行地|用人单位所在地)[^。；\n]{0,16}(仲裁|管辖)');
  Clause? red;
  for (final cl in ctx.clauses) {
    if (redRe.hasMatch(cl.full)) {
      red = cl;
      break;
    }
  }
  if (red != null) {
    addPatternItem(
      ctx,
      red,
      _ItemData(
        base: 'R30',
        ruleId: 'R30',
        verdict: Verdict.red,
        ruleName: '排除法定管辖或放弃救济',
        short: '只能去公司所在地仲裁',
        consequence: '劳动争议应由劳动合同履行地或用人单位所在地仲裁委管辖；约定只能去公司所在地或外地，或提前放弃仲裁/诉讼权利，通常会限制你的救济选择。',
        ask: 'HR：为什么只能去公司所在地仲裁？能否按劳动合同履行地或用人单位所在地选择？',
        counter: '删除排除性管辖和放弃救济条款，按劳动争议调解仲裁法第二十一条执行。',
        basis: law['ARB21'],
        confidence: '高',
      ),
      redRe,
    );
    return;
  }
  Clause? court;
  for (final cl in ctx.clauses) {
    if (courtRe.hasMatch(cl.full)) {
      court = cl;
      break;
    }
  }
  if (court != null) {
    addPatternItem(
      ctx,
      court,
      _ItemData(
        base: 'R30',
        ruleId: 'R30',
        verdict: Verdict.yellow,
        ruleName: '劳动争议约定法院管辖',
        short: '劳动争议直接约定法院',
        consequence: '劳动争议一般应先申请仲裁，直接约定由法院管辖不符合程序；这类条款可能无法排除仲裁前置。',
        ask: 'HR：劳动争议是否先走劳动仲裁？为什么直接约定法院管辖？',
        counter: '改为向劳动合同履行地或用人单位所在地劳动争议仲裁委员会申请仲裁。',
        basis: law['ARB21'],
        confidence: '中',
      ),
      courtRe,
    );
    return;
  }
  Clause? delivery;
  for (final cl in ctx.clauses) {
    if (deliveryRe.hasMatch(cl.full) && !RegExp(r'同意').hasMatch(cl.full)) {
      delivery = cl;
      break;
    }
  }
  if (delivery != null) {
    addPatternItem(
      ctx,
      delivery,
      _ItemData(
        base: 'R30',
        ruleId: 'R30',
        verdict: Verdict.yellow,
        ruleName: '电子送达未取得同意',
        short: '短信/微信送达未同意',
        consequence: '约定短信、微信或电子方式送达，但没有写明经你同意；电子送达应以你同意并能确认收悉为前提。',
        ask: 'HR：电子送达是否经过我同意？如何确认我收悉？',
        counter: '写明送达地址、电子送达同意方式和变更通知义务。',
        basis: law['CIVPRO90'],
        confidence: '中',
      ),
      deliveryRe,
    );
    return;
  }
  Clause? green;
  for (final cl in ctx.clauses) {
    if (greenRe.hasMatch(cl.full)) {
      green = cl;
      break;
    }
  }
  if (green != null) {
    addGreen(ctx, green, '争议管辖', greenRe, '争议管辖按劳动合同履行地或用人单位所在地约定。');
  }
}

/* greens（劳动合同） */
void runLaborGreens(_Ctx ctx) {
  Clause? cHours;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(标准工时制|每日工作\s*8\s*小时|每周工作\s*40\s*小时)').hasMatch(cl.full)) {
      cHours = cl;
      break;
    }
  }
  addGreen(
    ctx,
    cHours,
    '工作时间',
    RegExp(r'(标准工时制|每日工作|每周工作)'),
    '标准工时、每日 8 小时与每周 40 小时已写明。',
  );
  final socialIssue = ctx.items.any(
    (it) => RegExp(r'社保|社会保险|公积金').hasMatch(it.ruleName),
  );
  if (!socialIssue) {
    Clause? cSocial;
    for (final cl in ctx.clauses) {
      if (RegExp(r'(缴纳(社会保险|社保)|社会保险)').hasMatch(cl.full) &&
          !RegExp(r'(放弃|不缴|自理|自行承担)').hasMatch(cl.full)) {
        cSocial = cl;
        break;
      }
    }
    addGreen(ctx, cSocial, '社会保险', RegExp(r'(社会保险|社保)'), '约定依法缴纳社会保险，属常规条款。');
  }
  Clause? cDuty;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(岗位|工作地点)').hasMatch(cl.full) &&
        !RegExp(r'(调整|变更|违约金|试用期|保证金|押金)').hasMatch(cl.full)) {
      cDuty = cl;
      break;
    }
  }
  addGreen(ctx, cDuty, '岗位与工作地点', RegExp(r'(岗位|工作地点)'), '岗位与工作地点明确。');
}

/* ---------------- R31–R36 消费培训与分期 ---------------- */

class _ClauseMeta {
  final Clause cl;
  final int? num;
  final List<String> qualifiers;
  final bool attachment;
  final String heading;
  final String body;
  final String text;
  final String label;
  _ClauseMeta({
    required this.cl,
    required this.num,
    required this.qualifiers,
    required this.attachment,
    required this.heading,
    required this.body,
    required this.text,
    required this.label,
  });
}

class _RefResult {
  final bool ok;
  final _ClauseMeta? meta;
  final Clause? clause;
  final String? reason;
  final String? message;
  final List<_ClauseMeta> candidates;
  _RefResult({
    required this.ok,
    this.meta,
    this.clause,
    this.reason,
    this.message,
    this.candidates = const [],
  });
}

class _PriorityEdge {
  final int source;
  final _ClauseMeta? subjectMeta;
  final bool negative;
  final bool limited;
  final String scope;
  final String quote;
  final String raw;
  final int? from;
  final int? to;
  final bool generic;
  final bool resolved;
  final String? reason;
  final _ClauseMeta? targetMeta;
  _PriorityEdge({
    required this.source,
    required this.subjectMeta,
    required this.negative,
    required this.limited,
    required this.scope,
    required this.quote,
    required this.raw,
    this.from,
    this.to,
    this.generic = false,
    this.resolved = false,
    this.reason,
    this.targetMeta,
  });
}

class _PriorityState {
  final String state;
  final String? reason;
  final List<String> issues;
  _PriorityState(this.state, {this.reason, this.issues = const []});
}

class _ObjectRelation {
  final String status;
  final String? reason;
  _ObjectRelation(this.status, {this.reason});
}

class _RefundPromise {
  final Set<String> objects;
  final bool full;
  final int? days;
  final bool anytime;
  final bool unconditional;
  final bool conditionsClear;
  final bool moreFavorable;
  final bool otherCourse;
  final bool restricted;
  final String? restrictedReason;
  final double? amount;
  final String text;
  _RefundPromise({
    required this.objects,
    required this.full,
    required this.days,
    required this.anytime,
    required this.unconditional,
    required this.conditionsClear,
    required this.moreFavorable,
    required this.otherCourse,
    required this.restricted,
    required this.restrictedReason,
    required this.amount,
    required this.text,
  });
}

class _CoverResult {
  final Clause clause;
  final _RefundPromise promise;
  final _ClauseMeta meta;
  final _PriorityState priority;
  final _ObjectRelation obj;
  _CoverResult({
    required this.clause,
    required this.promise,
    required this.meta,
    required this.priority,
    required this.obj,
  });
}

T? _firstWhereOrNull<T>(Iterable<T> list, bool Function(T) test) {
  for (final item in list) {
    if (test(item)) return item;
  }
  return null;
}

int? _articleNumOf(String text) {
  final m = RegExp(r'第\s*([一二两三四五六七八九十百零〇\d]+)\s*条').firstMatch(text);
  if (m == null) return null;
  final raw = m.group(1)!;
  final n = RegExp(r'^\d+$').hasMatch(raw) ? double.tryParse(raw) : cnNum(raw);
  if (n == null || !n.isFinite) return null;
  return n.round();
}

String _normalizeRef(String? q) =>
    (q ?? '').replaceAll(RegExp("[“”\"'《》\\s]"), '');

/* R31/R32 + R33–R36 消费培训与分期（对应网页端 runLoanConsumer） */
void runLoanConsumer(_Ctx ctx, {bool consumerOnly = false}) {
  final text = ctx.text;
  final consumerText = RegExp(r'(学员|消费者|课程|课时|直播课|录播|开课|上课|培训)').hasMatch(text);
  final licensedClaim = RegExp(r'(持牌消费金融(?:机构|公司)?|消费金融(?:股份)?有限公司|消费金融公司)')
      .hasMatch(text);
  final dateKey = contractDateKey(text);
  final currentRules = dateKey != null && dateKey >= 20260801;
  final licensedNote = licensedClaim
      ? '合同文本自称贷款人为持牌消费金融公司；该资质真实性仍需另行向监管或工商信息核对，以下按合同陈述适用持牌机构规则。'
      : '合同未明确贷款人是否为持牌机构；以下按持牌机构规则作条件性提示，并需按实际放款主体核对。';
  final dateNote = dateKey == null
      ? '合同未写签署日期，以下提示应按实际签约和放款时点作条件性核对。'
      : dateKey < 20260801
      ? '合同签署日期早于2026年8月1日，不能直接套用届时才施行的规定；如实际签约或放款发生在施行后，应按下列要求核对。'
      : '';

  Clause? find(RegExp re) {
    for (final cl in ctx.clauses) {
      if (re.hasMatch(cl.full)) return cl;
    }
    return null;
  }

  if (!consumerOnly) {
    final c10 = find(RegExp(r'(综合融资成本|明示表)'));
    if (c10 != null && RegExp(r'(签署|签约|支付页|月供)').hasMatch(c10.full)) {
      final t10 = c10.full;
      final tableQ =
          qFilter(c10, RegExp(r'支付页[^。；\n]{0,40}(?:月供|每月)')) ??
          qAny(c10, RegExp(r'(月供|签署后|明示表)'));
      final disclosureVerdict = licensedClaim && currentRules
          ? Verdict.yellow
          : Verdict.gray;
      if (RegExp(
        r'签署(?:贷款)?(?:合同)?前[^。；\n]{0,24}(?:只能|仅能)[^。；\n]{0,16}(?:看到|查看)[^。；\n]{0,12}(?:月供|每月)|签署后[^。；\n]{0,16}(?:才能|才可)[^。；\n]{0,16}(?:查看|看到)[^。；\n]{0,12}(?:表|成本)',
      ).hasMatch(t10)) {
        _addItem(
          ctx,
          _ItemData(
            base: 'R31',
            ruleId: 'R31',
            verdict: disclosureVerdict,
            ruleName: '签约后才能查看综合融资成本表',
            short: '签前只看月供，签后才能看成本表',
            clauseIndex: c10.index,
            location: clauseLabel(c10, c10.index),
            quote: tableQ?.quote ?? '',
            range: tableQ,
            consequence:
                '$licensedNote$dateNote支付页只显示每月还款额和“利息0元”，签署贷款前看不到综合融资成本明示表，签署后才能查看；月供和零利息不能替代签前披露的全部成本。',
            ask: '机构：为什么签前不能查看综合融资成本明示表？月供之外还有哪些费用？',
            counter: '在签署前提供完整明示表，列明每项费用、收取主体、频次和正常履约年化成本。',
            basis: law['IR26_2'],
            confidence: '高',
          ),
        );
      }
      final subjectQ =
          qFilter(
            c10,
            RegExp(
              r'(?:明示表|该表|成本表)[^。；\n]{0,32}(?:不列|未列|没有)[^。；\n]{0,18}(?:收取主体|收费主体)',
            ),
          ) ??
          qFilter(c10, RegExp(r'(?:不列|未列|没有)[^。；\n]{0,24}(?:收取主体|收费主体)'));
      if (subjectQ != null) {
        _addItem(
          ctx,
          _ItemData(
            base: 'R31',
            ruleId: 'R31',
            verdict: disclosureVerdict,
            ruleName: '明示表未列费用收取主体',
            short: '成本表不写钱付给谁',
            clauseIndex: c10.index,
            location: clauseLabel(c10, c10.index),
            quote: subjectQ.quote,
            range: subjectQ,
            consequence:
                '$licensedNote$dateNote综合融资成本明示表不列各项费用的收取主体，借款人无法判断费用由贷款人、平台还是培训机构收取，也无法核对谁有权收费。',
            ask: '机构：每项费用由谁收取？贷款人和平台各自收多少？',
            counter: '在明示表逐项列明收取主体、金额、频次和收取时间。',
            basis: law['IR26_2'],
            confidence: '高',
          ),
        );
      }
      final annualQ = qFilter(
        c10,
        RegExp(r'不显示[^。；\n]{0,24}(?:正常履约的)?年化(?:综合融资成本|利率)'),
      );
      if (annualQ != null) {
        _addItem(
          ctx,
          _ItemData(
            base: 'R31',
            ruleId: 'R31',
            verdict: disclosureVerdict,
            ruleName: '明示表未列正常履约年化成本',
            short: '没有年化综合融资成本',
            clauseIndex: c10.index,
            location: clauseLabel(c10, c10.index),
            quote: annualQ.quote,
            range: annualQ,
            consequence:
                '$licensedNote$dateNote明示表不显示正常履约的年化综合融资成本，只给月供和零利息，无法比较真实借款成本；应以实际占用本金为基础折算全部费用，并按人民银行公告〔2021〕第3号核对年化披露。',
            ask: '机构：按实际占用本金折算的年化综合融资成本是多少？',
            counter: '在签前明示表列明年化综合融资成本及计算口径。',
            basis: law['IR26_2'],
            confidence: '高',
          ),
        );
      }
    }

    final c11 = find(RegExp(r'已(?:显示|明示|展示|列明)的费用之外[^。；\n]{0,30}(?:新增|加收|收取)'));
    if (c11 != null) {
      final q =
          qFilter(c11, RegExp(r'(?:已(?:显示|明示)的费用之外|新增任何|扣款后通知)')) ??
          qAny(c11, RegExp(r'(新增|扣款|通知)'));
      _addItem(
        ctx,
        _ItemData(
          base: 'R32',
          ruleId: 'R32',
          verdict: licensedClaim && currentRules ? Verdict.red : Verdict.gray,
          ruleName: '明示费用外可新增收费',
          short: '表外费用先扣后通知',
          clauseIndex: c11.index,
          location: clauseLabel(c11, c11.index),
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '$licensedNote$dateNote合同允许在已展示费用之外按内部清单新增借款履约服务费，金额和次数由平台单方决定，并可在扣款后才通知；这使借款人无法在签约前知道全部成本，也不能有效控制扣款。',
          ask: '机构：已明示费用之外还可能收哪些钱？金额、次数和通知方式是什么？',
          counter: '删除开口收费条款；任何新增费用须事先书面告知并取得同意，不得先扣后通知。',
          basis: law['IR26_3'],
          confidence: '高',
        ),
      );
    }
    final c18 = find(RegExp(r'(仅内部可见|内部[^。；\n]{0,10}后台)'));
    if (c18 != null && RegExp(r'(通知|视为)').hasMatch(c18.full)) {
      final q =
          qFilter(c18, RegExp(r'(?:内部[^。；\n]{0,12}后台|仅内部可见|视为通知)')) ??
          qAny(c18, RegExp(r'(后台|通知)'));
      _addItem(
        ctx,
        _ItemData(
          base: 'R32',
          ruleId: 'R32',
          verdict: licensedClaim && currentRules
              ? Verdict.yellow
              : Verdict.gray,
          ruleName: '仅内部后台改价不构成通知',
          short: '贴内部后台就算通知',
          clauseIndex: c18.index,
          location: clauseLabel(c18, c18.index),
          quote: q?.quote ?? '',
          range: q,
          consequence:
              '$licensedNote$dateNote把成本条目或收费标准贴入仅内部可见的业务后台就视为通知借款人，借款人付款时仍看不到调整后的息费项目；内部系统记录不能代替能够及时到达借款人的有效通知。',
          ask: '机构：改价后如何通知我？我付款时在哪里能看到调整后的息费？',
          counter: '改为书面或可确认收悉的方式通知，并保证借款人在付款前能看到调整项目。',
          basis: law['IR26_4'],
          confidence: '高',
        ),
      );
    }
  }

  if (!consumerText) return;

  final c2 = find(
    RegExp(
      r'(?:生成|开通)[^。；\n]{0,18}(?:学习)?账号[^。；\n]{0,18}(?:即视为|视为)[^。；\n]{0,20}(?:交付|提供)',
    ),
  );
  if (c2 != null) {
    final t2 = c2.full;
    final refusal = RegExp(r'(不退|不予退还|不返还|概不退还|拒绝退款|不得退款)').hasMatch(t2);
    final favorable = RegExp(
      r'(?:七日内|7日内)[^。；\n]{0,16}(?:可|可以|有权|同意|应当|全额|无条件)[^。；\n]{0,12}(?:退款|退还|返还)|(?:全额|无条件)[^。；\n]{0,10}(?:退款|退还|返还)',
    ).hasMatch(t2);
    final accountDeemed = RegExp(
      r'(?:生成|开通)[^。；\n]{0,22}(?:学习)?账号[^。；\n]{0,22}(?:即视为|视为)[^。；\n]{0,24}(?:交付|提供)',
    ).hasMatch(t2);
    final dayMatch = RegExp(
      r'(?:付款后|付款之日起)(?:第)?\s*([一二两三四五六七八九十\d]+)\s*(?:日|天)',
    ).firstMatch(t2);
    final dayRaw = dayMatch?.group(1);
    final dayNum = dayRaw == null
        ? null
        : (RegExp(r'^\d+$').hasMatch(dayRaw)
              ? double.tryParse(dayRaw)
              : cnNum(dayRaw));
    final day = dayNum != null && dayNum.isFinite ? dayNum.round() : null;
    final beyond = RegExp(r'(?:超过|超出|满)\s*七\s*日|七\s*日\s*(?:后|以后)').hasMatch(t2);
    var priorSame = false;
    var noPrior = false;
    for (final s in sentenceList(ctx.text)) {
      final q = s.quote;
      if (RegExp(
            r'(?:获得|接受|购买|取得)(?:过)?[^。；\n]{0,12}(?:相同|同类|同样)[^。；\n]{0,8}(?:商品|服务|课程)',
          ).hasMatch(q) ||
          RegExp(r'(?:获得|接受|购买|取得)过[^。；\n]{0,16}(?:商品|服务|课程)').hasMatch(q) ||
          RegExp(r'(?:获得|接受|购买|取得)[^。；\n]{0,12}(?:商品|服务|课程)过').hasMatch(q)) {
        if (RegExp(
          r'(?:未|没有|从未|未曾|并未)[^。；\n]{0,26}(?:从|向|在)?[^。；\n]{0,22}(?:获得|接受|购买|取得)(?:过)?',
        ).hasMatch(q)) {
          noPrior = true;
        } else {
          priorSame = true;
        }
      }
    }
    final firstPurchase =
        noPrior || RegExp(r'首次购买|第一次购买|首次接受').hasMatch(ctx.text);
    final sevenQ =
        qFilter(
          c2,
          RegExp(r'(?:付款后|付款之日起)[^。；\n]{0,34}(?:日|天)|(?:不退|不予退还|不返还)'),
        ) ??
        qAny(c2, RegExp(r'(付款后|退还|退款)'));
    final accountQ =
        qFilter(
          c2,
          RegExp(
            r'(?:生成|开通)[^。；\n]{0,24}(?:学习)?账号[^。；\n]{0,24}(?:即视为|视为)[^。；\n]{0,24}(?:交付|提供)',
          ),
        ) ??
        qAny(c2, RegExp(r'(账号|交付)'));

    Set<String> refundObjectSet(String t) {
      final set = <String>{};
      if (RegExp(r'(?:预付款|课程款|课程价款|学费|培训费(?:用)?|课程费用)').hasMatch(t)) {
        set.add('prepay');
      }
      if (RegExp(r'(?:教材费|资料费|材料费|书本费)').hasMatch(t)) set.add('materials');
      if (RegExp(r'(?:平台费|平台服务费|技术服务费|风险管理费|服务费|利息|罚息|违约金|手续费|管理费)')
          .hasMatch(t)) {
        set.add('fee');
      }
      if (RegExp(r'(?:借款本金|贷款本金)').hasMatch(t)) set.add('loan');
      return set;
    }

    _ClauseMeta clauseMeta(Clause cl) {
      final heading = cl.heading;
      final body = cl.body;
      final num = _articleNumOf(heading);
      final qualifiers = RegExp(r'[（(]([^）)]{1,30})[）)]')
          .allMatches(heading)
          .map((m) => m.group(1)!)
          .toList();
      final attachment =
          RegExp(r'附件').hasMatch(heading) ||
          qualifiers.any((q) => RegExp(r'附件').hasMatch(q)) ||
          RegExp(r'^\s*附件').hasMatch(body);
      return _ClauseMeta(
        cl: cl,
        num: num,
        qualifiers: qualifiers,
        attachment: attachment,
        heading: heading,
        body: body,
        text: cl.full,
        label: clauseLabel(cl, cl.index),
      );
    }

    final metas = ctx.clauses.map(clauseMeta).toList();
    final currentMeta =
        _firstWhereOrNull(metas, (m) => m.cl.index == c2.index) ??
        clauseMeta(c2);
    final refusalMetas = metas
        .where(
          (m) =>
              RegExp(r'(?:不退|不予退还|不返还|概不退还|拒绝退款|不得退款)').hasMatch(m.text) &&
              RegExp(r'(?:预付款|课程款|课程价款|学费|培训费|退款)').hasMatch(m.text),
        )
        .toList();

    _RefResult resolveArticleNumber(
      int? num, [
      String? refText,
      String? qualifier,
    ]) {
      if (num == null) {
        return _RefResult(ok: false, reason: 'bad-number', message: '条号无法识别');
      }
      var candidates = metas.where((m) => m.num == num).toList();
      if (candidates.isEmpty) {
        return _RefResult(ok: false, reason: 'missing', message: '未找到第$num条');
      }
      final t = refText ?? '';
      final attHint =
          RegExp(r'附件').hasMatch(t) || RegExp(r'附件').hasMatch(qualifier ?? '');
      final origHint = RegExp(r'原').hasMatch(t);
      if (attHint) {
        candidates = candidates.where((m) => m.attachment).toList();
        if (candidates.isEmpty) {
          final attLabel =
              RegExp(r'附件[^，。；\n]{0,8}').firstMatch(t)?.group(0) ?? '附件';
          return _RefResult(
            ok: false,
            reason: 'missing-attachment',
            message: '$attLabel中没有可定位的第$num条',
          );
        }
        final attNo = RegExp(r'附件([一二两三四五六七八九十百零〇\d]+)(?=(?:第|中|内))')
            .firstMatch(t);
        if (attNo != null) {
          final label = '附件${attNo.group(1)}';
          final exact = candidates
              .where(
                (m) =>
                    _normalizeRef('${m.heading}${m.qualifiers.join()}')
                        .contains(_normalizeRef(label)),
              )
              .toList();
          if (exact.isNotEmpty) {
            candidates = exact;
          } else {
            return _RefResult(
              ok: false,
              reason: 'missing-attachment',
              message: '附件中没有可定位的第$num条（$label）',
            );
          }
        }
      } else if (origHint) {
        final bodyOnly = candidates.where((m) => !m.attachment).toList();
        if (bodyOnly.isNotEmpty) candidates = bodyOnly;
      }
      if (qualifier != null && qualifier.isNotEmpty) {
        final q = _normalizeRef(qualifier);
        if (q.isNotEmpty) {
          final exact = candidates
              .where(
                (m) =>
                    _normalizeRef('${m.heading}${m.body}').contains(q) ||
                    _normalizeRef(m.qualifiers.join()).contains(q),
              )
              .toList();
          if (exact.isNotEmpty) {
            candidates = exact;
          } else {
            return _RefResult(
              ok: false,
              reason: 'qualifier-miss',
              message: '第$num条没有与“$qualifier”相符的条款',
            );
          }
        }
      }
      if (candidates.length == 1) {
        return _RefResult(
          ok: true,
          meta: candidates[0],
          clause: candidates[0].cl,
        );
      }
      return _RefResult(
        ok: false,
        reason: 'ambiguous',
        candidates: candidates,
        message: '第$num条存在${candidates.length}个候选，正文与附件或重复条号无法唯一确定',
      );
    }

    RegExpMatch? lastArticleRefBefore(String t) {
      final re = RegExp(
        r'(?:原(?:合同)?|附件[一二两三四五六七八九十百零〇\d]*|前述|上述|该|本)?\s*第\s*([一二两三四五六七八九十百零〇\d]+)\s*条(?:\s*[（(]([^）)]{1,30})[）)])?',
      );
      final found = re.allMatches(t).toList();
      return found.isEmpty ? null : found.last;
    }

    int? numberFrom(String raw) {
      final n = RegExp(r'^\d+$').hasMatch(raw)
          ? double.tryParse(raw)
          : cnNum(raw);
      if (n == null || !n.isFinite) return null;
      return n.round();
    }

    _RefResult? resolveRefText(
      String? refText,
      String prefixText,
      _ClauseMeta currentMetaArg,
    ) {
      final t = (refText ?? '').trim();
      if (t.isEmpty) return null;
      if (RegExp(r'(?:前述|上述|该|此)[^，。；\n]{0,10}(?:拒退|拒绝退款|退款)条款').hasMatch(t)) {
        if (refusalMetas.length == 1) {
          return _RefResult(
            ok: true,
            meta: refusalMetas[0],
            clause: refusalMetas[0].cl,
          );
        }
        return _RefResult(
          ok: false,
          reason: 'ambiguous-refusal',
          candidates: refusalMetas,
          message: '“前述拒退条款”存在多个候选，无法唯一定位',
        );
      }
      final explicit = RegExp(
        r'(?:原(?:合同)?|附件[一二两三四五六七八九十百零〇\d]*|前述|上述|该|本)?\s*第\s*([一二两三四五六七八九十百零〇\d]+)\s*条(?:\s*[（(]([^）)]{1,30})[）)])?',
      ).firstMatch(t);
      if (explicit != null) {
        final n = numberFrom(explicit.group(1)!);
        if (n == null) {
          return _RefResult(ok: false, reason: 'bad-number', message: '条号无法识别');
        }
        return resolveArticleNumber(n, explicit.group(0), explicit.group(2));
      }
      if (RegExp(r'[该此]条|前述[^，。；\n]{0,6}条款').hasMatch(t)) {
        final last = lastArticleRefBefore(prefixText);
        if (last != null) {
          return resolveArticleNumber(
            numberFrom(last.group(1)!),
            last.group(0),
            last.group(2),
          );
        }
        return _RefResult(
          ok: false,
          reason: 'pronoun',
          message: '“$t”前没有可唯一定位的条号',
        );
      }
      if (RegExp(r'(?:^|[，,；;。\n\s])本(?:条|条款|约定|承诺)').hasMatch(t) ||
          RegExp(r'^本(?:条|条款|约定|承诺)').hasMatch(t)) {
        return _RefResult(
          ok: true,
          meta: currentMetaArg,
          clause: currentMetaArg.cl,
        );
      }
      if (RegExp(r'本合同|本协议').hasMatch(t)) {
        return _RefResult(
          ok: false,
          reason: 'document',
          message: '“本合同”不能作为具体条款定位',
        );
      }
      return null;
    }

    List<_RefResult> resolveTargets(
      String? targetText,
      String prefixText,
      _ClauseMeta currentMetaArg,
    ) {
      final t = (targetText ?? '').trim();
      final out = <_RefResult>[];
      if (t.isEmpty) return out;
      if (RegExp(r'(?:其他条款|其余条款|本合同其他|所有其他|其他约定)').hasMatch(t)) {
        return [_RefResult(ok: true)];
      }
      if (RegExp(r'(?:前述|上述|该|此)[^，。；\n]{0,10}(?:拒退|拒绝退款|退款)条款').hasMatch(t)) {
        final r = resolveRefText(t, prefixText, currentMetaArg);
        if (r != null) out.add(r);
      }
      final re = RegExp(
        r'(?:原(?:合同)?|附件[一二两三四五六七八九十百零〇\d]*|前述|上述|该|本)?\s*第\s*([一二两三四五六七八九十百零〇\d]+)\s*条(?:\s*[（(]([^）)]{1,30})[）)])?',
      );
      for (final m in re.allMatches(t)) {
        final n = numberFrom(m.group(1)!);
        if (n != null) out.add(resolveArticleNumber(n, m.group(0), m.group(2)));
      }
      if (RegExp(r'本条').hasMatch(t) &&
          !RegExp(r'第\s*[一二两三四五六七八九十百零〇\d]+\s*条').hasMatch(t)) {
        out.add(
          _RefResult(ok: true, meta: currentMetaArg, clause: currentMetaArg.cl),
        );
      }
      if (RegExp(r'[该此]条').hasMatch(t) &&
          !RegExp(r'第\s*[一二两三四五六七八九十百零〇\d]+\s*条').hasMatch(t)) {
        final r = resolveRefText('该条', prefixText, currentMetaArg);
        if (r != null) out.add(r);
      }
      if (out.isEmpty && RegExp(r'前述[^，。；\n]{0,6}条款').hasMatch(t)) {
        final r = resolveRefText(t, prefixText, currentMetaArg);
        if (r != null) out.add(r);
      }
      final seen = <int>{};
      return out.where((x) {
        if (x.ok && x.meta != null) {
          if (seen.contains(x.meta!.cl.index)) return false;
          seen.add(x.meta!.cl.index);
        }
        return true;
      }).toList();
    }

    String priorityScope(String s) {
      const feeWords =
          '教材费|资料费|材料费|书本费|平台费|平台服务费|技术服务费|风险管理费|服务费|管理费|手续费|利息|违约金|罚息';
      final feeScope =
          RegExp(
            '(?:仅|只|限于|限|范围(?:仅|只|为|限于)?|就|对|针对)[^。；\\n]{0,14}(?:$feeWords)',
          ).hasMatch(s) ||
          RegExp('(?:$feeWords)[^。；\\n]{0,10}(?:范围内|范围|优先|适用)').hasMatch(s);
      if (feeScope) return 'fee';
      if (RegExp(r'(?:仅|只|限于|限|对|针对)[^。；\n]{0,10}(?:另一门|其他课程|另一课程|不同课程|第二门)')
          .hasMatch(s)) {
        return 'other';
      }
      return 'general';
    }

    List<_PriorityEdge> parsePriorityEdges(_ClauseMeta meta) {
      final s = meta.body;
      final edges = <_PriorityEdge>[];
      final re = RegExp(r'优先(?:适用)?');
      for (final m in re.allMatches(s)) {
        var segStart = 0;
        for (final ch in ['。', '；', '\n']) {
          final p = m.start > 0 ? s.lastIndexOf(ch, m.start - 1) : -1;
          if (p >= 0 && p + 1 > segStart) segStart = p + 1;
        }
        var segEnd = s.length;
        for (final ch in ['。', '；', '\n']) {
          final p = s.indexOf(ch, m.start + m.group(0)!.length);
          if (p >= 0 && p < segEnd) segEnd = p;
        }
        final before = s.substring(segStart, m.start);
        final afterRaw = s.substring(m.start + m.group(0)!.length, segEnd);
        final nearStart = segStart > m.start - 24 ? segStart : m.start - 24;
        final nearEnd = segEnd < m.start + m.group(0)!.length + 24
            ? segEnd
            : m.start + m.group(0)!.length + 24;
        final near = s.substring(nearStart, nearEnd);
        final subjectParts = before.split(RegExp(r'[，,]'));
        final subjectPart = subjectParts.last.trim();
        var subject = _RefResult(ok: true, meta: meta, clause: meta.cl);
        _RefResult? subjectIssue;
        if (subjectPart.isNotEmpty &&
            RegExp(r'(?:第\s*[一二两三四五六七八九十百零〇\d]+\s*条|本条|本条款|该条|前述|上述|本协议|本合同)')
                .hasMatch(subjectPart)) {
          if (RegExp(r'本条\s*$').hasMatch(subjectPart)) {
            subject = _RefResult(ok: true, meta: meta, clause: meta.cl);
          } else {
            final sr = resolveRefText(
              subjectPart,
              s.substring(0, m.start),
              meta,
            );
            if (sr != null && sr.ok) {
              subject = sr;
            } else if (sr != null) {
              subject = _RefResult(ok: false);
              subjectIssue = sr;
            }
          }
        }
        final negative =
            RegExp(r'(?:不|未|并非|不得|不能|没有)\s*(?:再|予以|得|能)?\s*$')
                .hasMatch(before) ||
            RegExp(r'^(?:性|关系)?[^。；\n]{0,4}(?:低于|不及)').hasMatch(afterRaw);
        final limited = RegExp(
          r'(?:仅|只)[^。；\n]{0,8}(?:优先|适用|限|针对|限于)|(?:优先|适用)[^。；\n]{0,8}(?:仅|只)',
        ).hasMatch(near);
        final scope = priorityScope(near);
        final targetRaw = afterRaw.split(RegExp(r'[，,]')).first.trim();
        final allOther = RegExp(r'(?:其他条款|其余条款|本合同其他|所有其他|其他约定)')
            .hasMatch(targetRaw);
        final targets = allOther
            ? <_RefResult>[]
            : resolveTargets(
                targetRaw,
                s.substring(0, m.start + m.group(0)!.length),
                meta,
              );
        final emptyTarget =
            targetRaw.isEmpty || RegExp(r'^(?:适用|适用于)$').hasMatch(targetRaw);
        final at = (m.start - segStart) < 0 ? 0 : (m.start - segStart);
        final quote = clipQuote(near, at, at + m.group(0)!.length);
        final from = subject.ok ? subject.meta!.cl.index : null;

        if (allOther || (emptyTarget && !limited)) {
          edges.add(
            _PriorityEdge(
              source: meta.cl.index,
              subjectMeta: meta,
              negative: negative,
              limited: limited,
              scope: scope,
              quote: quote,
              raw: near,
              from: from,
              generic: true,
              resolved: subject.ok,
              reason: subjectIssue?.message,
            ),
          );
          continue;
        }
        if (targets.isEmpty) {
          final laterTarget = RegExp(
            r'优先[^。；\n]{0,14}第\s*[一二两三四五六七八九十百零〇\d]+\s*条',
          ).hasMatch(afterRaw);
          if (limited && emptyTarget && laterTarget) continue;
          edges.add(
            _PriorityEdge(
              source: meta.cl.index,
              subjectMeta: meta,
              negative: negative,
              limited: limited,
              scope: scope,
              quote: quote,
              raw: near,
              from: from,
              resolved: false,
              reason:
                  subjectIssue?.message ??
                  (limited ? '优先范围没有指向可定位的条款' : '优先对象不明确'),
            ),
          );
          continue;
        }
        for (final t in targets) {
          if (t.ok && t.meta == null) {
            edges.add(
              _PriorityEdge(
                source: meta.cl.index,
                subjectMeta: meta,
                negative: negative,
                limited: limited,
                scope: scope,
                quote: quote,
                raw: near,
                from: from,
                generic: true,
                resolved: subject.ok,
                reason: subjectIssue?.message,
              ),
            );
            continue;
          }
          edges.add(
            _PriorityEdge(
              source: meta.cl.index,
              subjectMeta: meta,
              negative: negative,
              limited: limited,
              scope: scope,
              quote: quote,
              raw: near,
              from: from,
              to: t.ok ? t.meta!.cl.index : null,
              resolved: subject.ok && t.ok,
              reason: !subject.ok
                  ? (subjectIssue?.message ?? '优先主体不明确')
                  : (!t.ok ? t.message : null),
              targetMeta: t.meta,
            ),
          );
        }
      }
      return edges;
    }

    final priorityEdges = <_PriorityEdge>[];
    for (final m in metas) {
      priorityEdges.addAll(parsePriorityEdges(m));
    }

    _PriorityState priorityState(_ClauseMeta pMeta, _ClauseMeta cMeta) {
      final p = pMeta.cl.index;
      final c = cMeta.cl.index;
      final pEdges = priorityEdges.where((e) => e.source == p).toList();
      final issues = <String>[];
      final unresolved = _firstWhereOrNull(pEdges, (e) => !e.resolved);
      if (unresolved != null) issues.add(unresolved.reason ?? '优先对象不明确');
      final adj = <int, List<int>>{};
      final allAdj = <int, List<int>>{};
      void addAdj(Map<int, List<int>> map, int? from, int? to) {
        if (from == null || to == null) return;
        map.putIfAbsent(from, () => <int>[]);
        if (!map[from]!.contains(to)) map[from]!.add(to);
      }

      for (final e in priorityEdges) {
        if (e.negative || !e.resolved || e.from == null) continue;
        final compatible = e.scope != 'fee' && e.scope != 'other';
        if (e.generic) {
          addAdj(allAdj, e.from, c);
          if (compatible) addAdj(adj, e.from, c);
        } else if (e.to != null) {
          addAdj(allAdj, e.from, e.to);
          if (compatible) addAdj(adj, e.from, e.to);
        }
      }
      final reachable = <int>{p};
      final allQueue = <int>[p];
      while (allQueue.isNotEmpty) {
        final n = allQueue.removeAt(0);
        for (final nx in allAdj[n] ?? const <int>[]) {
          if (!reachable.contains(nx)) {
            reachable.add(nx);
            allQueue.add(nx);
          }
        }
      }
      final badScope = _firstWhereOrNull(
        priorityEdges,
        (e) =>
            !e.negative &&
            e.resolved &&
            e.from != null &&
            (e.scope == 'fee' || e.scope == 'other') &&
            reachable.contains(e.from) &&
            (e.generic || e.to == c),
      );
      if (badScope != null) {
        issues.add(
          badScope.scope == 'fee'
              ? '优先范围仅覆盖费用项目，不覆盖本笔预付款'
              : '优先范围仅覆盖另一门课程，不覆盖本笔预付款',
        );
      }
      final unresolvedReach = _firstWhereOrNull(
        priorityEdges,
        (e) =>
            !e.resolved &&
            !e.negative &&
            e.from != null &&
            reachable.contains(e.from),
      );
      if (unresolvedReach != null && !identical(unresolvedReach, unresolved)) {
        issues.add(unresolvedReach.reason ?? '优先链条中存在无法定位的条款');
      }
      final negativeBlock = _firstWhereOrNull(
        priorityEdges,
        (e) =>
            e.negative &&
            e.resolved &&
            e.from != null &&
            reachable.contains(e.from) &&
            (e.generic || e.to == c),
      );
      final reverseBlock = priorityEdges.any(
        (e) =>
            !e.negative &&
            e.resolved &&
            e.from == c &&
            (e.to == p || e.generic) &&
            e.scope != 'fee' &&
            e.scope != 'other',
      );
      var pathFound = false;
      final queue = <int>[p];
      final seen = <int>{p};
      while (queue.isNotEmpty) {
        final n = queue.removeAt(0);
        if (n == c) {
          pathFound = true;
          break;
        }
        for (final nx in adj[n] ?? const <int>[]) {
          if (!seen.contains(nx)) {
            seen.add(nx);
            queue.add(nx);
          }
        }
      }
      var cycle = false;
      final color = <int, int>{};
      void dfs(int n) {
        color[n] = 1;
        for (final nx in adj[n] ?? const <int>[]) {
          if (color[nx] == 1) {
            cycle = true;
            return;
          }
          if (!color.containsKey(nx)) dfs(nx);
        }
        color[n] = 2;
      }

      dfs(p);
      if (cycle) issues.add('优先关系存在循环引用或互相优先');
      if (reverseBlock &&
          (pathFound ||
              pEdges.any(
                (e) => e.resolved && e.generic && !e.negative && e.from == p,
              ))) {
        issues.add('拒退条款反向优先于承诺条款，不能确认覆盖');
      }
      if (negativeBlock != null &&
          (pathFound ||
              pEdges.any(
                (e) => e.resolved && e.generic && !e.negative && e.from == p,
              ))) {
        issues.add('优先关系同时存在相反约定');
      }
      if (issues.isNotEmpty) {
        return _PriorityState('conflict', reason: issues.first, issues: issues);
      }
      if (pathFound ||
          pEdges.any(
            (e) => e.resolved && e.generic && !e.negative && e.from == p,
          )) {
        return _PriorityState('cover');
      }
      if (pEdges.isEmpty) {
        if (reverseBlock) {
          return _PriorityState('excluded', reason: '拒退条款反向优先于承诺条款');
        }
        return _PriorityState('unclear', reason: '承诺条款未写明优先关系');
      }
      return _PriorityState('excluded', reason: '优先对象不含拒退条款或明确排除拒退条款');
    }

    Set<String> namedCourseTokens(String? input) {
      final s = input ?? '';
      final out = <String>{};
      final re = RegExp(r'([\u4e00-\u9fa5A-Za-z0-9]{2,20}(?:课程|课|培训|班|套餐))');
      for (final m in re.allMatches(s)) {
        final tok = m.group(1)!;
        final afterEnd = m.end + 4 > s.length ? s.length : m.end + 4;
        final after = s.substring(m.end, afterEnd);
        if (RegExp(r'(?:中心|公司|机构|平台|学校|学院)').hasMatch(after)) continue;
        if (RegExp(r'(?:其他|另一|不同|新增|本课程|该课程|全部课程|所有课程|此类|相同|同类)')
            .hasMatch(tok)) {
          continue;
        }
        if (RegExp(
          r'^(?:本|该|此|其他|另一|不同|上述|前述|全部|所有|每|多|一门|两门|三门|这门|哪门|免费|线上|线下|直播|录播|培训|课程|购买|推销|或|如|并|且|及|与|将|可|应|能|由|向|对|为|在|被|把|从|到|的)',
        ).hasMatch(tok)) {
          continue;
        }
        if (RegExp(r'(?:直播课|录播课|培训课程|全部|所有)$').hasMatch(tok)) continue;
        if (RegExp(
          r'(?:甲方|乙方|丙方|丁方|生成|预收|交付|视为|提供|购买|停课|上课|开课|退还|返还|付款|支付|签署|约定|合同|金额|剩余|已上|完整|推广|模板|账号|才能|以后|放弃|转往|上调|违约|经营者|消费者|借款|贷款|收到|录入|不用|另付)',
        ).hasMatch(tok)) {
          continue;
        }
        if (tok.length < 3) continue;
        out.add(tok);
      }
      for (final m in RegExp(
        r'(?:课程|套餐|订单|班次)\s*([A-Za-z0-9一二三四五六七八九十]{1,8})',
      ).allMatches(s)) {
        final tok = m.group(0)!.replaceAll(RegExp(r'\s+'), '');
        if (!RegExp(r'^(?:课程|套餐|订单|班次)$').hasMatch(tok)) out.add(tok);
      }
      for (final m in RegExp(
        r'(?:课程名称|课程|培训项目|套餐名称|套餐|订单)[：:为]?\s*[“"《]([^”"》]{2,20})[”"》]',
      ).allMatches(s)) {
        out.add(m.group(1)!);
      }
      return out;
    }

    final globalCourseNames = namedCourseTokens(ctx.text);

    Set<String> packageIds(String? input) {
      final out = <String>{};
      for (final m in RegExp(
        r'(?:套餐|订单(?:号|编号)?|班次)[：:\s]*(?:为|是)?\s*([A-Za-z0-9][A-Za-z0-9_-]{1,20})',
      ).allMatches(input ?? '')) {
        out.add(m.group(1)!);
      }
      return out;
    }

    final globalPackageIds = packageIds(ctx.text);

    final prepayAmounts = () {
      final out = <double>[];
      final re = RegExp(
        r'(?:预收[^。；\n]{0,14}|课程价款|课程款|借款本金|贷款本金)[^。；\n]{0,14}?((?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)\s*(万元|元)',
      );
      for (final m in re.allMatches(ctx.text)) {
        var n = double.parse(m.group(1)!.replaceAll(',', ''));
        if (m.group(2) == '万元') n *= 10000;
        if (n.isFinite && n > 0 && !out.any((v) => (v - n).abs() < 0.01)) {
          out.add(n);
        }
      }
      return out;
    }();

    _RefundPromise? refundPromise(String input) {
      if (!RegExp(r'(?:退还|返还|退款)').hasMatch(input)) return null;
      const targetWords =
          '(预付款(?:本金)?|课程款|课程价款|学费|培训费(?:用)?|课程费用|教材费|资料费|材料费|书本费|平台费|平台服务费|技术服务费|风险管理费|手续费|服务费|管理费|(?:借款|贷款)本金)';
      final objects = <String>{};
      String? canon(String s) {
        if (RegExp(r'预付款|课程款|课程价款|学费|培训费|课程费用').hasMatch(s)) return 'prepay';
        if (RegExp(r'教材费|资料费|材料费|书本费').hasMatch(s)) return 'materials';
        if (RegExp(r'平台费|平台服务费|技术服务费|风险管理费|服务费|利息|罚息|违约金|手续费|管理费')
            .hasMatch(s)) {
          return 'fee';
        }
        if (RegExp(r'借款本金|贷款本金').hasMatch(s)) return 'loan';
        return null;
      }

      void addTarget(String s) {
        final o = canon(s);
        if (o != null) objects.add(o);
      }

      for (final m in RegExp(
        '(?:退还|返还|退款|退)[^。；\\n]{0,8}$targetWords',
      ).allMatches(input)) {
        addTarget(m.group(1)!);
      }
      for (final m in RegExp(
        '$targetWords[^。；\\n]{0,12}(?:全额|全部|可|应当|应|予以)?[^。；\\n]{0,8}(?:退还|返还|退款)',
      ).allMatches(input)) {
        addTarget(m.group(1)!);
      }
      if (objects.isEmpty) return null;
      final partial = RegExp(
        r'(?:部分退款|部分退还|部分返还|剩余|余额|按[^。；\n]{0,8}(?:课时|比例|进度)[^。；\n]{0,8}折算|扣除[^。；\n]{0,10}(?:课时|费用|已上|已消费))',
      ).hasMatch(input);
      final full = RegExp(r'(?:全额|全部|100\s*%|预付款本金|全部预付款|全部课程款)')
          .hasMatch(input);
      RegExpMatch? windowMatch = RegExp(
        r'(?:自|从)[^。；\n]{0,14}(?:付款|支付|缴费)[^。；\n]{0,6}?(?:之日起|起|后)[^。；\n]{0,8}?([一二两三四五六七八九十百\d]+)\s*(?:日|天)\s*(?:内|以内)',
      ).firstMatch(input);
      windowMatch ??= RegExp(
        r'(?:付款|支付|缴费)[^。；\n]{0,6}?(?:之日起|起|后)[^。；\n]{0,8}?([一二两三四五六七八九十百\d]+)\s*(?:日|天)\s*(?:内|以内)',
      ).firstMatch(input);
      windowMatch ??= RegExp(
        r'(?:付款后|支付后|缴费后)[^。；\n]{0,8}?([一二两三四五六七八九十百\d]+)\s*(?:日|天)',
      ).firstMatch(input);
      final daysRaw = windowMatch?.group(1);
      final daysNum = daysRaw == null
          ? null
          : (RegExp(r'^\d+$').hasMatch(daysRaw)
                ? double.tryParse(daysRaw)
                : cnNum(daysRaw));
      final days = daysNum != null && daysNum.isFinite ? daysNum.round() : null;
      final anytime = RegExp(
        r'(?:随时|任何时候|任意时间)[^。；\n]{0,10}(?:可|可以|有权)[^。；\n]{0,8}(?:退款|退还|返还)',
      ).hasMatch(input);
      final unconditional = RegExp(r'(?:无理由|无条件)').hasMatch(input);
      final conditionsClear =
          (days != null && days > 0) || anytime || unconditional;
      final moreFavorable =
          full && (days != null ? days > 7 : (anytime || unconditional));
      final otherCourse = RegExp(
        r'(?:其他|另一|另行|新增|不同|别的|第[二三四五六七八九十\d]+门)[^。；\n]{0,10}(?:课程|课|培训|服务|费用)',
      ).hasMatch(input);
      final noStateLimit = RegExp(
        r'(?:无论|不论)[^。；\n]{0,8}是否(?:已)?(?:开课|上课|消费|使用)|(?:无论|不论)[^。；\n]{0,8}(?:均已|均不|一律)',
      ).hasMatch(input);
      final stateLimit =
          !noStateLimit &&
          RegExp(r'(?:未|尚未|没有)[^。；\n]{0,8}(?:开课|上课|使用|消费|登录)').hasMatch(input);
      final attendedLimit = RegExp(
        r'(?:已|已经)[^。；\n]{0,8}(?:开课|上课|消费|使用)[^。；\n]{0,12}(?:不退|不予|扣除|折算)',
      ).hasMatch(input);
      final restricted = partial || stateLimit || attendedLimit;
      final restrictedReason = partial
          ? '退款只覆盖剩余/部分款项，需核对实际退款权益'
          : stateLimit
          ? '退款附加了未开课或未使用等上课状态限制，需人工比较适用条件'
          : attendedLimit
          ? '已上课或已消费后的退款受限，需人工比较适用条件'
          : null;
      final amountMatches = RegExp(
        r'(?:退还|返还|退款)[^。；\n]{0,24}?((?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)\s*(万元|元)',
      ).allMatches(input).toList();
      double? amount;
      if (amountMatches.isNotEmpty) {
        final m = amountMatches.last;
        amount = double.parse(m.group(1)!.replaceAll(',', ''));
        if (m.group(2) == '万元') amount *= 10000;
        if (!amount.isFinite) amount = null;
      }
      return _RefundPromise(
        objects: objects,
        full: full,
        days: days,
        anytime: anytime,
        unconditional: unconditional,
        conditionsClear: conditionsClear,
        moreFavorable: moreFavorable,
        otherCourse: otherCourse,
        restricted: restricted,
        restrictedReason: restrictedReason,
        amount: amount,
        text: input,
      );
    }

    _ObjectRelation objectRelation(_RefundPromise p, String pText) {
      if (p.otherCourse) {
        return _ObjectRelation('different', reason: '承诺指向另一门课程或其他服务');
      }
      final pNames = namedCourseTokens(pText);
      final cNames = namedCourseTokens(currentMeta.text);
      final sameMark = RegExp(
        r'(?:同一笔|该笔|本笔|这笔|同一订单|该订单|本订单|原订单|同一套餐|本套餐|该套餐|本课程|该课程|本培训|该培训|上述课程|原课程)',
      ).hasMatch(pText);
      final pPkg = packageIds(pText);
      final cPkg = packageIds(currentMeta.text);
      if (pPkg.isNotEmpty && cPkg.isNotEmpty && !pPkg.any(cPkg.contains)) {
        return _ObjectRelation('different', reason: '承诺与拒退条款指向不同套餐或订单');
      }
      if (pNames.isNotEmpty && cNames.isNotEmpty) {
        final same = pNames.any(cNames.contains);
        return same
            ? _ObjectRelation('same')
            : _ObjectRelation('different', reason: '承诺与拒退条款指向不同课程');
      }
      if (pNames.isNotEmpty && cNames.isEmpty) {
        if (sameMark) return _ObjectRelation('same');
        if (globalCourseNames.length == 1 &&
            globalCourseNames.contains(pNames.first)) {
          return _ObjectRelation('same');
        }
        if (globalCourseNames.length > 1 ||
            pPkg.isNotEmpty ||
            globalPackageIds.length > 1) {
          return _ObjectRelation(
            'ambiguous',
            reason: '合同存在多门课程或套餐，承诺只写课程/学费，无法确认与拒退条款是同一笔付款',
          );
        }
        return _ObjectRelation('same');
      }
      if (pNames.isEmpty && cNames.isNotEmpty) {
        if (sameMark) return _ObjectRelation('same');
        if (globalCourseNames.length > 1 || globalPackageIds.length > 1) {
          return _ObjectRelation(
            'ambiguous',
            reason: '合同存在多门课程或套餐，承诺未写明课程名称，无法确认是同一笔付款',
          );
        }
        return _ObjectRelation('same');
      }
      if (pPkg.isNotEmpty &&
          cPkg.isEmpty &&
          globalPackageIds.length > 1 &&
          !sameMark) {
        return _ObjectRelation(
          'ambiguous',
          reason: '承诺写有套餐/订单，但拒退条款未写明，无法确认是同一笔付款',
        );
      }
      if (cPkg.isNotEmpty &&
          pPkg.isEmpty &&
          globalPackageIds.length > 1 &&
          !sameMark) {
        return _ObjectRelation(
          'ambiguous',
          reason: '拒退条款写有套餐/订单，但承诺未写明，无法确认是同一笔付款',
        );
      }
      if (sameMark) return _ObjectRelation('same');
      if (globalCourseNames.length > 1 || globalPackageIds.length > 1) {
        return _ObjectRelation(
          'ambiguous',
          reason: '合同存在多门课程或套餐，仅凭“学费”或金额不能确认为同一笔付款',
        );
      }
      return _ObjectRelation('same');
    }

    String? amountIssue(_RefundPromise p) {
      if (p.amount == null) return null;
      if (prepayAmounts.isEmpty) return '承诺写明的退款金额无法与合同预付款对应';
      if (!prepayAmounts.any((v) => (v - p.amount!).abs() < 0.01)) {
        return '承诺写明的退款金额 ${p.amount} 元与合同预付款 ${prepayAmounts.map(fmtYuan).join(' / ')} 元不一致';
      }
      return null;
    }

    _CoverResult? crossCover;
    _CoverResult? crossConflict;
    if (refusal && !favorable) {
      final c2Objects = refundObjectSet(t2);
      for (final meta in metas) {
        if (meta.cl.index == c2.index) continue;
        final p = refundPromise(meta.body);
        if (p == null || (!p.full && !p.restricted)) continue;
        if (!p.moreFavorable && p.conditionsClear && !p.restricted) continue;
        if (p.otherCourse) continue;
        if (!p.objects.any(c2Objects.contains)) continue;
        if (c2Objects.contains('prepay') && !p.objects.contains('prepay')) {
          continue;
        }
        final obj = objectRelation(p, meta.body);
        if (obj.status == 'different') continue;
        final pr = priorityState(meta, currentMeta);
        if (pr.state == 'excluded') continue;
        final reasons = <String>[];
        if (obj.status == 'ambiguous') {
          reasons.add(obj.reason ?? '承诺与拒退条款可能不是同一笔付款');
        }
        if (!p.conditionsClear) reasons.add('退款期限或条件不明确');
        if (p.restricted) reasons.add(p.restrictedReason ?? '退款范围或条件受限');
        final ai = amountIssue(p);
        if (ai != null) reasons.add(ai);
        if (day != null && p.days != null && p.days! < day) {
          reasons.add('承诺期限短于拒退条款所涉第$day日');
        }
        if (meta.num == null || currentMeta.num == null) {
          reasons.add('条款未编号或缺附件条号，无法确认条号与证据位置');
        }
        if (pr.state != 'cover') reasons.add(pr.reason ?? '优先关系不明确');
        if (reasons.isNotEmpty) {
          crossConflict ??= _CoverResult(
            clause: meta.cl,
            promise: p,
            meta: meta,
            priority: pr,
            obj: obj,
          );
        } else {
          crossCover = _CoverResult(
            clause: meta.cl,
            promise: p,
            meta: meta,
            priority: pr,
            obj: obj,
          );
          break;
        }
      }
    }

    if (refusal && !favorable) {
      final history = priorSame
