      RegExp(r'(短信验证码|验证码)').hasMatch(c15.full) &&
      RegExp(r'(长期保留|永久保存|推广)').hasMatch(c15.full)) {
    final q = qFilter(c15, RegExp(r'人脸')) ?? qAny(c15, RegExp(r'(人脸|验证码)'));
    final qPromo = qFilter(c15, RegExp(r'(?:长期保留|永久保存|推广)')) ?? q;
    _addItem(
      ctx,
      _ItemData(
        base: 'R36',
        ruleId: 'R36',
        verdict: Verdict.red,
        ruleName: '已有同等验证仍强制人脸',
        short: '有短信验证还强制人脸',
        clauseIndex: c15.index,
        location: clauseLabel(c15, c15.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: '已经部署的一次性短信验证码能达到同等身份核验效果，却仍要求必须录入人脸模板才能上课，且不能单独选择；实现相同目的存在其他方式时，人脸识别不得作为唯一验证方式，应提供合理替代。',
        ask: '机构：短信验证码已经够用，为什么还强制人脸？不同意人脸能否上课？',
        counter: '提供短信验证等替代方式；人脸识别只在必要且取得单独同意时使用。',
        basis: law['FACE10'],
        confidence: '高',
      ),
    );
    _addItem(
      ctx,
      _ItemData(
        base: 'R36',
        ruleId: 'R36',
        verdict: Verdict.yellow,
        ruleName: '人脸模板长期留存推广且无单独同意',
        short: '人脸长期留存做推广',
        clauseIndex: c15.index,
        location: clauseLabel(c15, c15.index),
        quote: qPromo?.quote ?? '',
        range: qPromo,
        consequence: '签培训合同即概括授权采集人脸，模板由平台长期保留并用于以后推广课程；人脸属于敏感个人信息，处理目的、保存期限和必要性应单独说明并取得单独同意，概括授权不能替代。',
        ask: '机构：人脸模板保存多久？用于推广时如何单独取得我的同意？',
        counter: '明确保存期限和营销使用范围；敏感信息取得单独同意，并提供删除和替代验证渠道。',
        basis: law['PI28'],
        confidence: '高',
      ),
    );
  }

  final c16 = find(RegExp(r'合作商'));
  if (c16 != null &&
      RegExp(r'(姓名|手机号|学习记录)').hasMatch(c16.full) &&
      RegExp(r'(交给|提供给|共享)').hasMatch(c16.full)) {
    final q =
        qFilter(c16, RegExp(r'(?:合作商|学习记录|姓名|手机号)')) ??
        qAny(c16, RegExp(r'(合作商|营销)'));
    _addItem(
      ctx,
      _ItemData(
        base: 'R36',
        ruleId: 'R36',
        verdict: Verdict.red,
        ruleName: '营销共享未披露接收方且无单独同意',
        short: '学习记录交给不明合作商',
        clauseIndex: c16.index,
        location: clauseLabel(c16, c16.index),
        quote: q?.quote ?? '',
        range: q,
        consequence: '为推销其他课程，把姓名、手机号、学习记录交给自行决定营销用途的合作商，却不告知合作商名称和联系方式，并以签署主合同概括视为同意；向第三方提供个人信息应告知接收方、目的、方式和信息种类并取得单独同意。',
        ask: '机构：合作商是谁？联系方式是什么？共享哪些学习记录、用于什么营销？',
        counter: '逐项告知接收方和处理目的并取得单独同意；提供拒绝和撤回渠道。',
        basis: law['PI23'],
        confidence: '高',
      ),
    );
  }
}

// 纯预付课程合同：不依赖贷款词也能触发 R33 的通用退款审查。
void runPrepayFallback(_Ctx ctx) {
  if (ctx.items.any((it) => it.ruleId == 'R33')) return;
  Clause? pay;
  for (final cl in ctx.clauses) {
    final t = cl.full;
    if (RegExp(r'(预付|预收|预交|课程费|学费|培训费|课程款|一次性(?:支付|收取|付款))').hasMatch(t) &&
        parseAmount(cl.body) != null) {
      pay = cl;
      break;
    }
  }
  Clause? refuse;
  for (final cl in ctx.clauses) {
    if (RegExp(r'(不退|不予退还|概不退还|不予退款|不退费|不得退款|费用不予退还)').hasMatch(cl.full)) {
      refuse = cl;
      break;
    }
  }
  if (pay == null && refuse == null) return;
  if (refuse != null) {
    final amount = pay != null
        ? (maxAmountAfter(
                pay.full,
                RegExp(r'(预付|预收|预交|课程费|学费|培训费|课程款|一次性(?:支付|收取|付款))'),
              ) ??
              parseAmount(pay.body))
        : null;
    final q =
        qAny(refuse, RegExp(r'(不退|不予退还|概不退还|不予退款|不退费|不得退款|费用不予退还)')) ??
        (pay != null ? qAny(pay, RegExp(r'(预付|预收|预交|学费|课程费|培训费)')) : null);
    _addItem(
      ctx,
      _ItemData(
        base: 'R33',
        ruleId: 'R33',
        verdict: Verdict.red,
        ruleName: '预付课程拒绝退款',
        short: amount != null ? '${fmtWan(amount)}预付款不退' : '预付款不退',
        clauseIndex: refuse.index,
        location: clauseLabel(refuse, refuse.index),
        quote: q?.quote ?? '',
        range: q,
        consequence:
            '合同约定${amount != null ? '预付的 ${fmtYuan(amount)} 元' : '已付费用'}不退或不予退还。预付式消费中，以格式条款排除或者限制消费者解除合同、请求返还预付款等权利的，可能被认定无效；付款后七日内还可能适用预付款本金返还规则（存在法定例外）。',
        ask: '机构：不开课、停课、迁址或者我七日内提出解除时，预付款怎么退？为什么约定一律不退？',
        counter: '删除一律不退；写明解除条件、退款比例和办理时限，未消费部分按约定或法定规则返还。',
        basis: law['PREPAY9'],
        confidence: '高',
        loss: amount ?? 0,
      ),
    );
    return;
  }
  final qPay = qAny(pay!, RegExp(r'(预付|预收|预交|课程费|学费|培训费|课程款)'));
  _addItem(
    ctx,
    _ItemData(
      base: 'R33',
      ruleId: 'R33',
      verdict: Verdict.gray,
      ruleName: '预付课程未约定退款',
      short: '预付款怎么退没写',
      clauseIndex: pay.index,
      location: clauseLabel(pay, pay.index),
      quote: qPay?.quote ?? '',
      range: qPay,
      consequence: '合同写了预付课程费用，但没有约定解除、退费和未消费课时的处理方式；真停课或想退时，退款比例和办理时限都无法核对。',
      ask: '机构：停课、迁址、转班或者我提出解除时，未消费课时怎么退？多久到账？',
      counter: '写明解除条件、未消费课时的折算方式和退款时限，并给出书面申请渠道。',
      basis: law['PREPAY9'],
      confidence: '中',
    ),
  );
}

void buildPending(_Ctx ctx) {
  final items = ctx.items;
  bool has(RegExp re) =>
      items.any((it) => re.hasMatch(it.ruleName) || re.hasMatch(it.short));
  final list = <String>[];
  void push(List<String> arr) {
    for (final p in arr) {
      if (p.isNotEmpty && !list.contains(p) && list.length < 5) list.add(p);
    }
  }

  final packs = ctx.packs.isNotEmpty ? ctx.packs : [ctx.docType];
  for (final pack in packs) {
    if (pack == 'labor') {
      if (has(RegExp(r'试用期'))) push(['用人单位所在地的最低工资标准（核对试用期工资是否另触最低线）']);
      if (has(RegExp(r'竞业'))) push(['你的岗位是否属于竞业限制适用人员，补偿标准怎么定']);
      if (has(RegExp(r'押金|保证金'))) push(['保证金是否已经实际交纳、有没有收据']);
      if (has(RegExp(r'加班|工时|调休'))) push(['公司实行标准工时、综合工时还是不定时工时？是否经过审批？']);
      if (has(RegExp(r'工资|绩效|扣款'))) push(['工资构成、绩效规则、发薪日与实际扣款记录']);
      if (has(RegExp(r'社保|公积金'))) push(['社保参保地、缴费基数和公积金缴存比例']);
      if (has(RegExp(r'年假|休假|病假|产假|婚育'))) push(['年假天数、病假工资和婚育假期与当地规定的对应关系']);
      if (has(RegExp(r'保密|成果归属|兼职'))) push(['保密信息范围、成果归属边界与个人作品例外']);
      if (has(RegExp(r'离职|交接|证明'))) push(['离职证明出具时间、工资结算日、档案和社保转移流程']);
      if (has(RegExp(r'合同文本|先签|空白|试用期后'))) push(['是否已拿到盖章的书面合同原件，空白处是否填写完整']);
      push(['公司是否另有培训协议、保密协议或补充协议（当前文本里没有）', '合同主体名称是否与营业执照、录取通知一致']);
    } else if (pack == 'intern') {
      push([
        '学校是否统一购买实习责任保险或意外伤害保险',
        '这是学校组织的顶岗实习，还是你自行联系的实习',
        '实习补贴是否达到学校实习备案或协议模板的要求',
        '这份实习是否实际按员工管理（考勤、绩效、固定工资）——可能被认定为劳动关系',
      ]);
    } else if (pack == 'loan') {
      push([
        '放款机构的全称与放贷资质（持牌机构与民间借贷适用的利率规则不同）',
        '合同成立当月的一年期 LPR',
        '含平台服务费的年化综合成本（按 IRR 核算）',
        '提前结清、退费与征信影响的具体规则',
        '目前是否已经实际放款（放款前后解约成本不同）',
      ]);
    } else if (pack == 'three-party') {
      push(['学校就业办对解约的办理要求与流程', '单位能够证明的实际招聘支出', '升学、考公、参军等情形是否可免责解约']);
    } else if (pack == 'probation' && !packs.contains('labor')) {
      push(['这份文件的合同期限、试用期工资和转正工资（试用期规则需要这三项才能完整核对）']);
    }
  }
  if (list.isEmpty) push(['合同主体、金额、附件和口头承诺仍要人工核对']);
  ctx.pending = list.take(5).toList();
}

String makeOneLiner(
  List<Finding> items,
  Map<Verdict, int> counts,
  List<String> packs,
) {
  Finding? top;
  for (final it in items) {
    if (it.verdict != Verdict.green) {
      top = it;
      break;
    }
  }
  final red = counts[Verdict.red] ?? 0;
  final yellow = counts[Verdict.yellow] ?? 0;
  final gray = counts[Verdict.gray] ?? 0;
  String s;
  if (red > 0) {
    s = '红线 $red 处，最重的是「${top!.short}」；先要求删改，再谈签不签。';
  } else if (yellow > 0) {
    s = '没有红线，但有 $yellow 处不利条款，最重的是「${top!.short}」；能谈，别默认接受。';
  } else if (gray > 0) {
    s = '没有明显红线；$gray 件事要确认，先看「${top!.short}」。';
  } else {
    final appliedIds = <String>{};
    for (final p in packs) {
      appliedIds.addAll(packRules[p] ?? const <String>[]);
    }
    final appliedCount = ruleLibrary
        .where((r) => appliedIds.contains(r.id))
        .length;
    if (appliedCount == 0) {
      s = '本次没有可执行的规则包，未核对任何规则；没扫到 ≠ 没风险。';
    } else {
      final uncovered = ruleLibrary
          .where((r) => !appliedIds.contains(r.id))
          .toList();
      final names = uncovered.take(4).map((r) => r.name).join('、');
      final more = uncovered.length > 4 ? '等 ${uncovered.length} 类' : '';
      final labels = packs
          .map((k) => packLabel[k])
          .whereType<String>()
          .join(' / ');
      s = '本次只核对 $appliedCount 类规则（$labels），未覆盖$names$more；没扫到 ≠ 没风险。';
    }
  }
  return s.length > 110
      ? '${s.substring(0, 108)}…'
      : (top != null && s.length > 60 ? '${s.substring(0, 58)}…' : s);
}

String firstLinesOf(String text, [int n = 5]) => text
    .split('\n')
    .map((s) => s.trim())
    .where((s) => s.isNotEmpty)
    .take(n)
    .join('\n');

bool hasLaborSignals(String text, String primaryKey) {
  final t = text;
  final head = firstLinesOf(t, 5);
  if (RegExp(r'(不构成劳动关系|不属于劳动关系|实习关系|劳务关系)').hasMatch(t) &&
      !RegExp(r'劳动合同').hasMatch(head)) {
    return false;
  }
  if (RegExp(r'劳动合同').hasMatch(head)) return true;
  if (primaryKey == 'three-party' || hasThreePartySignals(text)) return false;
  if (RegExp(r'(甲方[（(]用人单位[）)]|乙方[（(]劳动者[）)])').hasMatch(t)) return true;
  return RegExp(r'劳动者').hasMatch(t) &&
      RegExp(r'用人单位').hasMatch(t) &&
      RegExp(r'(工资|劳动报酬|社会保险|试用期|解除|离职|竞业限制|服务期)').hasMatch(t);
}

bool hasInternSignals(String text) {
  final t = text;
  final head = firstLinesOf(t, 5);
  if (RegExp(r'(实习协议|实习合同|实习协议书)').hasMatch(head)) return true;
  if (RegExp(r'(实习单位|实习学生|实习生)').hasMatch(t)) return true;
  return RegExp(r'实习').hasMatch(head) &&
      RegExp(r'(学校|补贴|实习证明|实习内容)').hasMatch(t);
}

bool hasLoanSignals(String text) {
  final t = text;
  if (RegExp(r'(培训贷|教育分期|分期贷款|培训分期|助学贷款|学费分期)').hasMatch(t)) return true;
  return RegExp(r'(培训|教育|课程|学员|学费|技能)').hasMatch(t) &&
      RegExp(r'(分期|贷款|放款|还款|月供|平台服务费|征信)').hasMatch(t);
}

bool hasPrepaySignals(String text) {
  final t = text;
  if (hasLoanSignals(t)) return false;
  if (RegExp(r'劳动合同|劳动者|用人单位').hasMatch(t) &&
      RegExp(r'(工资|社会保险|试用期|解除|竞业限制|服务期)').hasMatch(t)) {
    return false;
  }
  return RegExp(r'(课程|课时|培训班|学员|学费|课程费)').hasMatch(t) &&
      RegExp(r'(退费|退款|不退|不予退还|开课|上课|课时|转班|迁址|预付|预交|一次性支付)').hasMatch(t);
}

bool hasThreePartySignals(String text) {
  final t = text;
  final head = firstLinesOf(t, 5);
  if (RegExp(r'(三方协议|三方协议书|毕业生就业协议|就业协议书)').hasMatch(head)) return true;
  return RegExp(r'毕业生').hasMatch(head) &&
      RegExp(r'学校').hasMatch(t) &&
      RegExp(r'用人单位').hasMatch(t);
}

List<String> resolveRulePacks(String text, String primaryKey) {
  final packs = <String>[];
  void add(String? key) {
    if (key != null && key != 'other' && !packs.contains(key)) packs.add(key);
  }

  if (primaryKey == 'labor') {
    add('labor');
  } else if (primaryKey == 'intern') {
    add('intern');
  } else if (primaryKey == 'loan') {
    add('loan');
  } else if (primaryKey == 'prepay') {
    add('prepay');
  } else if (primaryKey == 'three-party') {
    add('three-party');
  } else if (primaryKey == 'probation') {
    add('probation');
  }
  final laborSignals = hasLaborSignals(text, primaryKey);
  if (laborSignals) add('labor');
  final trialLike = RegExp(r'(试用期|试岗期|见习期|适应期)').hasMatch(text);
  if (trialLike && (primaryKey != 'intern' || laborSignals)) add('probation');
  if (primaryKey == 'other' && trialLike && packs.isEmpty) add('probation');
  if (hasInternSignals(text)) add('intern');
  if (hasLoanSignals(text)) add('loan');
  if (hasPrepaySignals(text)) add('prepay');
  if (hasThreePartySignals(text)) add('three-party');
  return packs;
}

Analysis analyzeContract(String text, {String? docType}) {
  final clean = text.replaceAll(RegExp(r'\r\n?'), '\n').trim();
  final detectedKey = detectDocType(clean);
  final forcedKey = docType != null && docLabel.containsKey(docType)
      ? docType
      : null;
  var primaryKey = forcedKey ?? detectedKey;
  var packs = resolveRulePacks(clean, primaryKey);
  if (primaryKey == 'other' && packs.isNotEmpty) {
    String? promoted;
    for (final k in packs) {
      if (k == 'labor' ||
          k == 'intern' ||
          k == 'three-party' ||
          k == 'loan' ||
          k == 'prepay' ||
          k == 'probation') {
        promoted = k;
        break;
      }
    }
    if (promoted != null) {
      primaryKey = promoted;
      packs = resolveRulePacks(clean, primaryKey);
    }
  }
  final ctx = _Ctx(
    clean,
    extractClauses(clean),
    primaryKey,
    detectedKey,
    packs,
  );
  if (packs.contains('probation')) {
    runR1(ctx);
    runR2(ctx);
    runR3(ctx);
  }
  if (packs.contains('labor')) {
    runR4(ctx);
    runR5(ctx);
    runR6(ctx);
    runR7(ctx);
    runR11(ctx);
    runR12(ctx);
    runR13(ctx);
    runR14(ctx);
    runR15(ctx);
    runR16(ctx);
    runR17(ctx);
    runR18(ctx);
    runR19(ctx);
    runR21(ctx);
    runR22(ctx);
    runR23(ctx);
    runR24(ctx);
    runR25(ctx);
    runR26(ctx);
    runR27(ctx);
    runR28(ctx);
    runR29(ctx);
    runR30(ctx);
    runLaborGreens(ctx);
  }
  if (packs.contains('intern')) {
    runR10(ctx);
    runR27(ctx);
    runR29(ctx);
    runR30(ctx);
  }
  if (packs.contains('loan')) {
    runR9(ctx);
    runR20(ctx);
    runLoanConsumer(ctx);
  }
  if (packs.contains('prepay')) {
    if (!packs.contains('loan')) runLoanConsumer(ctx, consumerOnly: true);
    runPrepayFallback(ctx);
  }
  if (packs.contains('three-party')) {
    runR8(ctx);
    runR29(ctx);
    runR30(ctx);
  }
  ctx.items.sort((a, b) {
    final orderDiff = verdictOrder[a.verdict]! - verdictOrder[b.verdict]!;
    if (orderDiff != 0) return orderDiff;
    final lossDiff = b.loss - a.loss;
    if (lossDiff != 0) return lossDiff > 0 ? 1 : -1;
    return a.seq - b.seq;
  });
  final counts = <Verdict, int>{
    Verdict.red: 0,
    Verdict.yellow: 0,
    Verdict.gray: 0,
    Verdict.green: 0,
  };
  for (final it in ctx.items) {
    counts[it.verdict] = (counts[it.verdict] ?? 0) + 1;
  }
  buildPending(ctx);
  final numbered = ctx.clauses.where((cl) => cl.numbered).length;
  final substantive = ctx.clauses
      .where(
        (cl) =>
            (cl.kind == 'clause' || cl.kind == 'body') &&
            cl.body.trim().length >= 6,
      )
      .toList();
  final firstLine = clean.split('\n').first.trim();
  final title =
      firstLine.length <= 30 &&
          RegExp(r'(合同|协议)').hasMatch(firstLine) &&
          !RegExp(r'^第[一二三四五六七八九十百零〇\d]+条').hasMatch(firstLine)
      ? firstLine
      : (docLabel[ctx.docType] ?? '协议');
  final red = counts[Verdict.red] ?? 0;
  final yellow = counts[Verdict.yellow] ?? 0;
  final gray = counts[Verdict.gray] ?? 0;
  return Analysis(
    docKey: ctx.docType,
    docType: docLabel[ctx.docType] ?? '其他',
    detectedDocKey: detectedKey,
    detectedDocType: docLabel[detectedKey] ?? '其他',
    forced: forcedKey != null,
    packs: ctx.packs,
    packLabels: ctx.packs.map((k) => packLabel[k]).whereType<String>().toList(),
    extraPackLabels: ctx.packs
        .where((k) => k != ctx.docType)
        .map((k) => packLabel[k])
        .whereType<String>()
        .toList(),
    title: title,
    clauses: ctx.clauses,
    numberedCount: numbered,
    clauseCount: substantive.length,
    charCount: clean.length,
    items: ctx.items,
    counts: counts,
    pending: ctx.pending,
    oneLiner: makeOneLiner(ctx.items, counts, ctx.packs),
    topVerdict: red > 0
        ? Verdict.red
        : yellow > 0
        ? Verdict.yellow
        : gray > 0
        ? Verdict.gray
        : Verdict.green,
    insufficient: substantive.length < 3,
  );
}
